window.ORFEO_DATA_BUNDLE = {"chapters":{"_doc":"Struttura in 7 capitoli (da story.json v0.1), obiettivi con 3 livelli di suggerimento, indizi (evidence = prova utile al finale La Luce), i 17 ruoli di Orfeo. debugStart = stato di partenza per la modalità sviluppatore.","title":"Giuseppe & Kiki — Il Segreto di Orfeo","titleScene":"c1_lungarno","start":{"scene":"c1_studio","at":[1000,900],"before":["@give:coltellino","@give:moneta","@cutscene:intro","@chapter:1"]},"chapters":[{"id":1,"title":"La stanza murata","location":"Firenze","date":"Ottobre 2026","relationship":"Sconosciuti","core":"Scoperta del materiale ORFEO e primo incontro nell'archivio.","summary":"Un computer recuperato da una stanza murata in via de' Bardi contiene la cartella ORFEO. Beps segue una catena di schede all'Archivio Storico e incontra Kiki, che possiede una fotografia identica. Nel buio del deposito, una voce li avverte di lasciar perdere.","epigraph":"«I muri non mentono. Le persone sì, i muri no.»","debugStart":{"scene":"c1_studio","kiki":false,"switchLocked":true,"items":["coltellino","moneta"]}},{"id":2,"title":"La donna nella fotografia","location":"Parigi","date":"Novembre 2026","relationship":"Alleati","core":"Una fotografia del 1967 contiene la stessa figura presente nel 1944.","summary":"Allo Studio Marchetti, Beps e Kiki sovrappongono le foto del 1944 e del 1967: la donna col cappello è nello stesso punto, ma non è la stessa persona. Il medaglione, appoggiato su una mappa cifrata, indica Roma.","epigraph":"«La verità sta sempre un passo fuori dall'inquadratura.» — Ada Morel","debugStart":{"scene":"c2_gare","items":["coltellino","moneta","usb","foto1944","scheda_o17","busta_e","medaglione","promemoria"],"flags":{"met_kiki":true,"kiki_named":true,"pdf_open":true,"lista_seen":true,"kiki_nonna":true},"stats":{"fiducia":2,"legame":3,"conoscenza":6},"solved":["c1_frammenti","c1_catena"]}},{"id":3,"title":"Diciassette nomi","location":"Roma","date":"Novembre 2026","relationship":"Amici","core":"La LISTA_17 collega Orfeo a eventi del 1944.","summary":"Nella Biblioteca Teodosiana, Don Ilario — il Libraio — apre la Sala dei Cassetti. Diciassette emblemi, una targa in latino, e la Lista completa. Poi gli uomini del Notaio, e una fuga che si può fare solo in due.","epigraph":"«Primus ducit, secunda meminit, tertius traicit, ultimus verba custodit.»","debugStart":{"scene":"c3_piazza","items":["coltellino","moneta","usb","foto1944","scheda_o17","busta_e","medaglione","foto1967","lettera_ada"],"flags":{"met_kiki":true,"kiki_named":true,"pdf_open":true,"lista_seen":true,"retro_1967":true,"helene_met":true},"stats":{"fiducia":4,"legame":8,"conoscenza":14},"solved":["c1_frammenti","c1_catena","c2_sovrapposizione","c2_mappa"]}},{"id":4,"title":"Il ritorno","location":"Firenze","date":"Dicembre 2026","relationship":"Legame crescente","core":"Luoghi già visitati assumono un nuovo significato e uno dei due scompare.","summary":"L'ufficio di Beps è stato devastato e Kiki sparisce. Da solo, Beps ricompone il Sigillo di Orfeo sul banco di un orafo del Ponte Vecchio e attraversa il Corridoio Vasariano fino alla Grotta di Boboli, dove il Notaio lo aspetta.","epigraph":"«Le chiavi aprono, ma soprattutto chiudono.» — Oreste Neri","debugStart":{"scene":"c4_studio","items":["coltellino","moneta","usb","foto1944","medaglione","foto1967","lettera_ada","chiave_ottone","lista17","sigillo_a"],"flags":{"met_kiki":true,"kiki_named":true,"pdf_open":true,"lista_seen":true,"lista_full":true,"helene_met":true,"fuga_ok":true,"ilario_libraio":true,"erased_role_known":true},"stats":{"fiducia":6,"legame":12,"conoscenza":22},"solved":["c1_frammenti","c1_catena","c2_sovrapposizione","c2_mappa","c3_cassetti"]}},{"id":5,"title":"La porta d'Oriente","location":"Istanbul","date":"Dicembre 2026","relationship":"Primo bacio","core":"La ricerca conduce al vero scopo dell'organizzazione.","summary":"Selim, il Traduttore, rivela che il Registro non è mai stato diviso: le metà erano chiavi. Sotto un caravanserraglio, quattro anelli di bronzo indicano la strada di casa. Sul tetto dell'Han, Istanbul accende le sue luci.","epigraph":"«Chi entra in due, esce in due.»","debugStart":{"scene":"c5_galata","items":["coltellino","moneta","usb","foto1944","medaglione","foto1967","lettera_ada","chiave_ottone","lista17","sigillo","nastro"],"flags":{"met_kiki":true,"kiki_named":true,"pdf_open":true,"lista_seen":true,"lista_full":true,"helene_met":true,"fuga_ok":true,"varano_named":true,"kiki_liberata":true,"erased_role_known":true},"stats":{"fiducia":9,"legame":16,"conoscenza":28},"solved":["c1_frammenti","c1_catena","c2_sovrapposizione","c2_mappa","c3_cassetti","c4_sigillo"]}},{"id":6,"title":"Orfeo","location":"Parigi","date":"Gennaio 2027","relationship":"Coppia","core":"Identità e struttura della società segreta vengono finalmente rivelate.","summary":"Hélène confessa di essere Euridice. Il nastro del 1967 rivela un voto falsificato. Nell'archivio parigino, due falsi portano la firma della stessa famiglia. E nel suo studio, il Notaio racconta di un nonno delatore e di una nonna che salvò trenta persone.","epigraph":"«La cenere è l'unica cosa che non accusa nessuno.» — Aurelio Varano","debugStart":{"scene":"c6_pont_neuf","items":["coltellino","moneta","usb","foto1944","medaglione","foto1967","lettera_ada","chiave_ottone","lista17","sigillo","nastro"],"flags":{"met_kiki":true,"kiki_named":true,"pdf_open":true,"lista_seen":true,"lista_full":true,"helene_met":true,"fuga_ok":true,"varano_named":true,"kiki_liberata":true,"selim_traduttore":true,"bacio":true,"erased_role_known":true},"stats":{"fiducia":11,"legame":22,"conoscenza":34},"clues":["camera_firenze"],"solved":["c1_frammenti","c1_catena","c2_sovrapposizione","c2_mappa","c3_cassetti","c4_sigillo","c5_anelli"]}},{"id":7,"title":"L'ultima chiave","location":"Firenze","date":"Gennaio 2027","relationship":"Fiducia completa","core":"Enigma finale cooperativo. Epilogo: anni dopo, Giuseppe e Kiki si sposano.","summary":"Sotto la stanza murata, oltre il terzo gradino, la Camera di Orfeo si apre solo in due. All'alba, sul Lungarno, il Registro aspetta una decisione.","epigraph":"«Non voltarti.»","debugStart":{"scene":"c7_cantiere","items":["coltellino","moneta","usb","foto1944","medaglione","foto1967","lettera_ada","chiave_ottone","lista17","sigillo","nastro"],"flags":{"met_kiki":true,"kiki_named":true,"pdf_open":true,"lista_seen":true,"lista_full":true,"helene_met":true,"fuga_ok":true,"varano_named":true,"kiki_liberata":true,"selim_traduttore":true,"bacio":true,"helene_euridice":true,"nastro_ascoltato":true,"varano_doubt":true,"erased_role_known":true,"coop":5},"stats":{"fiducia":15,"legame":27,"conoscenza":40},"clues":["promemoria_1966","lista_parziale","stessa_donna","lista_completa","camera_firenze","verbale_falso","falso_1944","lina_varano","voce_ada"],"solved":["c1_frammenti","c1_catena","c2_sovrapposizione","c2_mappa","c3_cassetti","c4_sigillo","c5_anelli","c6_cronologia"]}}],"objectives":{"o1_esamina":{"chapter":1,"text":"Esamina il materiale recuperato dal cantiere.","hints":["Il vecchio computer sulla scrivania è il motivo per cui sei qui stasera.","Usa il vecchio computer (clic sinistro, o tocco).","Clicca sul computer sopra la scrivania: Beps copierà i file sulla chiavetta."]},"o1_cantiere":{"chapter":1,"text":"Raggiungi Sandro al cantiere di via de' Bardi. Con un caffè.","hints":["Sandro ha chiesto esplicitamente un caffè.","La macchinetta del caffè dell'ufficio funziona. Poi esci dalla porta, verso il Lungarno e il cantiere (a destra).","Usa la macchinetta del caffè, esci, attraversa il Lungarno verso destra fino al cantiere e dai il caffè a Sandro."]},"o1_caffe_sandro":{"chapter":1,"text":"Porta un caffè a Sandro.","hints":["Sandro non apre la stanza senza caffè.","L'ufficio ha una macchinetta. È a due passi.","Torna in ufficio (a sinistra del Lungarno), usa la macchinetta, poi dai il caffè a Sandro (trascinalo su di lui o usa «Mostra un oggetto»)."]},"o1_stanza":{"chapter":1,"text":"Esplora la stanza murata.","hints":["Guarda bene i muri e i mobili: qualcuno ci ha lavorato fino al 1998.","L'armadio metallico è chiuso con un lucchetto arrugginito. E nel muro c'è una crepa.","Usa il coltellino sull'armadio per prendere i frammenti. Prendi il mezzo medaglione dalla crepa."]},"o1_frammenti":{"chapter":1,"text":"Ricomponi i frammenti del documento.","hints":["I frammenti sono nell'inventario. Si possono esaminare o stendere sul tavolo.","Esamina i frammenti (clic destro / pressione lunga nell'inventario) oppure usali sul tavolo impolverato.","Apri il puzzle e ordina le strisce: intestazione, poi «L'acqua è arrivata…», «si sono salvati…», «e portate le copie…», «del catalogo…», «al rimando in rosso…»."]},"o1_archivio":{"chapter":1,"text":"Cerca la scheda O-1 all'Archivio Storico.","hints":["L'Archivio Storico è sul Lungarno, tra l'ufficio e il cantiere.","Il cassetto O del catalogo è chiuso. L'archivista può aprirlo, se le mostri un buon motivo.","Parla con l'archivista e mostrale il promemoria ricomposto (o la Foto 1944) con «Mostra un oggetto»."]},"o1_catena":{"chapter":1,"text":"Segui la catena del catalogo O fino in fondo.","hints":["Lo schedario è a sinistra in sala. Si parte da O-1.","Segui il rimando rosso di ogni scheda; dove l'acqua l'ha cancellato, leggi la nota a matita.","O-1 → O-6 → O-11 → O-4 → O-15 → O-17."]},"o1_deposito":{"chapter":1,"text":"Controlla il ripiano 17 del deposito, con Kiki.","hints":["La porta del deposito è in fondo a destra nella sala di lettura.","Kiki ha la tessera: ora la porta è aperta.","Entra nel deposito e usa il ripiano 17."]},"o1_luce":{"chapter":1,"text":"Al buio: riaccendi la luce.","hints":["Beps non vede niente. Kiki ricorda dov'è il quadro elettrico.","Passa a Kiki (Tab o il ritratto piccolo in alto a destra).","Come Kiki, usa il quadro elettrico vicino all'ingresso, a sinistra."]},"o1_caffe":{"chapter":1,"text":"Parlatene con calma, al Caffè delle Logge.","hints":["Il caffè è sul Lungarno.","Esci dall'Archivio: il Caffè delle Logge è la porta rossa a destra.","Torna sul Lungarno ed entra nel Caffè delle Logge."]},"o1_parlare":{"chapter":1,"text":"Confrontate quello che sapete. Aprite il PDF. Riunite il medaglione.","hints":["Parla con Kiki: ha molte cose da raccontare e qualcosa da darti.","Il PDF si apre col portatile di Kiki e la chiave scritta sulla Scheda O-17. Il medaglione ha due metà.","Usa la chiavetta USB sul portatile; la password è la data dell'alluvione (4 novembre 1966, targa sul Lungarno). Chiedi a Kiki del medaglione e combina le due metà. Poi chiedile «E adesso?»."]},"o1_medaglione":{"chapter":1,"text":"Riunisci le due metà del medaglione.","hints":["Hai due metà nell'inventario.","Gli oggetti si possono combinare: seleziona uno, poi clicca sull'altro.","Seleziona «Mezzo medaglione», poi clicca su «Mezzo medaglione di Kiki»."]},"o2_marchetti":{"chapter":2,"text":"Trova lo Studio Marchetti, in rue des Archives.","hints":["La busta del ripiano 17 aveva un indirizzo.","Dalla stazione prendi il taxi verso la Senna, poi prosegui verso il Marais.","Gare → Quai (a destra) → rue des Archives (a destra)."]},"o2_foto1967":{"chapter":2,"text":"Chiedi a Hélène della fotografia del 1967.","hints":["Hélène è nello studio.","Parla con Hélène: il tema «La fotografia del 1967».","Scegli «La fotografia del 1967» nel dialogo con Hélène."]},"o2_sovrapponi":{"chapter":2,"text":"Stampa il negativo e sovrapponi le due fotografie.","hints":["Nella camera oscura c'è un ingranditore. Nello studio c'è un banco luminoso.","Usa il negativo sull'ingranditore. Poi usa le foto sul banco luminoso.","Camera oscura → negativo sull'ingranditore. Studio → foto sul banco luminoso → allinea i crocini rossi."]},"o2_mappa":{"chapter":2,"text":"Trova una mappa su cui appoggiare il medaglione.","hints":["Ada comprava libri da un bouquiniste sul quai. Hélène lo conosce.","Monsieur Albert, sul Quai des Grands-Augustins, vende un libretto speciale a chi sa rispondere.","Chiedi ad Albert di Orfeo e rispondi «Gluck». Esamina il libretto: dentro c'è la mappa."]},"o2_libretto":{"chapter":2,"text":"Esamina il libretto di Monsieur Albert.","hints":["Tra le pagine c'è qualcosa.","Esamina il libretto nell'inventario (clic destro / pressione lunga).","Esamina il libretto: ottieni la mappa cifrata. Poi combinala col medaglione."]},"o2_mappa_usa":{"chapter":2,"text":"Appoggia il medaglione sulla mappa.","hints":["Hai entrambi gli oggetti.","Combina il medaglione con la mappa cifrata.","Combina medaglione e mappa; ruota finché la tacca punta la stella rossa (indizio sul retro della foto del '67)."]},"o2_casa":{"chapter":2,"text":"Cerca tra le cose di Ada.","hints":["Qualcuno ha frugato prima di voi, ma non dappertutto.","Kiki conosce i nascondigli di sua nonna.","Come Kiki, usa il mobile del grammofono."]},"o3_biblioteca":{"chapter":3,"text":"Entra nella Biblioteca Teodosiana.","hints":["Il portone è a destra, dietro le colonne.","Usa il portone della biblioteca.","Clicca sul portone con la scritta BIBLIOTECA."]},"o3_sala":{"chapter":3,"text":"Entra nella Sala dei Cassetti.","hints":["Don Ilario ha la chiave. Ora te l'ha data.","La porta SALA XVII è in fondo a destra.","Usa la porta della Sala dei Cassetti."]},"o3_cassetti":{"chapter":3,"text":"Apri i diciassette cassetti.","hints":["Il mobile è bloccato e la targa è in latino.","Beps può sbloccare il fermo sul fianco del mobile con il coltellino. Kiki può tradurre la targa.","Coltellino sul fianco del mobile (Beps), guarda la targa (Kiki), poi apri: lira, luna, àncora, foglia."]},"o3_fuga":{"chapter":3,"text":"Fuggite dalla Sala dei Cassetti.","hints":["La porta principale è bloccata. C'è un cancello e una grata.","La grata si svita con il coltellino. Il condotto è troppo stretto per Beps.","Coltellino sulla grata, poi passa a Kiki e usa la grata."]},"o3_condotto":{"chapter":3,"text":"Kiki deve passare nel condotto.","hints":["Solo Kiki ci passa.","Passa a Kiki (Tab).","Come Kiki, usa la grata."]},"o3_leva":{"chapter":3,"text":"Apri il cancello dall'altra parte.","hints":["Kiki è nel passaggio di servizio. C'è una leva.","Usa la leva come Kiki.","Kiki: usa la leva e tienila."]},"o3_passa":{"chapter":3,"text":"Beps deve passare il cancello, finché Kiki tiene la leva.","hints":["Kiki non può lasciare la leva.","Passa a Beps.","Come Beps, usa il cancello di servizio."]},"o3_scala":{"chapter":3,"text":"Raggiungete la scala retrattile.","hints":["È troppo in alto per uno solo.","In due ci si arriva.","Usa la scala retrattile con entrambi presenti."]},"o3_esci":{"chapter":3,"text":"Uscite in cortile.","hints":["La scala è giù.","Usala.","Usa la scala retrattile."]},"o3_osteria":{"chapter":3,"text":"All'Osteria da Fiorella, con calma.","hints":["L'osteria è a destra del cortile.","Esci a destra.","Uscita a destra del cortile."]},"o3_lista":{"chapter":3,"text":"Leggete insieme la Lista dei 17.","hints":["Sedetevi al vostro tavolo.","Usa il tavolo (o la Lista dei 17 sul tavolo).","Clicca sul tavolo a destra."]},"o4_studio":{"chapter":4,"text":"Aspetta Kiki. Intanto cerca quello che i ladri non hanno trovato.","hints":["Guarda bene l'ufficio devastato.","C'è un pacco che non era lì prima, e un biglietto sulla scrivania.","Prendi il pacco di Sandro vicino al plastico del palazzo."]},"o4_ponte":{"chapter":4,"text":"Trova Kiki: ricomponi il Sigillo e raggiungi la Grotta di Boboli dal Corridoio Vasariano.","hints":["La lista diceva dove sono i quattro frammenti: Roma, il muro, la Banca del Giglio, il ponte che non cadde.","Sul Ponte Vecchio c'è la bottega di chi custodisce le chiavi. La Banca del Giglio è oltre il ponte; ti serve la chiave d'ottone.","Mostra la Lista dei 17 a Mastro Neri. In banca chiedi la cassetta 17: il titolare è «Euridice». Poi chiedi a Neri il banco e la porticina."]},"o4_sigillo":{"chapter":4,"text":"Ricomponi il Sigillo sul banco di Mastro Neri.","hints":["Servono tutti e quattro i frammenti.","Usa il banco da orafo.","Bordo: ORFEO in alto a sinistra, poi NON, VOL, TARTI in senso orario; l'arco di ogni pezzo verso l'esterno."]},"o4_chiave_corridoio":{"chapter":4,"text":"Chiedi a Mastro Neri della porticina del Corridoio.","hints":["La porticina è sul ponte, a destra.","Mastro Neri ha la chiave.","Parla con Neri: «La porta del Corridoio»."]},"o4_corridoio":{"chapter":4,"text":"Attraversa il Corridoio Vasariano fino alla porta di Orfeo.","hints":["La porticina è a destra sul ponte.","In fondo al corridoio c'è una porta con un incavo rotondo.","Usa il Sigillo sulla porta di Orfeo."]},"o4_partenza":{"chapter":4,"text":"Uscite dalla grotta, verso il giardino di Boboli.","hints":["L'uscita è a destra.","Usa l'uscita verso il giardino.","Clicca sull'uscita a destra."]},"o5_bazar":{"chapter":5,"text":"Trova il Traduttore, «al Bazar, dove vendono il tempo».","hints":["Il Bazar è a destra del molo.","Nel Bazar, la bottega dell'antiquario è a destra.","Molo → Bazar → bottega di Selim."]},"o5_camera":{"chapter":5,"text":"Scendete nella Camera degli Anelli, sotto il Büyük Valide Han.","hints":["Servono luce e una leva.","Selim presta la lanterna; Emre, il ragazzo del tè, ha un piede di porco.","Chiedi la lanterna a Selim e il piede di porco a Emre. Al Han, Beps usa il piede di porco sulla botola."]},"o5_botola_beps":{"chapter":5,"text":"Beps deve forzare la botola.","hints":["Serve forza: tocca a Beps.","Passa a Beps.","Come Beps, usa il piede di porco sulla botola."]},"o5_scendi":{"chapter":5,"text":"Scendete nella cisterna.","hints":["Serve la lanterna.","Usa la botola con la lanterna nell'inventario.","Usa la botola."]},"o5_anelli":{"chapter":5,"text":"Fai girare gli anelli.","hints":["Al centro va il medaglione. Sul suo retro ci sono quattro simboli.","Luna, lira, onda, chiave: dall'anello interno all'esterno. Comincia dall'esterno.","Esterno ⚷, terzo ≈, secondo ♪, interno ☾."]},"o5_tetto":{"chapter":5,"text":"Sali con Kiki sul tetto dell'Han.","hints":["Dal cortile dell'Han, a sinistra, una scala sale sul tetto.","Siediti sul muretto.","Han → scala a sinistra → tetto."]},"o6_helene":{"chapter":6,"text":"Andate da Hélène, allo Studio Marchetti.","hints":["È a sinistra del Pont Neuf.","Prendi l'uscita verso il Marais.","Pont Neuf → uscita a sinistra."]},"o6_nastro":{"chapter":6,"text":"Ascoltate il nastro di Orfeo.","hints":["Il Revox è sotto lo studio.","La sala di proiezione è dietro la tenda.","Usa il nastro sul registratore a bobine."]},"o6_archivio":{"chapter":6,"text":"Rimettete in ordine l'archivio di Orfeo.","hints":["Passage des Libraires, a destra del Pont Neuf.","Usa il tavolo dei documenti.","Ordina per data e segna come falsi la lettera del Ponte Vecchio e il verbale del '67."]},"o6_cronologia":{"chapter":6,"text":"Ricostruite la cronologia dei documenti di Orfeo.","hints":["Il tavolo è al centro.","Ordina per data, poi trova due contraddizioni.","Vedi i suggerimenti dentro l'enigma."]},"o6_varano":{"chapter":6,"text":"Affrontate il Notaio nel suo studio.","hints":["L'Île de la Cité è in basso, dal Pont Neuf.","Prendi l'uscita in basso.","Pont Neuf → uscita in basso."]},"o6_catacombe":{"chapter":6,"text":"Attraversate le catacombe fino alla stazione.","hints":["L'uscita è a destra.","Usa l'uscita verso Denfert.","Uscita a destra."]},"o7_scendi":{"chapter":7,"text":"Trova la via per scendere sotto la stanza murata.","hints":["«L'acqua arrivò al terzo gradino.»","I gradini a sinistra. Beps sa riconoscere un vuoto.","Usa i gradini come Beps."]},"o7_lastra":{"chapter":7,"text":"Sollevate insieme la lastra del terzo gradino.","hints":["Pesa troppo per uno solo.","Serve che ci siate tutti e due.","Usa di nuovo i gradini."]},"o7_galleria":{"chapter":7,"text":"Scendete nella galleria.","hints":["La scala è aperta.","Usa i gradini.","Usa i gradini."]},"o7_paratoia":{"chapter":7,"text":"Superate il canale.","hints":["C'è una paratoia con una ruota.","Solo Beps ha la forza di girarla.","Come Beps, usa la ruota della paratoia."]},"o7_camera":{"chapter":7,"text":"Entrate nella Camera di Orfeo.","hints":["L'arco in fondo a destra.","Usa l'arco.","Clicca sull'arco."]},"o7_meccanismo":{"chapter":7,"text":"Aprite il meccanismo: «Il Sigillo apre. La Voce chiama. I Nomi rispondono. La Chiave chiude.»","hints":["Ogni passo ha il suo lato: alcuni sono di Beps, altri di Kiki. L'ordine è scritto sull'iscrizione.","Beps: Sigillo nell'incavo. Kiki: nastro nel grammofono, poi la Ruota dei Nomi. Infine la chiave… ma «nessuno resta solo».","Sigillo (Beps) → nastro (Kiki) → Ruota: arco ⌒ (Kiki) → leva (Kiki, tenerla) → chiave d'ottone (Beps)."]},"o7_leva":{"chapter":7,"text":"«…ma solo se nessuno resta solo.»","hints":["C'è una leva dalla parte di Kiki.","Kiki deve tenere la leva mentre Beps gira la chiave.","Kiki: usa la leva. Poi passa a Beps e usa la chiave d'ottone sulla serratura."]},"o7_chiave":{"chapter":7,"text":"Gira la chiave, mentre Kiki tiene la leva.","hints":["Tocca a Beps.","Passa a Beps.","Come Beps, usa la chiave d'ottone sulla serratura."]},"o7_registro":{"chapter":7,"text":"Prendete il Registro.","hints":["Lo scrigno al centro.","Usa lo scrigno.","Clicca sullo scrigno."]},"o7_decidi":{"chapter":7,"text":"Decidete cosa fare del Registro.","hints":["Varano vi aspetta sotto il lampione.","Parla con Varano: puoi chiedere di ogni possibilità prima di scegliere.","Parla con Varano e scegli «Abbiamo deciso»."]},"o6_parla_varano":{"chapter":6,"text":"Parla con il Notaio.","hints":["Varano è dietro la scrivania. Ma guardati intorno: sulla scrivania c'è una lettera.","Prendi la lettera sulla scrivania, poi parla con Varano di sua nonna.","Raccogli la lettera di Lina, poi parla con Varano di tutti i temi e salutalo."]}},"clues":{"cartella_orfeo":{"chapter":1,"title":"La cartella ORFEO","text":"Tre file su un computer del 1998 trovato in una stanza murata: FIRENZE_1944.jpg, LISTA_17.pdf (cifrato), NON_APRIRE.wav."},"voce_registrata":{"chapter":1,"title":"La voce","text":"«Se qualcuno sta ascoltando questo messaggio, significa che abbiamo fallito. Chi trova questa voce trovi anche l'altra metà. E non si volti.»"},"alluvione":{"chapter":1,"title":"4 novembre 1966","text":"La targa sul Lungarno ricorda il giorno dell'alluvione di Firenze."},"donna_lungarno":{"chapter":1,"title":"La donna sotto il portico","text":"Abito nero, cappello a falda larga. Sparita lasciando una moneta da 500 lire."},"terzo_gradino":{"chapter":1,"title":"Il terzo gradino","text":"Nella stanza murata, il terzo gradino è più chiaro degli altri."},"mezzo_medaglione":{"chapter":1,"title":"Mezzo medaglione","text":"Trovato in una crepa del muro: metà di un medaglione d'ottone con mezza lira."},"promemoria_1966":{"chapter":1,"evidence":true,"title":"Promemoria del 1966","text":"«Murate la stanza e portate le copie a Parigi. Si parte dalla scheda O-1.» Firmato E."},"signora_francese":{"chapter":1,"title":"La signora francese","text":"Nel 1998 una signora francese col cappello pagò in contanti per «risistemare la cantina»."},"barcaiolo":{"chapter":1,"title":"Il Barcaiolo","text":"Renzo Ricci, padre dell'archivista, traghettava persone sull'Arno nel 1944."},"testimone":{"chapter":1,"title":"La Testimone","text":"Nelle foto di Orfeo la donna col cappello sta sempre nello stesso punto. «C'era sempre, e non c'era mai.»"},"scheda_o17":{"chapter":1,"title":"Scheda O-17","text":"Provenienza Parigi 1967; deposito, ripiano 17. «La chiave è il giorno in cui l'acqua arrivò al terzo gradino.»"},"busta_parigi":{"chapter":1,"title":"Studio Marchetti","text":"Busta del 1967: Studio Marchetti, 12 rue des Archives, Parigi."},"voce_buio":{"chapter":1,"title":"La voce nel buio","text":"«Lasciate stare Orfeo. È per il vostro bene.»"},"uomo_grigio":{"chapter":1,"title":"L'uomo col cappotto grigio","text":"Ci osservava sul Lungarno. Conosce i nostri nomi."},"varano_finanzia":{"chapter":1,"evidence":true,"title":"Il finanziatore","text":"Il notaio Aurelio Varano finanzia il restauro del palazzo della stanza murata."},"cinquecento_lire":{"chapter":1,"title":"500 lire","text":"La donna col cappello lascia sempre una moneta da 500 lire."},"varano_lira":{"chapter":1,"title":"Il portachiavi","text":"Varano ha una lira sul portachiavi."},"lista_parziale":{"chapter":1,"evidence":true,"title":"LISTA_17 (parziale)","text":"I · Orfeo, la Guida (lira). II · Euridice, la Testimone (luna). VI · Il Barcaiolo (àncora). XIV · Il Libraio (foglia)."},"foto_kiki":{"chapter":1,"title":"La foto di Kiki","text":"Kiki possiede la stessa fotografia del 1944. Sua nonna la teneva nel messale."},"voce_ada":{"chapter":1,"evidence":true,"title":"La voce è di Ada","text":"La voce registrata è quella di Ada Morel, la nonna di Kiki."},"medaglione_intero":{"chapter":1,"title":"Il medaglione intero","text":"Una lira, una tacca sul bordo, dieci fori a spirale. Uno strumento, non un gioiello."},"foto_1967":{"chapter":2,"title":"Parigi 1967","text":"La stessa donna col cappello, nello stesso punto della foto del 1944."},"stella_tacca":{"chapter":2,"title":"«La stella guida la tacca»","text":"Scritto da Ada sul retro della foto del 1967."},"dodici_marzo":{"chapter":2,"title":"12 marzo","text":"La Dame au chapeau comprava Gluck ogni 12 marzo. Un anniversario."},"mappa_cifrata":{"chapter":2,"title":"La mappa cifrata","text":"Una carta d'Italia con lettere in cerchio e una stella rossa."},"stessa_donna":{"chapter":2,"evidence":true,"title":"Non è la stessa donna","text":"Nel 1944 è Lucia Morel, nel 1967 Ada Morel. Stesso punto, stesso cappello. Un ruolo, non una persona."},"teodosiana":{"chapter":2,"title":"TEODOSIANA","text":"Il medaglione sulla mappa indica la Biblioteca Teodosiana di Roma."},"lettera_ada":{"chapter":2,"title":"La lettera di Ada","text":"«Non avere paura di chi porta l'altra metà. Non voltarti indietro.»"},"cappello_ada":{"chapter":2,"title":"Il cappello di Ada","text":"Il cappello di Ada è a Parigi. Chi lo portava sul Lungarno?"},"donna_roma":{"chapter":3,"title":"Il balcone","text":"La donna col cappello su un balcone di Roma."},"targa_latina":{"chapter":3,"title":"La targa","text":"«Il primo guida, la seconda ricorda, il terzo traghetta, l'ultimo custodisce le parole.»"},"libraio":{"chapter":3,"title":"Il Libraio","text":"Don Ilario Cesti è il Ruolo XIV."},"euridice_ruolo":{"chapter":3,"title":"Euridice è un ruolo","text":"La Testimone si eredita: cappello, medaglione, posto nelle fotografie."},"ruolo_ponte":{"chapter":3,"title":"Il Ponte","text":"Il Ruolo XVII decideva quando il Registro sarebbe stato reso pubblico. Abolito nel 1967."},"lista_completa":{"chapter":3,"evidence":true,"title":"La Lista dei 17","text":"Tutti i ruoli e i loro custodi dal 1944. Il XVII raschiato."},"cancellato":{"chapter":3,"evidence":true,"title":"Cancellato due volte","text":"Il volto graffiato nella foto e il nome raschiato nella lista sono la stessa persona."},"sigillo_quattro":{"chapter":3,"title":"Il Sigillo diviso","text":"Roma, cassetta 17 della Banca del Giglio, il muro dove l'acqua si fermò, il ponte che non cadde."},"frammento_cantiere":{"chapter":4,"title":"Il frammento del muro","text":"Sandro ha trovato il terzo frammento del Sigillo nella stanza murata."},"sms_federica":{"chapter":4,"title":"«Federica»","text":"Kiki firma «Federica» solo quando qualcosa non va. La foto mostra la Grotta del Buontalenti."},"corridoio":{"chapter":4,"title":"Il Corridoio","text":"Mastro Neri custodiva la chiave della porticina del Corridoio Vasariano."},"nastro_orfeo":{"chapter":4,"title":"Il nastro","text":"Bobina: «ORFEO — Parigi, 12.III.1967 — Seduta straordinaria»."},"sigillo_intero":{"chapter":4,"title":"Il Sigillo","text":"ORFEO · NON · VOLTARTI."},"registro":{"chapter":4,"title":"Il Registro","text":"Ottant'anni di nomi: salvatori, salvati e delatori."},"istanbul":{"chapter":4,"title":"Istanbul","text":"Ada andava a Istanbul ogni dicembre. «A comprare tappeti.»"},"retro_medaglione":{"chapter":5,"title":"Il retro del medaglione","text":"Dal centro al bordo: luna, lira, onda, chiave."},"donna_istanbul":{"chapter":5,"title":"Il Bazar","text":"La donna col cappello, a Istanbul. Il cappello di Ada è a Parigi."},"traduttore":{"chapter":5,"title":"Il Traduttore","text":"Selim Aydın, Ruolo XVI. Sua madre accoglieva i fuggiaschi del 1944."},"tetto":{"chapter":5,"title":"Il tetto dell'Han","text":"«È bello sapere che si può attraversare.»"},"camera_firenze":{"chapter":5,"evidence":true,"title":"La Camera di Orfeo","text":"È sotto la stanza murata di via de' Bardi, oltre il terzo gradino."},"helene_euridice":{"chapter":6,"title":"Hélène è Euridice","text":"Ha ereditato il ruolo da Ada nel 2019. Ma non era lei a Istanbul."},"verbale_falso":{"chapter":6,"evidence":true,"title":"Il voto falsificato","text":"Nel 1967 Euridice e il Ponte votarono contro. Ettore Varano li verbalizzò come «assenti»."},"guido_sarti":{"chapter":6,"title":"Guido Sarti","text":"Il Ponte. Il volto graffiato nella foto del 1944."},"falso_1944":{"chapter":6,"evidence":true,"title":"Il falso del Ponte Vecchio","text":"Una lettera del 1944 dice che il Ponte Vecchio crollò: è falsa, autenticata dal Notaio."},"bruno_varano":{"chapter":6,"evidence":true,"title":"Bruno Varano","text":"Il nonno di Aurelio: delatore nel 1944."},"lina_varano":{"chapter":6,"evidence":true,"title":"Lina Varano","text":"La nonna di Aurelio: nascose trenta persone. Nel Registro, tra i Barcaioli."},"lina":{"chapter":6,"title":"La lettera di Lina","text":"«Siamo stati entrambi Varano. Scegli tu quale essere.»"},"camera_due":{"chapter":6,"title":"In due","text":"La Camera di Orfeo si apre solo in due."},"iscrizione_camera":{"chapter":7,"title":"L'iscrizione","text":"«Il Sigillo apre. La Voce chiama. I Nomi rispondono. La Chiave chiude — ma solo se nessuno resta solo.»"},"diciottesimo":{"chapter":7,"title":"Il Diciottesimo","text":"«Il diciottesimo nome appartiene a chi non si volta da solo.»"},"donna_alba":{"chapter":7,"title":"All'alba","text":"Una donna col cappello sul Ponte Vecchio. Si volta, e se ne va."}},"roles":[{"name":"Orfeo","emblem":"♪","desc":"la Guida. Emblema: la lira.","early":true,"holders":"Pietro Lanzoni (1944) · Marco Testi (1967) · vacante dal 2003"},{"name":"Euridice","emblem":"☾","desc":"la Testimone, che ricorda. Emblema: la luna.","early":true,"holders":"Lucia Morel (1944) · Ada Morel (1967) · █████ · Hélène Marchetti (2019)"},{"name":"Il Cartografo","emblem":"✦","desc":"traccia le vie. Emblema: la stella.","holders":"Ernesto Valli (1944) · Sandra Valli (1972)"},{"name":"L'Archivista","emblem":"▤","desc":"ordina le carte. Emblema: lo schedario.","holders":"Bice Ferroni (1944) · vacante"},{"name":"Il Tipografo","emblem":"✎","desc":"falsifica per salvare. Emblema: la penna.","holders":"Anonimo (1944)"},{"name":"Il Barcaiolo","emblem":"⚓","desc":"colui che traghetta. Emblema: l'àncora.","early":true,"holders":"Renzo Ricci (1944) · Lina Varano, «barcaiola di cantina» (1944)"},{"name":"La Sarta","emblem":"✂","desc":"nasconde nei vestiti. Emblema: le forbici.","holders":"Ines Bardi (1944)"},{"name":"Il Medico","emblem":"✚","desc":"cura senza registrare. Emblema: la croce.","holders":"Dott. Aldo Segre (1944)"},{"name":"Il Fotografo","emblem":"◉","desc":"vede e ricorda. Emblema: l'occhio.","holders":"Jacques Marchetti (1955)"},{"name":"Il Campanaro","emblem":"♜","desc":"dà i segnali. Emblema: la torre.","holders":"Fra' Teodoro (1944)"},{"name":"Il Notaio","emblem":"⚖","desc":"autentica. Emblema: la bilancia.","holders":"Bruno Varano (1944) · Ettore Varano (1967) · Aurelio Varano (1999)"},{"name":"La Maestra","emblem":"☼","desc":"insegna i nomi nuovi. Emblema: il sole.","holders":"Maria Pace (1944)"},{"name":"Il Ferroviere","emblem":"⚙","desc":"conosce gli orari. Emblema: la ruota.","holders":"Gino Fabbri (1944)"},{"name":"Il Libraio","emblem":"❧","desc":"custodisce le parole. Emblema: la foglia.","early":true,"holders":"Ilario Cesti (1952)"},{"name":"Il Custode delle Chiavi","emblem":"⚷","desc":"apre e chiude. Emblema: la chiave.","holders":"Oreste Neri (1944) · Tommaso Neri (1967) · Stefano Neri"},{"name":"Il Traduttore","emblem":"⇄","desc":"fa passare le parole. Emblema: le due frecce.","holders":"Nermin Aydın (1944) · Selim Aydın (1989)"},{"name":"Il Ponte","emblem":"⌒","desc":"decide quando il Registro uscirà alla luce. Emblema: l'arco.","erased":true,"holders":"Guido Sarti (1944) — abolito nel 1967"}]},"scenes":{"_doc":"Scene. Coordinate nel mondo logico 1920x1080. walk = poligono camminabile; walkFor = poligono per personaggio; walkIf = poligoni alternativi condizionali. hotspots: rect [x,y,w,h], at = punto d'interazione, look/use/talk/exit/items, only = solo un personaggio. art = oggetto disegnato proceduralmente se manca lo sfondo reale.","scenes":{"c1_studio":{"bg":"assets/backgrounds/bg_studio_architettura_firenze_clean.jpg","name":"Ufficio della ditta","place":"Oltrarno · Firenze · ottobre 2026","chapter":1,"music":"firenze","ambience":"rain","art":{"type":"interior","time":"evening","wall":"#5e4a36","floor":"#3e2c1e","horizon":680,"wallpaper":true,"light":[{"x":560,"y":470,"r":560,"c":"#ffcc88","a":0.45},{"x":1250,"y":330,"r":380,"c":"#9fb4ff","a":0.18}],"layers":[{"k":"rug","x":640,"y":860,"w":640,"h":150,"c":"#5a2a22"},{"k":"lamp","x":1000,"y":420,"w":80,"h":280},{"k":"plant","x":1660,"y":560,"w":130,"h":200}]},"walk":[[600,1080],[1760,1080],[1760,960],[1600,950],[1500,860],[1350,790],[850,780],[820,820],[700,860]],"scale":[790,0.62,1080,1],"spawn":{"default":[1000,930],"from_c1_lungarno":[1650,1010,"l"]},"switch":false,"firstEnter":["beps[worried]: Doveva essere un intervento di dieci minuti. Copiare un disco, controllare due cartelle e tornare a casa.","beps[think]: Poi ho visto quella cartella: <b>ORFEO</b>. E improvvisamente dieci minuti sono diventati una pessima idea.","@objective:o1_esamina"],"hotspots":[{"id":"scrivania","name":"Scrivania","rect":[100,600,750,300],"art":{"k":"desk","items":false},"at":[760,930],"look":"La mia scrivania. Sepolta sotto tre portatili da riparare, due tazze e un computer che non è mio.","use":"Non ho tempo per mettere in ordine. Non ho mai tempo per mettere in ordine."},{"id":"computer","name":"Vecchio computer","rect":[500,490,160,140],"art":{"k":"computer"},"at":[760,900],"face":"l","look":"Il computer recuperato dal cantiere. Vecchio, polveroso e stranamente ancora leggibile. Un Pentium del '98, a occhio.","use":[{"if":"!flag.pc_read","do":["@anim:use","Vediamo. Una sola cartella: ORFEO. Dentro, tre file.","beps[think]: FIRENZE_1944.jpg, LISTA_17.pdf, NON_APRIRE.wav.","La cartella contiene tre file. Il PDF è cifrato. La foto è del 1944. L’audio…",{"choice":[{"label":"Apri NON_APRIRE.wav","line":"beps[skeptical]: Con un nome così, è praticamente un invito."},{"label":"Guarda prima la foto","line":"beps: Prima la foto. Quattro uomini, una donna col cappello… e un volto graffiato via. Poi l'audio."}]},"@sfx:tape","narr: Voce registrata: «Se qualcuno sta ascoltando questo messaggio, significa che abbiamo fallito.»","narr: «Il registro è al sicuro, per ora. Chi trova questa voce trovi anche l'altra metà. E non si volti.»","beps[surprised]: …","beps: Copio tutto sulla chiavetta. E stampo la foto, prima che questo rottame decida di morire.","@give:usb","@give:foto1944","@flag:pc_read","@clue:cartella_orfeo","@clue:voce_registrata","@wait:400","@sfx:phone","beps[surprised]: Il telefono. Alle nove di sera.","@anim:phone","sandro: Beps? Sono Sandro, del cantiere di via de' Bardi. Senta… nella stanza murata c'è dell'altro. Un armadio. E una cosa nel muro.","sandro: Io lì dentro da solo non ci torno. Di notte si sente l'acqua.","beps: Arrivo. Tienimi il caffè in caldo.","sandro: Il caffè lo porti tu, Beps. La macchinetta del cantiere è morta con l'ultimo papa.","@person:sandro","@objective:o1_cantiere"]},{"do":["Ho già copiato tutto sulla chiavetta. Meglio non lasciare altre tracce."]}],"items":{"usb":"La chiavetta è già piena di tutto quello che c'era. Il PDF resta cifrato."}},{"id":"stampante","name":"Stampante","rect":[1150,520,220,160],"art":{"k":"machine","c":"#5a5a5e"},"at":[1200,860],"look":"La stampante dell'ufficio. Inceppa un foglio su tre per principio.","use":[{"if":"flag.pc_read","do":["Ha già stampato la foto. Non tentiamo la sorte."]},{"do":["Non ho niente da stampare. Ancora."]}]},{"id":"finestra","name":"Finestra","rect":[500,90,770,400],"art":{"k":"window","time":"rain","rain":true},"look":"Piove sull'Oltrarno. Di là dal fiume, la cupola si vede appena. Firenze sotto la pioggia sembra una fotografia vecchia."},{"id":"foto_nonno","name":"Foto del nonno","rect":[1300,440,70,90],"art":{"k":"frame","c":"#b8a888","overlay":true},"look":["Nonno Gigi, muratore, davanti al cantiere della Biblioteca Nazionale dopo l'alluvione del '66. Mi ha lasciato le 500 lire e la mania di smontare le cose per capire come funzionano.","Diceva: «I muri non mentono. Le persone sì, i muri no.»"]},{"id":"macchinetta","name":"Macchinetta del caffè","rect":[1480,560,190,170],"art":{"k":"machine","c":"#2e2e32"},"at":[1480,900],"look":"La macchinetta a cialde. Produce qualcosa di marrone e caldo. Il resto è fede.","use":[{"if":"flag.sandro_caffe","do":["Sandro ha già avuto il suo caffè. Uno al giorno è sufficiente, per la salute di tutti."]},{"if":"item.caffe","do":["Ne ho già uno in mano. Non sono un bar."]},{"if":"flag.pc_read","do":["@anim:use","@sfx:mechanism","Un caffè per Sandro. Bicchierino di carta, coperchio, preghiera.","@give:caffe"]},{"do":["Un caffè adesso? No, prima il computer."]}]},{"id":"plastico","name":"Plastico","rect":[290,510,180,90],"art":{"k":"building","c":"#d8ccb0","lit":1},"at":[700,950],"look":["Il plastico del palazzo di via de' Bardi, in scala 1:50. L'hanno fatto i tecnici della ditta: io ho solo fatto il rendering 3D.","Guardandolo adesso: tra il secondo e il terzo pilastro c'è un vuoto che nel rilievo laser non c'era. La stanza murata."]},{"id":"lavagna","name":"Bacheca","rect":[1380,160,320,370],"art":{"k":"corkboard"},"look":"Password dei clienti, schemi di rete e fili rossi. Sembra la bacheca di un serial killer, ma è solo il piano dei backup."},{"id":"libreria","name":"Libreria","rect":[0,80,480,520],"art":{"k":"shelves","c":"#4a3526"},"at":[700,950],"face":"l","look":"Manuali di Linux, un libro sulla crittografia, un Palladio lasciato dai tecnici e tre gialli di Simenon. Le priorità di un informatico.","use":"Cerco qualcosa su un'organizzazione chiamata Orfeo… Niente. Solo l'Orfeo di Monteverdi, e non credo c'entri."},{"id":"cestino","name":"Cestino","rect":[1360,800,110,140],"art":{"k":"crate","c":"#6a6a6a"},"look":"Un mouse rotto, un cavo VGA e la mia dignità del lunedì mattina."},{"id":"porta","name":"Porta dell'ufficio","rect":[1740,110,180,880],"art":{"k":"door","label":"UFFICIO"},"at":[1700,1000],"exit":{"to":"c1_lungarno","if":"flag.pc_read","else":["Prima dovrei capire cosa sto cercando."]}}]},"c1_lungarno":{"bg":"assets/backgrounds/bg_lungarno_notte_01.jpg","name":"Lungarno","place":"Firenze · sera di pioggia","chapter":1,"music":"firenze","ambience":"rain","fx":["rain"],"art":{"type":"exterior","time":"rain","horizon":600,"ground":"#34312e","skyline":200,"light":[{"x":1330,"y":330,"r":420,"c":"#ffd890","a":0.35}],"layers":[{"k":"river","x":0,"y":560,"w":620,"h":160},{"k":"bridge","x":40,"y":470,"w":540,"h":150,"shops":true},{"k":"building","x":620,"y":160,"w":520,"h":660,"c":"#8a7458","seed":"a"},{"k":"building","x":1140,"y":120,"w":780,"h":700,"c":"#9a8466","seed":"b"},{"k":"railing","x":0,"y":690,"w":620,"h":70}]},"walk":[[120,1080],[1920,1080],[1920,900],[1600,780],[1300,665],[1100,645],[1000,655],[790,770]],"scale":[650,0.42,1080,0.95],"spawn":{"default":[640,990],"from_c1_studio":[330,1040,"r"],"from_c1_cantiere":[1780,1010,"l"],"from_c1_archivio":[1700,930,"l"],"from_c1_caffe":[1540,830,"l"]},"firstEnter":["Il Lungarno, sotto la pioggia. Il cantiere è in fondo a via de' Bardi, oltre l'Archivio."],"enter":[{"if":"flag.deposito_done && !flag.varano_lungarno","do":["@flag:varano_lungarno","kiki[worried]: Beps. Sotto il lampione. Non girarti di scatto.","beps[surprised]: Cappotto grigio scuro, sciarpa bordeaux. Ci sta guardando.","varano: …","kiki: Se ne va. Senza fretta. Come chi sa che ci rivedrà.","@person:varano","@clue:uomo_grigio"]}],"npcs":[{"id":"varano_lamp","char":"varano","name":"L'uomo col cappotto grigio","x":900,"y":775,"dir":"l","if":"flag.deposito_done && !flag.varano_lungarno_gone","look":{"beps":"Ci guarda da sotto il lampione. Non ha l'aria di uno che aspetta l'autobus.","kiki":"Lo stesso uomo del buio, ci scommetto. Ha la voce di chi è abituato a essere ascoltato."},"talk":"varano_c1"}],"hotspots":[{"id":"arno","name":"Arno","rect":[0,560,640,200],"art":null,"look":{"beps":"L'Arno gonfio di pioggia. Nel '66 è salito fino alle targhe sui muri. I fiorentini non lo dimenticano.","kiki":"Il fiume ha la memoria lunga. Come gli archivisti."}},{"id":"ponte","name":"Ponte Vecchio","rect":[500,490,540,80],"look":{"beps":"Il Ponte Vecchio. Nel '44 i tedeschi fecero saltare tutti i ponti di Firenze tranne questo. Nessuno sa bene perché.","kiki":"L'unico ponte sopravvissuto alla notte del 4 agosto 1944. Sopra ci passa il Corridoio Vasariano."}},{"id":"targa","name":"Targa dell'alluvione","rect":[1612,420,70,90],"art":{"k":"sign","label":"4·XI·66","c":"#3a3430"},"look":{"beps":["«Il 4 novembre 1966 l'acqua d'Arno arrivò a questa altezza.» Sopra la mia testa. Di parecchio.","@clue:alluvione"],"kiki":["La targa dell'alluvione: 4 novembre 1966. Mia nonna diceva che quel giorno Firenze imparò a nuotare.","@clue:alluvione"]}},{"id":"lampione","name":"Lampione","rect":[780,160,80,580],"art":{"k":"streetlamp"},"look":{"beps":"Un lampione in ghisa. Sotto la pioggia fa un alone dorato che i pittori del lungarno venderebbero a cinquanta euro.","kiki":"Bella luce. Ottima per farsi notare, pessima per nascondersi."}},{"id":"panchina","name":"Panchina","rect":[400,880,280,110],"art":{"k":"bench"},"at":[560,1010],"look":{"beps":"Una panchina bagnata. L'ultima volta che mi ci sono seduto ho passato il pomeriggio a spiegare a un turista che il Duomo non è in vendita.","kiki":"Bagnata. Come tutto il resto."},"use":{"beps":"Mi siederei, ma ho una pessima sensazione e i pantaloni buoni.","kiki":"Non ora. Ma tienila a mente: qui si vedono bene i tramonti."}},{"id":"edicola","name":"Locandina dell'edicola","rect":[1040,400,80,110],"art":{"k":"sign","label":"MISTERO IN OLTRARNO","c":"#e8e0c8"},"look":{"beps":"L'edicola di Gianni. Chiusa. Sul cartellone: «MISTERO IN OLTRARNO: TROVATA STANZA MURATA». Fantastico. Adesso lo sa tutta Firenze.","kiki":"«Mistero in Oltrarno». Ecco come ti ho trovato, Beps. Come ti ha trovato chiunque."}},{"id":"donna","name":"Figura sotto il portico","rect":[1262,470,80,150],"art":{"k":"figure","hat":true,"c":"#0a0a0c"},"if":"flag.pc_read && !flag.woman_1","look":"Una donna sotto il portico. Abito nero, cappello a falda larga. Come quella della foto.","use":["@walk:1250,690","beps[surprised]: Era lì. Adesso non c'è più.","Solo l'odore di tè e pioggia. E una moneta da 500 lire sul gradino.","@flag:woman_1","@clue:donna_lungarno","@person:donna","@stat:conoscenza+1"]},{"id":"porta_archivio","name":"Archivio Storico","rect":[1690,240,180,570],"art":{"k":"door","label":"ARCHIVIO","c":"#3a2a1c"},"at":[1720,930],"exit":{"to":"c1_archivio","if":"flag.pc_read","else":["L'Archivio Storico. Prima voglio vedere cosa c'è nella stanza murata."]}},{"id":"porta_caffe","name":"Caffè delle Logge","rect":[1530,320,90,390],"art":{"k":"door","label":"CAFFÈ","c":"#4a1f1a"},"at":[1540,830],"exit":{"to":"c1_caffe","if":"flag.deposito_done","else":{"beps":["Il Caffè delle Logge. Dopo, forse. Adesso ho da fare."],"kiki":["Dopo. Prima il deposito."]}}},{"id":"verso_studio","name":"Verso l'ufficio","rect":[0,880,150,200],"art":{"k":"exit"},"exit":{"to":"c1_studio"},"arrow":"l"},{"id":"verso_cantiere","name":"Via de' Bardi (cantiere)","rect":[1830,880,90,200],"art":{"k":"exit"},"exit":{"to":"c1_cantiere"},"arrow":"r"}]},"c1_cantiere":{"name":"La stanza murata","place":"Cantiere di via de' Bardi · notte","chapter":1,"music":"mystery","ambience":"underground","fx":["dust",{"k":"light","x":980,"y":120,"w":420,"h":900}],"art":{"type":"underground","time":"night","wall":"#4a3a2e","floor":"#2a221c","horizon":690,"dark":0.6,"light":[{"x":1090,"y":260,"r":520,"c":"#ffe0a0","a":0.45}],"layers":[{"k":"brickwall","x":1180,"y":200,"w":420,"h":490,"hole":true},{"k":"crate","x":1640,"y":760,"w":160,"h":120,"label":"DITTA"}]},"walk":[[60,1060],[1880,1060],[1860,760],[340,740],[60,800]],"scale":[740,0.74,1060,1],"spawn":{"default":[1700,900,"l"],"from_c1_lungarno":[1740,920,"l"]},"npcs":[{"id":"sandro","x":1500,"y":880,"dir":"l","talk":"sandro","look":"Sandro, il capocantiere. Ha l'aria di uno che vorrebbe essere ovunque tranne che qui."}],"firstEnter":["sandro: Beps! Grazie a Dio. Hai portato il caffè?",{"if":"item.caffe","do":["beps: Ho portato il caffè."],"else":["beps: Il… caffè. Certo. Il caffè."]}],"hotspots":[{"id":"telo","name":"Telo sulla breccia","rect":[1180,200,420,490],"art":{"k":"curtain","c":"#3a4a5a"},"if":"!flag.sandro_ok","look":"Un telo cerato copre la breccia nel muro. Sandro ci sta davanti come un buttafuori.","use":["sandro: Ehi ehi ehi. Prima il caffè, poi la stanza. È la regola del cantiere."]},{"id":"breccia","name":"Breccia nel muro","rect":[1260,260,280,360],"if":"flag.sandro_ok","look":["La breccia aperta da Sandro. Il muro è del '66, malta di calce e mattoni di recupero.","Ma l'intonaco interno è più recente. Qualcuno è entrato e ha richiuso. Più di una volta."]},{"id":"armadio","name":"Armadio metallico","rect":[330,290,230,400],"art":{"k":"safe","c":"#4a5058"},"if":"flag.sandro_ok","at":[460,820],"look":"Un armadio d'acciaio da ufficio, anni Novanta. Lucchetto arrugginito.","use":[{"if":"flag.armadio_open && !flag.got_frammenti","do":["@anim:pickup","Dentro ci sono sei strisce di carta strappata. Le prendo.","@give:frammenti"]},{"if":"flag.armadio_open","do":["Vuoto, a parte la ruggine e una ragnatela molto ben progettata."]},{"do":["Il lucchetto è arrugginito. Col coltellino potrei forzarlo."]}],"items":{"coltellino":[{"if":"!flag.armadio_open","do":["@anim:use","@sfx:mechanism","Un po' di leva… ecco. Il lucchetto cede con un lamento.","Dentro: sei strisce di carta strappata e bagnata. Qualcuno le ha strappate in fretta.","@flag:armadio_open","@give:frammenti","@objective:o1_frammenti"]},{"do":["È già aperto."]}],"frammenti":["@puzzle:c1_frammenti"]}},{"id":"tavolo","name":"Tavolo impolverato","rect":[620,580,380,160],"art":{"k":"desk","items":false,"c":"#4a3a2a"},"if":"flag.sandro_ok","at":[800,850],"look":"Nella polvere, il rettangolo pulito di dove stava il computer. Accanto, l'impronta di una tazza. Qualcuno ci lavorava.","use":[{"if":"item.frammenti","do":["Stendo i frammenti sul tavolo.","@puzzle:c1_frammenti"]},{"do":["Ci appoggerei qualcosa, se avessi qualcosa da appoggiare."]}],"items":{"frammenti":["Stendo i frammenti sul tavolo.","@puzzle:c1_frammenti"]}},{"id":"crepa","name":"Crepa nel muro","rect":[700,300,70,100],"art":{"k":"hole"},"if":"flag.sandro_ok && !flag.got_medaglione_b","at":[740,800],"look":"Una crepa nel muro. Dentro luccica qualcosa.","use":["@anim:pickup","Infilo le dita… ecco. Metà di un medaglione d'ottone. Spezzato di netto.","@give:medaglione_b","@clue:mezzo_medaglione"]},{"id":"lira","name":"Simbolo inciso","rect":[880,210,90,90],"art":{"k":"symbol","c":"#c9a85a","a":0.5},"if":"flag.sandro_ok","col":"sym_1"},{"id":"bolla","name":"Foglio sul tavolo","rect":[940,590,60,45],"art":{"k":"papers","overlay":true},"if":"flag.sandro_ok","col":"doc_01"},{"id":"gradini","name":"Gradini","rect":[60,700,260,260],"art":{"k":"stairs","down":true,"c":"#5a4a3a"},"at":[300,900],"look":["Tre gradini scendono verso il pavimento della stanza. Il terzo è più chiaro degli altri, come se fosse stato lavato… o allagato.","@clue:terzo_gradino"]},{"id":"macchie","name":"Segni dell'acqua","rect":[60,520,260,110],"look":"Una linea scura corre sul muro a un metro da terra. Il segno dell'alluvione. L'acqua è arrivata fin qui."},{"id":"impalcatura","name":"Impalcatura","rect":[1640,120,260,560],"art":{"k":"scaffold"},"look":"Il ponteggio della ditta. Collaudato, certificato e, alle dieci di sera, molto inquietante."},{"id":"lampada","name":"Lampada da cantiere","rect":[1040,160,100,160],"art":{"k":"hanglamp"},"look":"Una lampada alogena appesa a un filo. Fa ombre lunghissime."},{"id":"uscita","name":"Verso il Lungarno","rect":[1840,700,80,360],"art":{"k":"exit"},"exit":{"to":"c1_lungarno"},"arrow":"r"}]},"c1_archivio":{"name":"Archivio Storico — Sala di lettura","place":"Firenze","chapter":1,"music":"firenze","ambience":"room","fx":[{"k":"light","x":760,"y":60,"w":420,"h":900},"dust"],"art":{"type":"interior","time":"evening","wall":"#6a5440","floor":"#4a3424","horizon":650,"beams":true,"light":[{"x":600,"y":560,"r":300,"c":"#c8ffb0","a":0.25},{"x":1200,"y":500,"r":500,"c":"#ffd8a0","a":0.3}],"layers":[{"k":"shelves","x":1000,"y":120,"w":560,"h":530,"c":"#3e2c1e","seed":"arch"},{"k":"table","x":400,"y":700,"w":420,"h":200,"c":"#5a3e28"}]},"walk":[[60,1080],[1880,1080],[1830,700],[1080,690],[1040,960],[600,1000],[80,1000]],"scale":[690,0.72,1080,1],"spawn":{"default":[240,1040,"r"],"from_c1_lungarno":[180,1040,"r"],"from_c1_corridoio":[1120,740,"l"]},"npcs":[{"id":"archivista","x":1420,"y":880,"dir":"l","talk":"archivista","look":{"beps":"L'archivista. Occhiali sulla punta del naso, cardigan verde, lo sguardo di chi ha visto passare tre generazioni di studenti maleducati.","kiki":"Ottavia Ricci. Mi ha fatto la tessera di ricerca tre anni fa. Mi chiama ancora «signorina restauratrice»."}},{"id":"kiki_lettrice","char":"kiki_npc","name":"Una lettrice","x":1150,"y":770,"dir":"r","if":"!flag.met_kiki","look":"Una donna al tavolo di lettura. Giacca marrone, borsa di cuoio a tracolla, occhiali. Finge di leggere un registro del Seicento. Lo tiene al contrario.","talk":"kiki_pre"}],"hotspots":[{"id":"bancone","name":"Bancone","rect":[1010,430,240,170],"art":{"k":"counter","c":"#5a3a24"},"look":{"beps":"Il bancone delle richieste. Moduli in triplice copia. Una matita legata con lo spago.","kiki":"Il regno di Ottavia. Ci ho passato ore."}},{"id":"schedario","name":"Schedario del catalogo","rect":[0,320,285,360],"art":{"k":"cabinet","c":"#6b4a2e","cols":4,"rows":6},"at":[300,1040],"face":"l","look":{"beps":"Lo schedario del catalogo. Cassetti dalla A alla Z. Il cassetto «O» ha un lucchetto, l'unico.","kiki":"Il catalogo O. Ufficialmente non esiste."},"use":[{"if":"puzzle.c1_catena","do":["La catena l'ho già seguita fino in fondo. La scheda O-17 è con me."]},{"if":"flag.catalogo_ok","do":["@anim:use","@sfx:drawer","@puzzle:c1_catena"]},{"do":["Il cassetto O è chiuso a chiave. Dovrei chiedere all'archivista."]}]},{"id":"finestre","name":"Finestre alte","rect":[1450,0,330,520],"art":{"k":"window","time":"rain","rain":true},"look":{"beps":"Finestre altissime. La pioggia ci scivola sopra come su un acquario.","kiki":"Luce da nord. Perfetta per leggere, pessima per le mani fredde."}},{"id":"ritratto","name":"Ritratto","rect":[1095,128,120,220],"art":{"k":"painting","c":"#3a3020","seed":"rit"},"look":{"beps":"Il fondatore dell'Archivio, 1852. Ha la faccia di uno che ha appena trovato una scheda fuori posto.","kiki":"Francesco Bonaini. Ha inventato l'archivistica moderna. Nessuno lo sa, ma ha anche inventato il modo di guardare male gli studenti."}},{"id":"lampada","name":"Lampada verde","rect":[500,420,150,110],"art":{"k":"lamp"},"look":{"beps":"Una lampada da banchiere. Ogni archivio del mondo ne ha almeno una. È la legge.","kiki":"La lampada verde. Mi rilassa più del tè."}},{"id":"carrello","name":"Carrello dei libri","rect":[1245,530,70,110],"art":{"k":"boxes","label":"DA RICOLLOCARE"},"look":{"beps":"Un carrello di fascicoli «da ricollocare». Alcuni ci sono dal 2003, a giudicare dalla polvere.","kiki":"Il carrello della vergogna. Ogni archivio ne ha uno."}},{"id":"orologio","name":"Orologio","rect":[1250,150,80,100],"art":{"k":"clock"},"look":{"beps":"Le nove e quaranta. Chiudono alle dieci. Ottavia mi ha fatto un favore a lasciarmi entrare.","kiki":"È indietro di quattro minuti da sempre. Ottavia dice che è «il tempo dell'archivio»."}},{"id":"cartello","name":"Cartello","rect":[1680,520,170,60],"art":{"k":"sign","label":"SILENZIO","c":"#2a2a2a"},"look":{"beps":"«SILENZIO». In maiuscolo. Quindi è urlato.","kiki":"L'ironia di un cartello che urla silenzio."}},{"id":"foto_alluvione","name":"Fotografia incorniciata","rect":[900,610,70,60],"art":{"k":"frame","c":"#8a7a5a","overlay":true},"col":"photo_02"},{"id":"porta_deposito","name":"Porta del deposito","rect":[950,280,90,150],"art":{"k":"door","label":"DEPOSITO","c":"#3a2a1a"},"at":[1100,720],"exit":{"to":"c1_corridoio","if":"flag.deposito_ok","else":{"beps":["«Solo personale autorizzato.» Io sono autorizzato a malapena a parcheggiare in Oltrarno."],"kiki":["Ho la tessera, ma devo prima dirlo a Ottavia."]}}},{"id":"uscita","name":"Uscita","rect":[0,640,80,440],"art":{"k":"exit"},"exit":{"to":"c1_lungarno","if":"!flag.met_kiki || flag.deposito_done","else":{"beps":["Non adesso: il ripiano 17 ci aspetta."],"kiki":["Il deposito prima, Beps."]}},"arrow":"l"}]},"c1_corridoio":{"bg":"assets/backgrounds/bg_archivio_firenze_room_01.jpg","name":"Deposito — Corridoio dei ripiani","place":"Archivio Storico · Firenze","chapter":1,"music":"tension","ambience":"room","fx":[{"k":"night","if":"flag.blackout"},{"k":"dark","if":"flag.blackout"}],"art":{"type":"interior","time":"night","wall":"#4e4438","floor":"#2e2820","horizon":640,"wainscot":false,"vanish":980,"light":[{"x":980,"y":160,"r":420,"c":"#e8f0ff","a":0.3}],"layers":[{"k":"shelves","x":40,"y":120,"w":520,"h":560,"paper":true,"seed":"d1"},{"k":"shelves","x":600,"y":200,"w":300,"h":440,"paper":true,"seed":"d2"},{"k":"hanglamp","x":940,"y":0,"w":80,"h":150}]},"walk":[[100,1080],[1520,1080],[1520,1010],[1040,1010],[990,760],[880,640],[760,640],[700,760],[440,770],[380,860],[100,1010]],"scale":[640,0.5,1080,1],"spawn":{"default":[300,1030,"r"],"from_c1_archivio":[260,1040,"r"]},"firstEnter":["kiki: Ripiano 17. In fondo a destra. Ottavia ci dà dieci minuti.","beps: Dieci minuti. Ho già sentito questa frase stasera."],"hotspots":[{"id":"ripiano","name":"Ripiano 17","rect":[1545,100,375,900],"art":{"k":"shelves","c":"#5a4a3a","paper":true,"seed":"17"},"at":[1460,1040],"if":"!flag.blackout","look":{"beps":"Il ripiano 17. Faldoni dagli anni Trenta ai Novanta. Uno solo è legato con un nastro rosso.","kiki":"Ripiano 17. Il faldone col nastro rosso: carta francese, la riconosco dal colore."},"use":[{"if":"!flag.ripiano_aperto","do":["@anim:pickup","@sfx:page","beps: Il faldone col nastro rosso. Dentro… una busta. E una microcassetta.","kiki[surprised]: «Studio Marchetti, 12 rue des Archives, Paris.» Una busta del 1967.","@give:busta_e","@clue:busta_parigi","@flag:ripiano_aperto","@wait:300","@sfx:door","@flag:blackout","@refresh","narr: Le luci si spengono.","beps[scared]: Kiki?","kiki[worried]: Sono qui. Non muoverti.","varano: Lasciate stare Orfeo. È per il vostro bene.","narr: Passi. Una porta che si chiude, lontano.","beps[worried]: Chi era? Io non vedo nemmeno le mie mani.","kiki[determined]: Il quadro elettrico è accanto all'ingresso, l'ho visto entrando. Ci vado io. Tu sta' fermo.","@unlockswitch","@objective:o1_luce"]},{"do":["Il faldone è vuoto, ormai. A parte la polvere del '67."]}]},{"id":"quadro","name":"Quadro elettrico","rect":[408,340,56,130],"art":{"k":"safe","c":"#6a6a6a"},"at":[470,800],"only":"kiki","onlyMsg":{"beps":["Al buio non trovo niente. Kiki ha visto dov'è il quadro: tocca a lei."]},"look":{"beps":"Il quadro elettrico. Da qui non lo vedo nemmeno.","kiki":"Il quadro elettrico. L'interruttore generale è abbassato."},"use":[{"if":"flag.blackout","do":["@anim:use","@sfx:click","@unflag:blackout","@refresh","kiki: Fatto. Luce.","beps[surprised]: Grazie. Davvero.","kiki[skeptical]: L'interruttore non è scattato da solo. Qualcuno l'ha abbassato.","beps: E ci ha parlato. «Per il nostro bene».","kiki: La gente che dice «per il vostro bene» di solito pensa al proprio.","@stat:fiducia+1","@flag:deposito_done","@clue:voce_buio","@objective:o1_caffe"]},{"do":["È tutto acceso. E vorrei che restasse così."]}]},{"id":"buio","name":"Buio","rect":[300,150,1300,600],"if":"flag.blackout","look":{"beps":"Buio pesto. Sento la carta, la polvere, e qualcosa che somiglia al mio cuore.","kiki":"Buio. Ma ricordo la stanza: il quadro è a sinistra, all'ingresso."},"use":{"beps":"Non vedo niente. Meglio che se ne occupi Kiki.","kiki":"Il quadro è a sinistra. Ci arrivo."}},{"id":"microcassetta","name":"Microcassetta","rect":[1640,610,50,40],"art":{"k":"crate","c":"#2a2a2a","overlay":true},"if":"flag.ripiano_aperto && !flag.blackout","col":"rec_01"},{"id":"registro","name":"Registro di consultazione","rect":[600,520,70,50],"art":{"k":"book","c":"#3a4a3a","overlay":true},"if":"!flag.blackout","col":"doc_02"},{"id":"estintore","name":"Estintore","rect":[800,540,60,160],"art":{"k":"pillar","c":"#a82a20"},"if":"!flag.blackout","look":{"beps":"Revisionato nel 2009. Speriamo che non serva.","kiki":"In un archivio, l'estintore è la cosa più importante. Dopo i fascicoli."}},{"id":"finestrella","name":"Finestra ad arco","rect":[610,250,110,170],"art":{"k":"window","time":"night"},"if":"!flag.blackout","look":{"beps":"Una finestrella ad arco. Da quaggiù si vede solo la cupola. Che, per una finestra di un deposito, non è poco.","kiki":"La cupola sotto la pioggia. Firenze vista dagli archivisti."}},{"id":"scaffali","name":"Catalogo A-Z","rect":[40,160,380,560],"if":"!flag.blackout","look":{"beps":"Chilometri di carta. Qualcuno dovrebbe calcolare quanto pesa la storia. Io scriverei un programma per farlo.","kiki":"Ventimila faldoni, più o meno. Li ho restaurati in duecento."}},{"id":"uscita","name":"Torna in sala","rect":[0,700,90,380],"art":{"k":"exit"},"arrow":"l","exit":{"to":"c1_archivio","if":"!flag.blackout","else":{"beps":["Al buio non trovo nemmeno l'uscita."],"kiki":["Prima la luce."]}}}]},"c1_caffe":{"name":"Caffè delle Logge","place":"Firenze · notte","chapter":1,"music":"tender","ambience":"crowd","art":{"type":"interior","time":"evening","wall":"#6a3a2a","floor":"#2a1e18","horizon":640,"wallpaper":true,"light":[{"x":960,"y":300,"r":700,"c":"#ffcf88","a":0.4}],"layers":[{"k":"chandelier","x":860,"y":0,"w":200,"h":150},{"k":"table","x":1200,"y":760,"w":260,"h":170,"c":"#3a2618"}]},"walk":[[80,1060],[1860,1060],[1800,720],[160,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c1_lungarno":[220,920,"r"]},"partnerOffset":[180,-10],"npcs":[{"id":"tommaso","x":1480,"y":800,"dir":"l","talk":"tommaso","look":{"beps":"Tommaso, il barista. Asciuga lo stesso bicchiere da quando siamo entrati.","kiki":"Il barista ascolta tutto. Si vede da come asciuga i bicchieri."}}],"firstEnter":["kiki: Due cappuccini, Tommaso. Lo so che sono le dieci di sera. Non giudicarci.","kiki[skeptical]: Allora, informatico. Adesso mi racconti tutto. E io, forse, racconto qualcosa a te.","@objective:o1_parlare"],"hotspots":[{"id":"bancone","name":"Bancone","rect":[1100,520,560,220],"art":{"k":"counter","c":"#3a2416"},"look":{"beps":"Marmo, ottone, e una macchina da espresso che vale più della mia auto.","kiki":"Il bancone più bello dell'Oltrarno. E il cappuccino più caro."}},{"id":"vetrina","name":"Vetrina dei dolci","rect":[1680,560,200,180],"art":{"k":"counter","c":"#c9b58c"},"look":{"beps":"Bomboloni. Alle dieci di sera. Firenze sa come tentare un uomo.","kiki":"Non guardare i bomboloni. Non guardarli."}},{"id":"specchio","name":"Specchio","rect":[560,160,260,260],"art":{"k":"mirror"},"look":{"beps":"Ho l'aria di uno che ha passato la serata in una stanza murata. Il che è corretto.","kiki":"Ho i capelli bagnati e lo sguardo di nonna quando era arrabbiata. Bene."}},{"id":"quadro","name":"Vecchia fotografia","rect":[940,190,160,120],"art":{"k":"frame","c":"#8a7454"},"col":"photo_01"},{"id":"tavolino","name":"Tavolino","rect":[380,720,340,190],"art":{"k":"table","c":"#3a2618"},"at":[560,960],"look":{"beps":"Il nostro tavolino. Due cappuccini, due fotografie identiche.","kiki":"Il tavolino più appartato. L'ho scelto apposta."}},{"id":"laptop","name":"Portatile di Kiki","rect":[500,660,120,70],"art":{"k":"laptop","overlay":true},"at":[560,940],"look":{"beps":"Il portatile di Kiki. Pieno di adesivi di archivi europei. Uno dice «I ♥ microfilm».","kiki":"Il mio portatile. Ha più chilometri di me."},"use":[{"if":"flag.pdf_open","do":["La LISTA_17 è aperta. Quattro nomi leggibili, tredici corrotti."]},{"do":["Ci serve la chiavetta di Beps, per provare ad aprire il PDF."]}],"items":{"usb":[{"if":"flag.pdf_open","do":["Il PDF è già aperto."]},{"do":["@dialogue:pdf_password"]}]}},{"id":"giornale","name":"Giornale","rect":[760,760,120,60],"art":{"k":"papers","overlay":true},"at":[800,960],"look":{"beps":["«Il notaio Aurelio Varano finanzia il restauro del palazzo di via de' Bardi.» Il mio cantiere. Il mio committente, in pratica.","@clue:varano_finanzia"],"kiki":["Varano. Notaio. Finanzia proprio il palazzo della stanza murata. Che generoso.","@clue:varano_finanzia"]}},{"id":"finestra","name":"Vetrina sulla strada","rect":[1240,110,460,300],"art":{"k":"window","time":"rain","rain":true},"look":{"beps":"Fuori piove. Dentro, per la prima volta stasera, fa caldo.","kiki":"Nessun cappotto grigio, là fuori. Per ora."}},{"id":"uscita","name":"Uscita","rect":[0,620,80,440],"art":{"k":"exit"},"arrow":"l","exit":{"to":"c1_lungarno","if":"false","else":{"beps":["Non abbiamo finito di parlare."],"kiki":["Siediti, Beps. Non abbiamo finito."]}}}]},"c2_gare":{"name":"Gare de Lyon","place":"Parigi · novembre 2026, mattina","chapter":2,"music":"paris","ambience":"station","fx":[{"k":"light","x":300,"y":0,"w":600,"h":1000},"dust"],"art":{"type":"interior","time":"day","wall":"#8a8070","floor":"#4a4440","horizon":640,"wainscot":false,"beams":true,"light":[{"x":600,"y":200,"r":700,"c":"#fff0d0","a":0.35}],"layers":[{"k":"arch","x":120,"y":40,"w":760,"h":600,"c":"#6a6458","inner":"#c8d4dc"},{"k":"arch","x":1000,"y":40,"w":760,"h":600,"c":"#6a6458","inner":"#c8d4dc"},{"k":"pillar","x":900,"y":40,"w":80,"h":620,"c":"#5a5448"}]},"walk":[[60,1060],[1860,1060],[1800,720],[120,720]],"scale":[720,0.72,1060,1],"spawn":{"default":[500,900,"r"],"from_c2_quai":[1700,900,"l"]},"firstEnter":["kiki: Parigi. Sei ore di treno e hai russato per cinque.","beps: Non russavo. Respiravo con convinzione.",{"if":"flag.switch_tutorial_done","do":[],"else":["@flag:switch_tutorial_done","@toast:Puoi passare da Beps a Kiki con Tab o toccando il ritratto in alto a destra. Ognuno vede le cose a modo suo."]},"@objective:o2_marchetti"],"hotspots":[{"id":"tabellone","name":"Tabellone delle partenze","rect":[1080,120,560,160],"art":{"k":"sign","label":"DÉPARTS · ARRIVÉES","c":"#14181e"},"look":{"beps":"Lione, Marsiglia, Ginevra, Milano. E il treno per Firenze delle 19:06. Lo memorizzo, non si sa mai.","kiki":"Le lettere che girano facendo clac-clac. Le hanno tolte quasi ovunque. Qui no. Parigi è testarda."}},{"id":"orologio","name":"Orologio della torre","rect":[860,60,160,160],"art":{"k":"clock"},"look":{"beps":"Un orologio enorme. Segna le nove e dodici. Puntualità francese, ritardo italiano: siamo in pari.","kiki":"Nonna diceva: «A Parigi gli orologi sono decorativi»."}},{"id":"train_bleu","name":"Le Train Bleu","rect":[200,160,360,220],"art":{"k":"painting","c":"#2a3a6a","seed":"tb"},"look":{"beps":"Il ristorante Le Train Bleu. Soffitti affrescati, ori, velluti. Un caffè costa quanto il biglietto del treno.","kiki":"Nonna ci portava la mamma ogni compleanno. La mamma odiava il velluto."}},{"id":"edicola","name":"Edicola","rect":[1500,470,220,290],"art":{"k":"stall","c":"#1e3a4a"},"look":{"beps":"Giornali, cartoline, souvenir della Tour Eiffel in tutte le misure. Anche quella da tre metri? Speriamo di no.","kiki":"Le Monde, Libération, e una cartolina d'epoca che mi fissa."}},{"id":"cartolina","name":"Cartolina d'epoca","rect":[1560,520,60,70],"art":{"k":"frame","c":"#d8c8a0","overlay":true},"col":"photo_03"},{"id":"piccione","name":"Piccione","rect":[700,840,80,70],"art":{"k":"figure","c":"#5a5a64"},"look":{"beps":"Un piccione parigino. Ha l'aria di chi giudica il mio cappotto.","kiki":"Ha più eleganza di metà dei passeggeri."},"use":{"beps":"Ciao. Non ho briciole. Non ho niente. Non mi guardare così.","kiki":"No, Beps non ha briciole. Vai a giudicare qualcun altro."}},{"id":"consigne","name":"Armadietti (consigne)","rect":[120,460,300,300],"art":{"k":"deposit","c":"#5a6a70","cols":5,"rows":4},"at":[280,860],"only":"kiki","onlyMsg":{"beps":["Armadietti a combinazione. Kiki ha detto che sua nonna «lasciava sempre qualcosa in consigne». Il codice lo sa lei, non io."]},"look":{"beps":"Armadietti a combinazione. Il numero 67 ha un adesivo con una lira, quasi cancellato.","kiki":"Il 67. Con la lira. Nonna usava sempre lo stesso codice per tutto: 1967."},"use":[{"if":"!col.doc_04","do":["@anim:use","@sfx:click","kiki: 1-9-6-7. … Si apre. Nonna, sei incredibile.","@collect:doc_04","@stat:legame+1","@inc:coop"]},{"do":["kiki: È vuoto, adesso. Ma l'ho aperto io."]}]},{"id":"panchina","name":"Panchina","rect":[1080,820,300,110],"art":{"k":"bench","c":"#2a3a3a"},"at":[1230,960],"look":{"beps":"Una panchina di ghisa verde. Elegante perfino quella.","kiki":"Non sederti, ci addormentiamo. Andiamo."}},{"id":"uscita","name":"Taxi (verso la Senna)","rect":[1820,600,100,460],"art":{"k":"exit"},"exit":{"to":"c2_quai"},"arrow":"r"}]},"c2_quai":{"name":"Quai des Grands-Augustins","place":"Parigi · lungo la Senna","chapter":2,"music":"paris","ambience":"city","art":{"type":"exterior","time":"day","horizon":560,"ground":"#6a6458","skyline":240,"sky":["#a8c0d0","#e8dcc0"],"layers":[{"k":"river","x":0,"y":540,"w":1920,"h":120,"c":"#4a6070"},{"k":"dome","x":1300,"y":260,"w":260,"h":260,"c":"#7a8890"},{"k":"tower","x":1560,"y":220,"w":90,"h":300,"c":"#a89a82"},{"k":"tower","x":1660,"y":220,"w":90,"h":300,"c":"#a89a82"},{"k":"railing","x":0,"y":640,"w":1920,"h":80,"c":"#3a3a34"},{"k":"tree","x":60,"y":260,"w":260,"h":420,"c":"#5a7040"},{"k":"tree","x":1700,"y":280,"w":220,"h":400,"c":"#5a7040"}]},"walk":[[0,1060],[1920,1060],[1920,780],[0,780]],"scale":[760,0.76,1060,1.02],"spawn":{"default":[300,900,"r"],"from_c2_gare":[140,920,"r"],"from_c2_studio_marchetti":[1780,920,"l"],"from_c2_appartamento":[960,900]},"npcs":[{"id":"albert","x":760,"y":830,"dir":"r","talk":"albert","look":{"beps":"Un bouquiniste con la barba bianca e una sciarpa rossa. Sta leggendo Proust. In piedi.","kiki":"Monsieur Albert. Nonna comprava i libri da lui. È sempre stato vecchio, credo."}}],"hotspots":[{"id":"bancarella","name":"Bancarella di libri","rect":[380,620,340,200],"art":{"k":"stall","c":"#2f4a35"},"at":[560,880],"look":{"beps":"Le casse verdi dei bouquinistes, appese al parapetto. Libri, stampe, riviste vecchie di un secolo.","kiki":"Una cassa di libretti d'opera. Cherubini, Rameau, Gluck… Monsieur Albert sa cosa vende."},"use":{"beps":"Non tocco niente senza il permesso di Albert. Ha l'aria di uno che morde.","kiki":"Chiedo prima ad Albert. È la regola dei quais."}},{"id":"senna","name":"Senna","rect":[0,540,1920,110],"look":{"beps":"La Senna. Più larga dell'Arno, più lenta, più sicura di sé.","kiki":"Nonna diceva che la Senna è un fiume che ha già visto tutto e ha deciso di non commentare."}},{"id":"notre_dame","name":"Notre-Dame","rect":[1300,200,460,320],"look":{"beps":"Notre-Dame, rinata dopo l'incendio. Ogni volta che la vedo penso: anche le cose bruciate si possono ripristinare. Come un backup.","kiki":"L'hanno restaurata pietra per pietra. Ci sono restauratori che piangono quando ne parlano. Io sono una di loro."}},{"id":"lucchetto","name":"Lucchetto sul parapetto","rect":[1080,660,50,50],"art":{"k":"coin","overlay":true},"col":"sym_2"},{"id":"panchina","name":"Panchina","rect":[1180,830,300,110],"art":{"k":"bench","c":"#3a4a3a"},"at":[1330,960],"look":{"beps":"Panchina con vista. Parigi è fatta apposta per stare seduti a guardarla.","kiki":"Dopo. Ci sediamo dopo. Promesso."}},{"id":"verso_gare","name":"Verso la Gare de Lyon","rect":[0,760,90,300],"art":{"k":"exit"},"exit":{"to":"c2_gare"},"arrow":"l"},{"id":"verso_marais","name":"Verso il Marais (rue des Archives)","rect":[1830,760,90,300],"art":{"k":"exit"},"exit":{"to":"c2_studio_marchetti"},"arrow":"r"},{"id":"verso_ada","name":"Rue Vieille-du-Temple (casa di Ada)","rect":[880,700,170,100],"art":{"k":"exit"},"arrow":"u","exit":{"to":"c2_appartamento","if":"flag.helene_met","else":{"beps":["Kiki dice che prima dobbiamo passare da Hélène. Ha lei le chiavi della casa della nonna."],"kiki":["Le chiavi di casa di nonna le ha Hélène. Prima lo studio."]}}}]},"c2_studio_marchetti":{"name":"Studio Marchetti","place":"12, rue des Archives · Parigi","chapter":2,"music":"paris","ambience":"room","fx":[{"k":"light","x":1200,"y":40,"w":380,"h":900}],"art":{"type":"interior","time":"day","wall":"#b8a888","floor":"#5a4634","horizon":650,"wallpaper":false,"light":[{"x":1380,"y":300,"r":600,"c":"#fff4dc","a":0.35}],"layers":[{"k":"poster","x":120,"y":160,"w":150,"h":200,"c":"#d8c8a8"},{"k":"poster","x":300,"y":190,"w":130,"h":170,"c":"#c8b898"},{"k":"easel","x":1640,"y":420,"w":180,"h":340}]},"walk":[[80,1060],[1860,1060],[1780,710],[160,710]],"scale":[710,0.72,1060,1],"spawn":{"default":[300,900,"r"],"from_c2_quai":[180,920,"r"],"from_c2_camera_oscura":[1000,820]},"npcs":[{"id":"helene","x":1260,"y":860,"dir":"l","talk":"helene","look":{"beps":"Capelli d'argento a caschetto, trench color sabbia, occhi che misurano la luce. Hélène Marchetti.","kiki":"Hélène. L'ultima volta che l'ho vista era al funerale di nonna. Mi aveva tenuto la mano tutto il tempo."}}],"firstEnter":["@dialogue:helene"],"hotspots":[{"id":"banco","name":"Banco luminoso","rect":[560,600,420,160],"art":{"k":"table","c":"#e8e4d8"},"at":[770,860],"look":{"beps":"Un tavolo luminoso da fotografo. Ci si appoggiano le pellicole per guardarle in controluce.","kiki":"Il banco luminoso. Perfetto per sovrapporre due stampe con i segni di registro."},"use":[{"if":"puzzle.c2_sovrapposizione","do":["Le due foto combaciano. Non ho più bisogno del banco."]},{"if":"item.foto1944 && item.foto1967","do":["@anim:use","Appoggio le due fotografie sul banco luminoso.","@puzzle:c2_sovrapposizione"]},{"do":["Ho solo una delle due foto. Me ne serve un'altra da sovrapporre."]}],"items":{"foto1944":[{"if":"item.foto1967","do":["@puzzle:c2_sovrapposizione"]},{"do":["Una sola foto non basta. Me ne serve un'altra da sovrapporre."]}],"foto1967":[{"if":"item.foto1944","do":["@puzzle:c2_sovrapposizione"]},{"do":["Mi serve anche la foto del '44."]}],"negativo":["Il negativo si legge al contrario. Va stampato nella camera oscura, con l'ingranditore."]}},{"id":"soffietto","name":"Macchina a soffietto","rect":[1040,380,160,220],"art":{"k":"projector"},"look":{"beps":"Una macchina fotografica a soffietto su un cavalletto di legno. Hardware vero, di quello che non si aggiorna.","kiki":"Una Deardorff degli anni Cinquanta. Jacques Marchetti ci ha fotografato mezza Parigi."}},{"id":"ritratti","name":"Ritratti alle pareti","rect":[100,140,360,240],"look":{"beps":"Ritratti in bianco e nero. Musicisti, scrittori, un pugile, una bambina con un gatto. Tutti guardano in macchina tranne uno.","kiki":"Jacques Marchetti aveva il dono di far sembrare tutti più coraggiosi di quanto fossero."}},{"id":"ritratto_ada","name":"Ritratto di coppia","rect":[460,160,110,150],"art":{"k":"frame","c":"#c8c0a8"},"col":"photo_04"},{"id":"cassettiera","name":"Cassettiera dei negativi","rect":[1450,470,180,260],"art":{"k":"cabinet","c":"#5a4a3a","cols":3,"rows":6},"look":{"beps":"Centinaia di cassettini etichettati per anno. 1958, 1959… 1967 è vuoto.","kiki":"Il cassettino del 1967 è vuoto. Hélène li ha già tirati fuori. O qualcun altro."}},{"id":"ricevuta","name":"Foglio sul bancone","rect":[880,610,70,40],"art":{"k":"papers","overlay":true},"col":"doc_05"},{"id":"gatto","name":"Gatto","rect":[1180,640,120,80],"art":{"k":"figure","c":"#e8a050"},"look":{"beps":"Un gatto rosso sopra una pila di Paris Match. Si chiama Daguerre. Naturalmente.","kiki":"Daguerre! Mi riconosce. Credo. Mi ignora con affetto."},"use":{"beps":[{"if":"!flag.gatto_b","do":["Lo accarezzo… e starnutisco. Sono allergico. Daguerre lo sa e mi sorride.","@flag:gatto_b","@stat:legame+1 quiet"]},{"do":["Daguerre mi guarda. Io starnutisco. È la nostra relazione."]}],"kiki":"Fa le fusa come un ventilatore rotto. Nonna lo adorava."}},{"id":"finestra","name":"Finestra sul cortile","rect":[1240,120,300,280],"art":{"k":"window","time":"day","city":false},"look":{"beps":"Un cortile del Marais con un tiglio e una bicicletta senza ruota davanti. Parigi è piena di biciclette incomplete.","kiki":"Da questa finestra nonna salutava Jacques ogni mattina. Lo diceva sempre."}},{"id":"tenda","name":"Camera oscura","rect":[1660,260,180,470],"art":{"k":"curtain","c":"#1a1a1a"},"at":[1720,860],"exit":{"to":"c2_camera_oscura","if":"item.negativo || flag.helene_met","else":"Hélène non mi ha ancora invitato nella sua camera oscura. Il che, detto così, suona strano."}},{"id":"uscita","name":"Verso la Senna","rect":[0,620,80,440],"art":{"k":"exit"},"exit":{"to":"c2_quai"},"arrow":"l"}]},"c2_camera_oscura":{"name":"Camera oscura","place":"Studio Marchetti · Parigi","chapter":2,"music":"mystery","ambience":"room","art":{"type":"interior","time":"night","wall":"#3a1010","floor":"#1a0a0a","horizon":650,"wainscot":false,"dark":0.4,"light":[{"x":960,"y":120,"r":900,"c":"#ff3020","a":0.4}],"layers":[{"k":"hanglamp","x":920,"y":0,"w":80,"h":140},{"k":"rope","x":200,"y":120,"w":1500,"h":30}]},"walk":[[100,1060],[1820,1060],[1700,720],[220,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[960,900],"from_c2_studio_marchetti":[960,920]},"firstEnter":["kiki: Luce rossa. Non aprire la tenda per nessun motivo, o bruci tutto quello che è in bacinella.","beps: Tutto è in bacinella? Io sono in bacinella?"],"hotspots":[{"id":"ingranditore","name":"Ingranditore","rect":[300,330,260,380],"art":{"k":"projector"},"at":[440,880],"look":{"beps":"Un ingranditore Durst. Proietta il negativo sulla carta fotografica, come una lanterna magica al contrario.","kiki":"Il Durst di Jacques. Ci ho stampato le mie prime foto a quindici anni."},"use":[{"if":"flag.retro_1967","do":["Il negativo è già stampato. La scritta è chiara."]},{"if":"item.negativo","do":["@dialogue:sviluppo"]},{"do":["Mi serve un negativo da stampare."]}],"items":{"negativo":[{"if":"!flag.retro_1967","do":["@dialogue:sviluppo"]},{"do":["Già stampato."]}]}},{"id":"bacinelle","name":"Bacinelle","rect":[700,640,520,110],"art":{"k":"counter","c":"#2a2a2a"},"at":[960,880],"look":{"beps":"Tre bacinelle: sviluppo, arresto, fissaggio. Odore di aceto e di anni Settanta.","kiki":"Rivelatore, arresto, fissaggio. In quest'ordine, sempre. Come una liturgia."}},{"id":"stampe","name":"Stampe appese","rect":[200,140,1500,140],"look":{"beps":"Stampe appese ad asciugare con le mollette. Facce, strade, una bambina con un pallone. Una donna col cappello, sfocata.","kiki":"Stampe recenti. Hélène sta ristampando tutto il 1967. Perché proprio adesso?"}},{"id":"provino","name":"Provino a contatto","rect":[1300,180,80,80],"art":{"k":"negative","overlay":true},"col":"doc_03"},{"id":"timer","name":"Timer","rect":[1360,520,120,120],"art":{"k":"clock"},"look":{"beps":"Un timer meccanico che ticchetta come un cuore nervoso.","kiki":"Il timer. Senza di lui si sbaglia tutto."}},{"id":"tanica","name":"Taniche di chimici","rect":[1520,640,200,140],"art":{"k":"boxes","label":"FIX"},"look":{"beps":"«Fissaggio». Spero non si riferisca a me.","kiki":"Non toccarle senza guanti. Davvero, Beps."}},{"id":"uscita","name":"Esci dalla camera oscura","rect":[880,960,200,100],"art":{"k":"exit"},"exit":{"to":"c2_studio_marchetti"},"arrow":"d"}]},"c2_appartamento":{"name":"Casa di Ada","place":"Rue Vieille-du-Temple · Parigi","chapter":2,"music":"tender","ambience":"room","fx":["dust",{"k":"light","x":1180,"y":60,"w":420,"h":900}],"art":{"type":"interior","time":"dusk","wall":"#8a7a68","floor":"#4a3a2c","horizon":650,"wallpaper":true,"light":[{"x":1380,"y":260,"r":560,"c":"#ffcf98","a":0.4}],"layers":[{"k":"sofa","x":420,"y":640,"w":420,"h":200,"c":"#d8d0c0"},{"k":"rug","x":500,"y":860,"w":700,"h":150,"c":"#6a3a2a"},{"k":"hanglamp","x":900,"y":0,"w":80,"h":160}]},"walk":[[80,1060],[1860,1060],[1780,720],[160,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,900,"r"],"from_c2_quai":[200,920,"r"]},"firstEnter":["kiki[sad]: …","kiki: Hanno coperto tutto con le lenzuola. Sembra che la casa dorma.","beps[worried]: Kiki. I cassetti sono aperti. Qualcuno è stato qui prima di noi.","kiki[angry]: Hanno frugato tra le cose di nonna.",{"choice":[{"label":"«Mi dispiace. Vuoi che aspetti fuori?»","do":["kiki[tender]: No. Resta. È più facile, se ci sei.","@stat:legame+1"]},{"label":"«Chiunque sia stato, cercava quello che cerchiamo noi.»","do":["kiki[determined]: Allora vediamo cosa non hanno trovato.","@stat:conoscenza+1"]},{"label":"Mettile una mano sulla spalla, in silenzio","line":"beps[tender]: …","do":["kiki[sad]: Grazie.","@stat:legame+1","@stat:fiducia+1"]}]},"@objective:o2_casa"],"hotspots":[{"id":"scrittoio","name":"Scrittoio","rect":[1040,560,300,200],"art":{"k":"desk","c":"#5a3a24"},"at":[1190,860],"look":{"beps":"Uno scrittoio Luigi Filippo. Sopra, una lampada e un calamaio secco. I cassetti sono stati svuotati sul pavimento.","kiki":"Nonna scriveva qui le lettere. Una al giorno, a qualcuno. Non ho mai saputo a chi."},"use":[{"if":"item.mappa && item.medaglione && !puzzle.c2_mappa","do":["Stendo la mappa sullo scrittoio e ci appoggio il medaglione.","@puzzle:c2_mappa"]},{"do":["Hanno già svuotato tutto. Qualunque cosa ci fosse, se la sono presa. O non c'era."]}],"items":{"mappa":[{"if":"item.medaglione","do":["@puzzle:c2_mappa"]},{"do":["Mi serve qualcosa da appoggiare sulla mappa. Qualcosa di rotondo, con dei fori."]}],"medaglione":[{"if":"item.mappa","do":["@puzzle:c2_mappa"]},{"do":["Mi serve una mappa su cui appoggiarlo."]}]}},{"id":"grammofono","name":"Mobile del grammofono","rect":[200,480,200,280],"art":{"k":"phonograph"},"at":[320,860],"only":"kiki","onlyMsg":{"beps":["Un grammofono a mobile. Kiki lo guarda come se sapesse qualcosa. Forse dovrebbe guardarlo lei."]},"look":{"beps":"Un grammofono a mobile, con lo sportello per i dischi. Chiuso.","kiki":"Nonna nascondeva i cioccolatini nel mobile del grammofono. E non solo quelli."},"use":[{"if":"!item.lettera_ada && !flag.lettera_letta","do":["@anim:pickup","kiki: Il doppio fondo. Lo sapevo solo io. … Una lettera. «Per Federica, quando sarà il momento.»","@give:lettera_ada","@dialogue:lettera_ada"]},{"do":["kiki: Solo dischi, adesso. Edith Piaf, Gluck, e Mina. Nonna era complicata."]}]},{"id":"segreteria","name":"Segreteria telefonica","rect":[1360,600,100,60],"art":{"k":"recorder","overlay":true},"col":"rec_02"},{"id":"foto_famiglia","name":"Fotografie di famiglia","rect":[700,200,160,150],"art":{"k":"frame","c":"#d8ccb0"},"col":"photo_05"},{"id":"diario","name":"Pagina strappata","rect":[900,900,80,50],"art":{"k":"papers","overlay":true},"col":"doc_06"},{"id":"cappello","name":"Cappello sull'attaccapanni","rect":[1600,300,160,440],"art":{"k":"figure","hat":true,"c":"#151515"},"look":{"beps":"Un cappello nero a falda larga sull'attaccapanni. Lo stesso della foto. Allora la donna sul Lungarno…","kiki":["Il cappello di nonna. È qui. È sempre stato qui.","kiki[worried]: Allora chi lo portava sul Lungarno, l'altra sera?","@clue:cappello_ada"]}},{"id":"lenzuola","name":"Mobili coperti","rect":[420,600,420,220],"look":{"beps":"Un divano sotto un lenzuolo. Sembra un fantasma che ha deciso di sedersi.","kiki":"Il divano dove mi addormentavo quando nonna guardava i film di Truffaut."}},{"id":"finestra","name":"Finestra sui tetti","rect":[1180,120,320,300],"art":{"k":"window","time":"dusk"},"look":{"beps":"I tetti di zinco di Parigi al tramonto. Un mare grigio con i comignoli come boe.","kiki":"Da qui nonna mi insegnava i nomi delle stelle. Le sbagliava tutte, apposta, per farmi ridere."}},{"id":"cassetti","name":"Cassetti rovesciati","rect":[940,780,260,90],"look":{"beps":"Hanno cercato in fretta e con metodo. Professionisti. Professionisti maleducati.","kiki":"Hanno lasciato le cose di valore. Cercavano carta. Cercavano quello che abbiamo noi."}},{"id":"uscita","name":"Esci","rect":[0,620,80,440],"art":{"k":"exit"},"exit":{"to":"c2_quai"},"arrow":"l"}]},"c3_piazza":{"name":"Piazza dei Librai","place":"Roma · sera","chapter":3,"music":"roma","ambience":"city","art":{"type":"exterior","time":"dusk","horizon":600,"ground":"#7a6650","skyline":160,"sky":["#3a3a6a","#e89a6a"],"light":[{"x":960,"y":700,"r":600,"c":"#ffb070","a":0.25}],"layers":[{"k":"building","x":0,"y":160,"w":620,"h":520,"c":"#c08a5a","seed":"r1","lit":0.5},{"k":"building","x":1300,"y":140,"w":620,"h":540,"c":"#b87a50","seed":"r2","lit":0.5},{"k":"dome","x":720,"y":120,"w":480,"h":420,"c":"#8a6a4a"},{"k":"pillar","x":700,"y":400,"w":60,"h":280,"c":"#d8c8a8"},{"k":"pillar","x":1160,"y":400,"w":60,"h":280,"c":"#d8c8a8"}]},"walk":[[0,1060],[1920,1060],[1920,780],[0,780]],"scale":[760,0.76,1060,1.02],"spawn":{"default":[300,920,"r"],"from_c3_biblioteca":[1520,880,"l"],"from_c3_osteria":[160,920,"r"]},"npcs":[{"id":"caricaturista","char":"agente","name":"Peppe il caricaturista","x":520,"y":860,"dir":"r","talk":"peppe","scale":0.95,"look":{"beps":"Un caricaturista con un cavalletto e un basco. Ha disegnato tre turisti come tre patate. Talento.","kiki":"Peppe. Disegna tutti come se fossero innamorati. È il suo trucco."}}],"firstEnter":["kiki: Roma. La città dove anche le pietre hanno un'opinione.","beps: La Teodosiana è lì, dietro le colonne. Chiude alle otto.","@objective:o3_biblioteca"],"hotspots":[{"id":"fontana","name":"Fontana","rect":[820,700,300,200],"art":{"k":"fountain"},"at":[970,940],"look":{"beps":"Una fontana barocca con quattro tritoni che sputano acqua con l'aria offesa.","kiki":"Dell'allievo di un allievo di Bernini. A Roma è come dire «anonimo»."},"use":{"beps":"Lancio una moneta? No. Le 500 lire restano con me.","kiki":"Non lancio monete. Torno a Roma quando voglio, senza corrompere nessuno."}},{"id":"lira_fontana","name":"Incisione sulla vasca","rect":[1060,820,50,50],"art":{"k":"symbol","c":"#e8d8b0","a":0.4},"col":"sym_3"},{"id":"chiesa","name":"Facciata della chiesa","rect":[720,120,480,300],"look":{"beps":"Una facciata a ordine gigante, con il timpano spezzato. Borromini sarebbe fiero. O furioso.","kiki":"Sant'Ivo dei Librai. Il patrono dei librai è un santo poco noto. Come i librai."}},{"id":"balcone","name":"Balcone","rect":[1440,300,160,200],"art":{"k":"figure","hat":true,"c":"#0a0a0c"},"if":"!flag.woman_3","look":{"beps":"Sul balcone del secondo piano. Una donna in nero. Col cappello.","kiki":"È lei. Beps, è LEI."},"use":["@walk:1500,840","beps[surprised]: Era lì. Le persiane si sono chiuse.","kiki[worried]: Ci sta seguendo. O ci sta precedendo.","@flag:woman_3","@clue:donna_roma","@stat:conoscenza+1"]},{"id":"cartellone","name":"Cartellone","rect":[1340,520,150,190],"art":{"k":"poster","c":"#e0c890"},"look":{"beps":"«I custodi della memoria. Mostra sugli archivi salvati durante la guerra.» Siamo nel posto giusto.","kiki":"Ci sono due foto di Firenze '44. E il nome di Don Ilario Cesti come curatore."}},{"id":"tavolini","name":"Tavolini","rect":[80,720,300,160],"art":{"k":"table","c":"#d8d0c0"},"look":{"beps":"Tovaglie a quadri, candele nei bicchieri. Mi viene fame solo a guardarli.","kiki":"Dopo, Beps. Dopo la biblioteca. Te lo prometto: carbonara."}},{"id":"portone","name":"Biblioteca Teodosiana","rect":[1520,520,200,240],"art":{"k":"door","label":"BIBLIOTECA","c":"#3a2416"},"at":[1600,860],"exit":{"to":"c3_biblioteca","if":"!flag.fuga_ok","else":["La biblioteca è piena di uomini del Notaio. Meglio di no."]}},{"id":"verso_osteria","name":"Verso Trastevere","rect":[0,760,90,300],"art":{"k":"exit"},"arrow":"l","exit":{"to":"c3_osteria","if":"flag.fuga_ok","else":{"beps":["Prima la biblioteca. Poi la carbonara."],"kiki":["Prima la biblioteca."]}}}]},"c3_biblioteca":{"name":"Biblioteca Teodosiana — Salone","place":"Roma","chapter":3,"music":"roma","ambience":"room","fx":["dust",{"k":"light","x":820,"y":0,"w":380,"h":1000}],"art":{"type":"interior","time":"dusk","wall":"#7a5a3a","floor":"#4a3020","horizon":660,"wainscot":false,"light":[{"x":1000,"y":200,"r":700,"c":"#ffe0b0","a":0.35}],"layers":[{"k":"shelves","x":0,"y":40,"w":760,"h":620,"c":"#5a3a22","seed":"t1","rows":7},{"k":"shelves","x":1180,"y":40,"w":740,"h":620,"c":"#5a3a22","seed":"t2","rows":7},{"k":"chandelier","x":880,"y":0,"w":200,"h":170}]},"walk":[[60,1060],[1860,1060],[1780,720],[140,720]],"scale":[720,0.72,1060,1],"spawn":{"default":[300,920,"r"],"from_c3_piazza":[200,920,"r"],"from_c3_sala_cassetti":[1600,860,"l"]},"npcs":[{"id":"ilario","x":1080,"y":860,"dir":"l","talk":"ilario","if":"!flag.allarme","look":{"beps":"Un prete minuscolo e antichissimo, con occhiali spessi come fondi di bottiglia. Sta leggendo Seneca e ascoltando i Pink Floyd con un auricolare.","kiki":"Don Ilario Cesti. Novantun anni. Ha restaurato più codici di quanti io ne abbia mai visti."}}],"hotspots":[{"id":"scaffali","name":"Scaffali a tutta altezza","rect":[0,40,760,300],"look":{"beps":"Scaffali alti dodici metri. Il problema non è leggere tutti questi libri. Il problema è arrivarci.","kiki":"Incunaboli, cinquecentine, manoscritti. Se il paradiso ha una biblioteca, ha questo odore."}},{"id":"scala","name":"Scala a pioli","rect":[620,120,120,560],"art":{"k":"railing","c":"#6a4a2a"},"at":[680,860],"only":"kiki","onlyMsg":{"beps":["Soffro di vertigini dal secondo piolo. È documentato. Kiki?"]},"look":{"beps":"Una scala a pioli con le ruote. In cima, sull'ultimo ripiano, qualcosa sporge da un libro.","kiki":"In cima c'è una fotografia infilata tra due volumi. Salgo io."},"use":[{"if":"!col.photo_06","do":["@anim:use","kiki: Salgo. Beps, tieni la scala. E non guardare in alto.","beps: Non guardo. Non guardo mai in alto. Ho le vertigini anche a guardare.","@inc:coop","@collect:photo_06"]},{"do":["kiki: Lassù non c'è altro. Solo polvere del Seicento."]}]},{"id":"globo","name":"Globo celeste","rect":[820,600,180,220],"art":{"k":"rings"},"look":{"beps":"Un globo celeste del Seicento. Le costellazioni hanno facce di animali che non hanno mai visto una costellazione.","kiki":"Coronelli, 1693. Lyra è disegnata come uno strumento d'oro. La costellazione di Orfeo."}},{"id":"busto","name":"Busto","rect":[1220,360,120,200],"art":{"k":"statue","c":"#e0d8c8"},"look":{"beps":"Un busto di marmo di qualcuno con un naso importante e un'espressione da «ve l'avevo detto».","kiki":"Teodosio, il fondatore. Il naso glielo hanno rifatto nel 1890. Si vede."}},{"id":"bancone","name":"Bancone del bibliotecario","rect":[1000,600,300,160],"art":{"k":"counter","c":"#4a2a18"},"look":{"beps":"Il bancone di Don Ilario. Un registro dei prestiti, un vasetto di caramelle alla menta e un iPod del 2005.","kiki":"Il registro dei prestiti è ancora a mano. Rispetto."}},{"id":"catalogo","name":"Lettera nel catalogo","rect":[1440,620,70,50],"art":{"k":"letter","overlay":true},"col":"doc_07"},{"id":"porta_cassetti","name":"Sala dei Cassetti","rect":[1720,300,140,440],"art":{"k":"door","label":"SALA XVII","c":"#2a1810"},"at":[1680,860],"exit":{"to":"c3_sala_cassetti","if":"flag.cassetti_ok","else":{"beps":["Chiusa a chiave. La chiave ce l'ha Don Ilario, appesa al collo come un crocifisso."],"kiki":["Chiusa. Dobbiamo convincere Don Ilario."]}}},{"id":"uscita","name":"Piazza","rect":[0,640,80,420],"art":{"k":"exit"},"exit":{"to":"c3_piazza"},"arrow":"l"}]},"c3_sala_cassetti":{"bg":"assets/backgrounds/bg_archivio_firenze_room_02.jpg","name":"Sala dei Cassetti","place":"Biblioteca Teodosiana · Roma","chapter":3,"music":"mystery","ambience":"room","fx":["dust",{"k":"flicker","if":"flag.allarme"}],"art":{"type":"interior","time":"night","wall":"#4a3626","floor":"#2a1c12","horizon":650,"wainscot":false,"light":[{"x":960,"y":380,"r":500,"c":"#ffc070","a":0.45}],"layers":[{"k":"candle","x":600,"y":470,"w":40,"h":80},{"k":"candle","x":1300,"y":470,"w":40,"h":80},{"k":"curtain","x":80,"y":100,"w":260,"h":560,"c":"#4a1a1a"}]},"walk":[[600,1080],[1700,1080],[1800,960],[1720,820],[1300,870],[1000,870],[960,650],[860,560],[720,560],[640,700]],"scale":[560,0.45,1080,1],"spawn":{"default":[700,1000,"r"],"from_c3_biblioteca":[680,1010,"r"]},"firstEnter":["kiki[surprised]: Diciassette cassetti. Ognuno con un emblema.","beps: E una targa. In latino, immagino.","kiki: Immagini bene.","@objective:o3_cassetti"],"hotspots":[{"id":"mobile","name":"Mobile dei diciassette cassetti","rect":[370,290,200,460],"art":{"k":"cabinet","c":"#5a3a20","cols":6,"rows":3},"at":[660,900],"look":{"beps":["Un mobile di noce con diciassette cassetti: sei, sei e cinque. Un posto vuoto in basso a destra.","Strano: il mobile è più corto della nicchia di almeno venti centimetri. Dietro c'è spazio."],"kiki":"Diciassette emblemi intarsiati. Il diciassettesimo è stato raschiato via. Come nella foto. Come nella lista."},"use":[{"if":"puzzle.c3_cassetti","do":["I cassetti hanno dato quello che dovevano."]},{"if":"!flag.fermo_sbloccato","do":[{"if":"active=='beps'","do":["Provo a tirare un cassetto… niente. Bloccati tutti.","beps[think]: Venti centimetri di vuoto dietro. Un meccanismo. Ci dev'essere un fermo."],"else":["kiki: Bloccati. Tutti. Beps, tu che smonti qualunque cosa: questo mobile ti dice qualcosa?"]}]},{"if":"!flag.targa_tradotta","do":["Potrei aprire i cassetti a caso, ma senza capire la targa sarebbe come giocare alla roulette.","@puzzle:c3_cassetti"]},{"do":["@puzzle:c3_cassetti"]}]},{"id":"fianco","name":"Fianco del mobile","rect":[120,620,250,300],"art":{"k":"pillar","c":"#4a3018"},"at":[640,990],"if":"!flag.fermo_sbloccato","only":"beps","onlyMsg":{"kiki":["Il fianco del mobile. Non vedo niente di strano. Beps saprebbe dove guardare: smonta tutto da quando è nato."]},"look":{"beps":"Il fianco del mobile. Una fessura tra il legno e il muro, larga quanto una lama.","kiki":"Una fessura. Ci passa a malapena un'unghia."},"use":["Ci vorrebbe qualcosa di sottile e robusto da infilare nella fessura."],"items":{"coltellino":["@anim:use","@sfx:click","beps: Lama nella fessura… c'è un nottolino. Lo spingo…","beps[surprised]: Clac. Il mobile si è spostato di un centimetro. I cassetti ora sono liberi.",{"if":"present.kiki","do":["kiki[smile]: Ammetto che a volte gli informatici servono anche fuori dai computer.","@stat:fiducia+1"]},"@flag:fermo_sbloccato"]}},{"id":"targa","name":"Targa in latino","rect":[170,435,230,150],"art":{"k":"sign","label":"PRIMVS DVCIT…","c":"#6a5434"},"look":{"beps":["«Primus ducit, secunda meminit, tertius traicit, ultimus verba custodit.»","Ho fatto il classico. Vent'anni fa. Ricordo solo «rosa, rosae». Kiki?"],"kiki":[{"if":"!flag.targa_tradotta","do":["kiki: «Il primo guida, la seconda ricorda, il terzo traghetta, l'ultimo custodisce le parole.»","kiki[think]: Quattro ruoli. Gli stessi quattro leggibili nella LISTA_17: Orfeo, Euridice, il Barcaiolo, il Libraio.","@flag:targa_tradotta","@clue:targa_latina","@stat:conoscenza+1",{"if":"present.beps","do":["beps: Ricordami di non fare mai più il classico senza di te.","@inc:coop"]}]},{"do":["kiki: Il primo guida, la seconda ricorda, il terzo traghetta, l'ultimo custodisce le parole. Nell'ordine del giuramento."]}]}},{"id":"arazzo","name":"Affresco","rect":[1340,0,380,140],"look":{"beps":"Un affresco sbiadito: Orfeo che suona la lira agli animali. Il leone sembra annoiato.","kiki":"Fine Cinquecento. Orfeo che incanta le belve. Hanno restaurato male la zampa del leone: si vede il ritocco."}},{"id":"candelabro","name":"Lume a olio","rect":[1190,470,90,140],"look":{"beps":"Un lume a olio vero. In una biblioteca. Il mio assicuratore sta piangendo da qualche parte.","kiki":"Don Ilario non vuole luci elettriche qui. Dice che i libri dormono meglio."}},{"id":"verbale","name":"Verbale ingiallito","rect":[1250,615,70,50],"art":{"k":"papers","overlay":true},"if":"puzzle.c3_cassetti","col":"doc_08"},{"id":"porta","name":"Porta del salone","rect":[0,640,110,440],"art":{"k":"exit"},"arrow":"l","exit":{"to":"c3_biblioteca","if":"!flag.allarme","else":{"beps":["Le voci vengono da lì. Il Notaio ha mandato i suoi uomini."],"kiki":["No! Sono nel salone. Dobbiamo trovare un'altra uscita."]}}},{"id":"cancello","name":"Porta di servizio","rect":[1540,260,190,560],"art":{"k":"gate","open":false},"at":[1620,900],"if":"!flag.fuga_cancello","look":{"beps":"Un cancello di ferro battuto. Il chiavistello è dall'altra parte, irraggiungibile.","kiki":"Il chiavistello è dall'altra parte. Serve qualcuno di là."},"use":[{"if":"flag.leva_tenuta && active=='beps'","do":["Il cancello è sollevato! Kiki regge la leva. Passo!","@goto:c3_passaggio@820,900","@flag:fuga_cancello","@dialogue:fuga_riuniti"]},{"do":["Bloccato. Il meccanismo è dall'altra parte del muro."]}]},{"id":"grata","name":"Grata di aerazione","rect":[1300,650,120,90],"art":{"k":"vent","overlay":true},"at":[1360,900],"if":"flag.allarme","look":{"beps":["Una grata di aerazione. Dietro, un condotto stretto. Io non ci passo. Kiki forse sì.",{"if":"!flag.grata_aperta","do":["Quattro viti arrugginite."]}],"kiki":"Un condotto. Stretto, ma io ci passo."},"use":[{"if":"!flag.grata_aperta","do":["Avvitata. Quattro viti. Ci vuole un cacciavite. O il coltellino di un informatico."]},{"if":"active=='kiki'","do":["kiki[determined]: Vado io. Beps, se di là c'è il meccanismo del cancello, lo apro.","beps[worried]: Stai attenta.","kiki: Lo sono sempre. Tu stai qui e non fare niente di eroico.","@anim:pickup","@together:false","@place:kiki=c3_passaggio@480,900,r","@switch:kiki","@objective:o3_leva"]},{"do":["beps: Non ci passo. Sono un informatico, non un contorsionista.","kiki[determined]: Ci passo io. Passa a me, Beps.","@objective:o3_condotto"]}],"items":{"coltellino":[{"if":"!flag.grata_aperta","do":["@anim:use","@sfx:mechanism","Il cacciavite del coltellino… una vite, due, tre… quattro. La grata viene via.","@flag:grata_aperta","@objective:o3_condotto"]},{"do":["È già aperta."]}]}}]},"c3_passaggio":{"name":"Passaggio di servizio","place":"Sotto la Teodosiana · Roma","chapter":3,"music":"tension","ambience":"underground","fx":["dust"],"art":{"type":"underground","time":"night","wall":"#4a4036","floor":"#2a241e","horizon":660,"light":[{"x":700,"y":300,"r":520,"c":"#ffd090","a":0.3}],"layers":[{"k":"hanglamp","x":660,"y":0,"w":80,"h":160},{"k":"boxes","x":1500,"y":760,"w":260,"h":200,"label":"1944"}]},"walk":[[100,1060],[1820,1060],[1720,740],[200,740]],"scale":[740,0.74,1060,1],"follow":true,"spawn":{"default":[480,900]},"firstEnter":[{"if":"active=='kiki'","do":["kiki: Sono di là. Polvere, ragnatele e… sì: una leva. Il cancello è legato a una molla. Se la lascio, si richiude."]}],"hotspots":[{"id":"leva","name":"Leva del cancello","rect":[300,440,120,260],"art":{"k":"lever","down":false},"at":[380,880],"if":"!flag.fuga_cancello","look":{"beps":"La leva del cancello, dal lato sbagliato del muro.","kiki":"Una leva a molla. Tirandola, il cancello si alza. Lasciandola, si richiude."},"use":[{"if":"flag.leva_tenuta","do":["kiki: La sto tenendo! Beps, passa! (Passa a Beps con Tab o col ritratto.)"]},{"do":["@anim:use","@sfx:mechanism","kiki[determined]: Tiro… è dura… ecco! Il cancello si alza. Ma se lascio, si richiude.","kiki: BEPS! Il cancello è aperto! Muoviti!","@flag:leva_tenuta","@objective:o3_passa"]}]},{"id":"cancello_retro","name":"Cancello (dall'altra parte)","rect":[700,300,240,420],"art":{"k":"gate","open":true},"if":"!flag.fuga_cancello","look":{"kiki":"Il cancello visto da qui. Beps è dall'altra parte, a pochi metri. Sembrano chilometri.","beps":"Il cancello."}},{"id":"scala","name":"Scala retrattile","rect":[1180,80,160,300],"art":{"k":"stairs","c":"#5a5a5a"},"at":[1260,860],"look":{"beps":"Una scala retrattile, agganciata in alto. Porta al cortile, credo. Troppo in alto da raggiungere da soli.","kiki":"La scala per il cortile. Troppo in alto. Da sola non ci arrivo."},"use":[{"if":"flag.scala_giu","do":["@goto:c3_cortile"]},{"if":"flag.fuga_cancello","do":[{"if":"active=='kiki'","do":["kiki: Beps. Fammi scaletta.","beps: Prego, signora. Il mio ginocchio è a sua disposizione."],"else":["beps: Kiki, sali sulle mie spalle. Prometto di non guardare.","kiki[laugh]: Guarda pure, basta che non mi fai cadere."]},"@anim:use","@sfx:mechanism","narr: Un salto, una spinta, uno sgancio. La scala scende con un rumore di ferraglia.","@flag:scala_giu","@inc:coop","@stat:legame+1","@objective:o3_esci"]},{"do":["Troppo in alto. Da solo non ci arrivo. In due, forse."]}]},{"id":"cassa","name":"Casse del 1944","rect":[1500,760,260,200],"at":[1600,960],"look":{"beps":"Casse con la scritta «1944 — LIBRI». Vuote. Qualcuno, ottant'anni fa, ci ha nascosto dentro altro che libri.","kiki":"Casse da trasporto. Ci si nascondevano i libri. E a volte i bambini."}},{"id":"dittafono","name":"Dittafono","rect":[1540,720,60,40],"art":{"k":"recorder","overlay":true},"col":"rec_03"},{"id":"ragnatele","name":"Ragnatele","rect":[200,60,400,200],"look":{"beps":"Ragnatele architettonicamente impeccabili. Chi le ha fatte ha studiato.","kiki":"Non guardarle. Non pensarci. Cammina."}}]},"c3_cortile":{"name":"Cortile di Trastevere","place":"Roma · notte","chapter":3,"music":"roma","ambience":"city","art":{"type":"exterior","time":"night","horizon":620,"ground":"#4a3a30","skyline":120,"light":[{"x":1400,"y":420,"r":400,"c":"#ffcf88","a":0.4}],"layers":[{"k":"building","x":0,"y":80,"w":800,"h":620,"c":"#a8704a","seed":"tr1","lit":0.55},{"k":"building","x":1100,"y":60,"w":820,"h":640,"c":"#b88050","seed":"tr2","lit":0.5},{"k":"rope","x":300,"y":220,"w":1300,"h":40}]},"walk":[[0,1060],[1920,1060],[1920,800],[0,800]],"scale":[780,0.78,1060,1.02],"spawn":{"default":[600,920,"r"],"from_c3_passaggio":[600,920,"r"]},"firstEnter":["beps[surprised]: Siamo fuori. Siamo vivi. Siamo… in un cortile pieno di mutande stese.","kiki[laugh]: Trastevere. Benvenuto.","kiki: Le voci sono lontane. Non ci hanno seguito.",{"choice":[{"label":"«Sei stata incredibile, nel condotto.»","do":["kiki[tender]: Lo so. Ma è bello sentirselo dire.","@stat:legame+1"]},{"label":"«Abbiamo la chiave e la lista. Ce l'abbiamo fatta.»","do":["kiki[smile]: Ce l'abbiamo fatta. Noi due.","@inc:coop","@stat:fiducia+1"]},{"label":"«Mi devi una carbonara.»","do":["kiki[laugh]: Te ne devo due. Andiamo da Fiorella, è qui dietro.","@stat:legame+1"]}]},"@flag:fuga_ok","@join","@objective:o3_osteria"],"hotspots":[{"id":"panni","name":"Panni stesi","rect":[300,200,1300,120],"look":{"beps":"Lenzuola, camicie, un costume da Batman taglia bambino. La vita normale continua sopra le nostre teste.","kiki":"Sventolano come bandiere di un paese tranquillo."}},{"id":"nasone","name":"Fontanella","rect":[900,760,80,130],"art":{"k":"pillar","c":"#3a3a3a"},"at":[940,920],"look":{"beps":"Un nasone, la fontanella romana in ghisa. Acqua fresca gratis da centocinquant'anni.","kiki":"Si tappa sotto col dito e l'acqua esce dal buchino sopra. È l'unica tecnologia romana che capisco davvero."},"use":{"beps":"Bevo. Tappo sotto, buchino sopra… mi sono lavato la faccia. Volevo farlo comunque.","kiki":"Bevo. Fresca. Ne avevo bisogno."}},{"id":"gatti","name":"Gatti","rect":[1500,840,200,90],"art":{"k":"figure","c":"#5a4a3a"},"look":{"beps":"Tre gatti romani sul cofano di una Panda. Mi guardano come se gli dovessi dei soldi.","kiki":"I veri padroni di Roma. Noi siamo solo ospiti."}},{"id":"madonnella","name":"Edicola votiva","rect":[1300,360,140,180],"art":{"k":"frame","c":"#3a5a8a"},"look":{"beps":"Una Madonnina con un lumino acceso. Qualcuno ha lasciato un biglietto: «Grazie per il 1944».","kiki":"«Grazie per il 1944.» Chissà da quanti anni c'è."}},{"id":"vespa","name":"Vespa","rect":[180,820,260,160],"art":{"k":"car","c":"#8ab0a0"},"look":{"beps":"Una Vespa verde acqua del '72. Ho una debolezza per le cose fatte bene.","kiki":"Se la rubiamo, finiamo in un film. Non la rubiamo."}},{"id":"foglio","name":"Foglio sul muretto","rect":[1080,860,60,40],"art":{"k":"papers","overlay":true},"col":"doc_09"},{"id":"verso_osteria","name":"Osteria da Fiorella","rect":[1830,760,90,300],"art":{"k":"exit"},"exit":{"to":"c3_osteria"},"arrow":"r"}]},"c3_osteria":{"name":"Osteria da Fiorella","place":"Trastevere · Roma","chapter":3,"music":"tender","ambience":"crowd","art":{"type":"interior","time":"evening","wall":"#c8a070","floor":"#5a3a24","horizon":640,"wallpaper":false,"light":[{"x":960,"y":360,"r":700,"c":"#ffc880","a":0.4}],"layers":[{"k":"table","x":300,"y":720,"w":380,"h":200,"c":"#f0e8d8"},{"k":"table","x":1300,"y":740,"w":340,"h":190,"c":"#f0e8d8"},{"k":"hanglamp","x":900,"y":0,"w":90,"h":180}]},"walk":[[80,1060],[1860,1060],[1800,720],[140,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c3_cortile":[200,920,"r"],"from_c3_piazza":[200,920,"r"]},"firstEnter":["narr: Due carbonare dopo.","beps[smile]: Questa è la cosa più bella che mi sia capitata in tre capitoli.","kiki: Capitoli?","beps: Giorni. Volevo dire giorni.","kiki: Leggiamo la lista. Con calma, stavolta.","@objective:o3_lista"],"hotspots":[{"id":"tavolo","name":"Il nostro tavolo","rect":[1300,700,340,200],"at":[1460,960],"look":{"beps":"Due piatti vuoti, due bicchieri, una lista di diciassette nomi. Una cena romantica, per gli standard di questa settimana.","kiki":"Quattro ruoli, poi tredici. E uno cancellato. E una chiave con scritto B.d.G."},"use":[{"if":"!flag.lista_letta","do":["@dialogue:lista_osteria"]},{"do":["Abbiamo letto tutto. Ora tocca a Firenze."]}],"items":{"lista17":[{"if":"!flag.lista_letta","do":["@dialogue:lista_osteria"]},{"do":["L'abbiamo letta. La so quasi a memoria."]}]}},{"id":"foto_muro","name":"Foto alle pareti","rect":[700,200,160,140],"art":{"k":"frame","c":"#a89878"},"col":"photo_07"},{"id":"cucina","name":"Porta della cucina","rect":[1660,280,160,420],"art":{"k":"door","label":"CUCINA","c":"#6a3a20"},"look":{"beps":"Da lì escono profumi che dovrebbero essere vietati dopo le undici.","kiki":"Fiorella ha ottant'anni e comanda quella cucina come un generale."}},{"id":"vino","name":"Fiasco di vino","rect":[460,660,60,80],"art":{"k":"candle","c":"#4a1a1a"},"look":{"beps":"Vino della casa. La casa dev'essere molto allegra.","kiki":"Un bicchiere. Uno. Domani si torna a Firenze."}},{"id":"tovaglia","name":"Tovaglia a quadri","rect":[300,720,380,200],"look":{"beps":"Quadri rossi e bianchi. La tovaglia ufficiale dell'amore italiano, secondo Hollywood.","kiki":"Ci hai fatto cadere la carbonara sopra. Due volte."}},{"id":"uscita","name":"Esci","rect":[0,640,80,420],"art":{"k":"exit"},"exit":{"to":"c3_piazza"},"arrow":"l"}]},"c4_studio":{"bg":"assets/backgrounds/bg_studio_architettura_firenze_clean.jpg","name":"Ufficio della ditta (devastato)","place":"Oltrarno · Firenze · dicembre 2026","chapter":4,"music":"tension","ambience":"rain","art":{"type":"interior","time":"day","wall":"#5e4a36","floor":"#3e2c1e","horizon":680,"wallpaper":true,"light":[{"x":1250,"y":330,"r":480,"c":"#d8e4ff","a":0.25}],"layers":[{"k":"papers","x":400,"y":880,"w":420,"h":120},{"k":"papers","x":1100,"y":900,"w":380,"h":110},{"k":"boxes","x":1620,"y":760,"w":240,"h":200}]},"walk":[[600,1080],[1760,1080],[1760,960],[1600,950],[1500,860],[1350,790],[850,780],[820,820],[700,860]],"scale":[790,0.62,1080,1],"spawn":{"default":[1000,930],"from_c4_ponte":[1650,1010,"l"]},"switch":false,"switchMsg":"Kiki non è qui.","firstEnter":["beps[surprised]: Il mio ufficio.","kiki[worried]: Beps…","narr: Cassetti rovesciati, disegni strappati, il plastico del palazzo spaccato in due. Il vecchio computer trovato nella stanza murata è sparito: sulla scrivania è rimasto solo il terminale di Beps.","beps[angry]: Il computer del palazzo. Si sono presi quello.","kiki: Ma la chiavetta ce l'hai tu. Non hanno niente.","kiki[worried]: Vado a vedere se hanno visitato anche casa mia. È a dieci minuti. Torno subito.",{"choice":[{"label":"«Vengo con te.»","do":["kiki: No. Tu resta qui e cerca quello che non hanno trovato. Tu conosci questo posto. Dieci minuti.","@stat:legame+1"]},{"label":"«Va bene. Stai attenta.»","do":["kiki[smile]: Sono sempre attenta. Dieci minuti.","@stat:fiducia+1"]}]},"@hide:kiki","@lockswitch","narr: Kiki esce. La porta si chiude. L'ufficio è silenzioso come un cantiere la domenica.","@objective:o4_studio"],"hotspots":[{"id":"scrivania","name":"Scrivania","rect":[100,600,750,300],"art":{"k":"desk","items":false},"at":[760,930],"look":"La mia scrivania. Il computer non c'è più. Al suo posto, un biglietto.","use":"Hanno svuotato i cassetti. Le mie matite sono ovunque. Le ritroverò fra tre anni sotto un mobile."},{"id":"biglietto","name":"Biglietto","rect":[560,640,80,50],"art":{"k":"letter","overlay":true},"col":"doc_10"},{"id":"pacco","name":"Pacco di Sandro","rect":[1180,900,120,100],"art":{"k":"crate","c":"#a8865a","label":"S.","overlay":true},"if":"!flag.got_sigillo_c","at":[1150,1040],"look":"Un pacco con un biglietto: «Beps, l'ho trovato nel muro dopo che sei andato via. Io non lo tocco più. — Sandro».","use":["@anim:pickup","Dentro, avvolto in un giornale del '66: un quarto di cerchio di bronzo rosso. Sul bordo: VOL.","beps[think]: Uno nel muro dove l'acqua si fermò. Eccolo.","@give:sigillo_c","@clue:frammento_cantiere","@wait:600","@dialogue:sms_kiki"]},{"id":"plastico","name":"Plastico distrutto","rect":[290,510,180,90],"art":{"k":"boxes"},"at":[700,950],"look":["Il plastico del palazzo. Spaccato con un colpo solo, nel punto esatto della stanza murata.","Non cercavano. Volevano dirmi qualcosa."]},{"id":"finestra","name":"Finestra","rect":[500,90,770,400],"art":{"k":"window","time":"rain","rain":true},"look":"Piove ancora. Kiki è uscita senza ombrello."},{"id":"lavagna","name":"Bacheca","rect":[1380,160,320,370],"art":{"k":"corkboard"},"look":"Hanno strappato tutto tranne un foglio: il disegno del Ponte Vecchio che avevo fatto a quindici anni. Gentili."},{"id":"telefono","name":"Telefono","rect":[800,700,60,40],"art":{"k":"phone","overlay":true},"at":[760,930],"look":"Il mio telefono. Nessun messaggio di Kiki.","use":[{"if":"flag.sms_ricevuto","do":["Rileggo il messaggio. «Non cercarmi. Sto bene. — Federica.» Kiki non firma mai Federica."]},{"do":["La chiamo… squilla a vuoto. Le scrivo: «Tutto ok?»"]}]},{"id":"porta","name":"Porta dell'ufficio","rect":[1740,110,180,880],"art":{"k":"door","label":"UFFICIO"},"at":[1700,1000],"exit":{"to":"c4_ponte","if":"flag.sms_ricevuto","else":["Kiki ha detto dieci minuti. Aspetto ancora un po'… e intanto guardo cosa hanno lasciato."]}}],"bgFilter":"saturate(0.75) brightness(0.92) hue-rotate(8deg)"},"c4_ponte":{"name":"Ponte Vecchio","place":"Firenze · mattina d'inverno","chapter":4,"music":"firenze","ambience":"city","art":{"type":"exterior","time":"day","horizon":560,"ground":"#7a6a58","skyline":160,"sky":["#9ab0c8","#e0d8c8"],"layers":[{"k":"building","x":0,"y":200,"w":700,"h":480,"c":"#c89050","seed":"pv1","lit":0.9},{"k":"building","x":1220,"y":200,"w":700,"h":480,"c":"#b88048","seed":"pv2","lit":0.9},{"k":"river","x":700,"y":520,"w":520,"h":160,"c":"#5a7080"},{"k":"railing","x":700,"y":640,"w":520,"h":70,"c":"#8a7a62"}]},"walk":[[0,1060],[1920,1060],[1920,780],[0,780]],"scale":[760,0.76,1060,1.02],"spawn":{"default":[960,920],"from_c4_studio":[160,920,"r"],"from_c4_banca":[1780,920,"l"],"from_c4_corridoio":[1000,860]},"npcs":[{"id":"neri","x":420,"y":830,"dir":"r","talk":"neri","look":"Mastro Neri, orafo. Occhiali da lente, grembiule di pelle, mani da chirurgo."}],"hotspots":[{"id":"bottega","name":"Bottega di Mastro Neri","rect":[140,360,360,330],"art":{"k":"stall","c":"#5a2a1a"},"look":"La bottega Neri: «Orafi dal 1897». Anelli, spille, un medaglione d'ottone in vetrina identico al nostro, ma intero e falso."},{"id":"banco","name":"Banco da orafo","rect":[520,600,200,140],"art":{"k":"counter","c":"#3a2a1a"},"at":[620,860],"look":"Il banco di lavoro di Mastro Neri. Bulini, cannello, un tappetino di cuoio con le impronte di centinaia di gioielli.","use":[{"if":"puzzle.c4_sigillo","do":["Il Sigillo è ricomposto. Il banco ha fatto il suo dovere."]},{"if":"!flag.neri_banco","do":["Non posso usare il banco di un orafo senza chiedere all'orafo."]},{"if":"item.sigillo_a && item.sigillo_b && item.sigillo_c && item.sigillo_d","do":["@anim:use","Stendo i quattro frammenti sul cuoio.","@puzzle:c4_sigillo"]},{"do":["Mi mancano dei frammenti. Ne servono quattro: Roma, la banca, il muro e quello di Neri."]}]},{"id":"vetrina","name":"Vetrina con foto","rect":[380,420,80,70],"art":{"k":"frame","c":"#c8b898","overlay":true},"col":"photo_08"},{"id":"cellini","name":"Busto di Cellini","rect":[880,300,160,340],"art":{"k":"statue","c":"#5a5040"},"look":"Benvenuto Cellini, il più grande orafo del Rinascimento e il più grande attaccabrighe di Firenze. Guarda il fiume come uno che ha un conto in sospeso."},{"id":"lucchetti","name":"Lucchetti","rect":[880,640,160,60],"look":"Lucchetti degli innamorati sulla cancellata. Il Comune li toglie, gli innamorati li rimettono. Una guerra che nessuno vincerà."},{"id":"arno","name":"Arno","rect":[700,520,520,120],"look":"Dal Ponte Vecchio, l'Arno sembra immobile. Nel '44 questo era l'unico modo per attraversarlo. Nel '66 è passato sopra."},{"id":"porta_corridoio","name":"Porticina del Corridoio Vasariano","rect":[1240,340,120,220],"art":{"k":"door","c":"#4a3a28"},"at":[1300,840],"exit":{"to":"c4_corridoio","if":"flag.neri_chiave","else":["Una porticina di servizio che sale al Corridoio Vasariano. Chiusa. Mastro Neri dovrebbe saperne qualcosa."]}},{"id":"verso_studio","name":"Verso l'Oltrarno (ufficio)","rect":[0,760,90,300],"art":{"k":"exit"},"exit":{"to":"c4_studio"},"arrow":"l"},{"id":"verso_banca","name":"Por Santa Maria (Banca del Giglio)","rect":[1830,760,90,300],"art":{"k":"exit"},"exit":{"to":"c4_banca"},"arrow":"r"}]},"c4_banca":{"name":"Banca del Giglio — Cassette di sicurezza","place":"Via Por Santa Maria · Firenze","chapter":4,"music":"mystery","ambience":"room","art":{"type":"interior","time":"day","wall":"#8a8478","floor":"#4a4440","horizon":650,"wainscot":true,"light":[{"x":960,"y":200,"r":700,"c":"#f0f4ff","a":0.3}],"layers":[{"k":"deposit","x":300,"y":160,"w":1320,"h":470,"c":"#8a7a5a","cols":12,"rows":5}]},"walk":[[80,1060],[1860,1060],[1780,720],[160,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c4_ponte":[200,920,"r"]},"npcs":[{"id":"bellandi","x":1400,"y":860,"dir":"l","talk":"bellandi","look":"La dottoressa Bellandi. Tailleur blu, occhiali sottili, un badge plastificato con la foto più seria della storia della fotografia."}],"hotspots":[{"id":"cassette","name":"Parete delle cassette","rect":[300,160,1320,470],"look":"Seicento cassette di sicurezza. Ognuna con un segreto. Alcune, forse, con più segreti della banca stessa.","use":"Non posso aprire niente senza la dottoressa Bellandi. Ha l'aria di una che ha imparato il regolamento a memoria."},{"id":"cassetta17","name":"Cassetta 17","rect":[660,260,110,90],"art":{"k":"safe","c":"#a89060"},"at":[720,860],"look":"La cassetta 17. Ottone brunito, serratura doppia. Una per la chiave della banca, una per la chiave del cliente.","use":[{"if":"flag.cassetta_aperta","do":["Vuota, ormai. Ottant'anni di attesa e io l'ho svuotata in due minuti."]},{"do":["Devo prima parlare con la dottoressa Bellandi."]}],"items":{"chiave_ottone":[{"if":"flag.cassetta_aperta","do":["Già aperta."]},{"do":["La dottoressa Bellandi mi fulmina con lo sguardo. «Prima la procedura, signore.»"]}]}},{"id":"registro","name":"Registro degli accessi","rect":[1180,640,80,50],"art":{"k":"book","c":"#1e2a3a","overlay":true},"col":"doc_11"},{"id":"telecamera","name":"Telecamera","rect":[1700,120,90,70],"art":{"k":"projector"},"look":"Una telecamera di sorveglianza. Saluto. Non risponde. Tipico."},{"id":"quadro","name":"Quadro","rect":[120,220,150,200],"art":{"k":"painting","c":"#3a4a3a","seed":"bg"},"look":"Il fondatore della banca, 1872. Ha la faccia di uno che ha appena prestato soldi a un Medici e se n'è pentito."},{"id":"orologio","name":"Orologio","rect":[1700,300,110,110],"art":{"k":"clock"},"look":"Mezzogiorno. Kiki è sparita da due ore."},{"id":"uscita","name":"Esci","rect":[0,640,80,420],"art":{"k":"exit"},"exit":{"to":"c4_ponte"},"arrow":"l"}]},"c4_corridoio":{"name":"Corridoio Vasariano","place":"Sopra il Ponte Vecchio · Firenze","chapter":4,"music":"mystery","ambience":"wind","fx":[{"k":"light","x":400,"y":60,"w":300,"h":900},{"k":"light","x":1200,"y":60,"w":300,"h":900},"dust"],"art":{"type":"interior","time":"day","wall":"#c8bca4","floor":"#7a6a58","horizon":640,"wainscot":false,"vanish":960,"light":[{"x":960,"y":300,"r":700,"c":"#fff4dc","a":0.3}],"layers":[{"k":"painting","x":120,"y":160,"w":160,"h":200,"seed":"v1"},{"k":"painting","x":1640,"y":160,"w":160,"h":200,"seed":"v2"},{"k":"painting","x":340,"y":200,"w":120,"h":160,"seed":"v3"}]},"walk":[[80,1060],[1840,1060],[1180,700],[740,700]],"scale":[700,0.66,1060,1],"spawn":{"default":[960,960],"from_c4_ponte":[960,1000]},"firstEnter":["Il Corridoio Vasariano. Un chilometro sospeso sopra Firenze, costruito perché i Medici non dovessero camminare in mezzo alla gente.","Nel '44, Orfeo ci faceva passare proprio la gente."],"hotspots":[{"id":"finestre","name":"Finestre sul fiume","rect":[520,180,240,220],"art":{"k":"window","time":"day","city":true},"look":"Le finestrelle sull'Arno. Da qui vedo il punto in cui io e Kiki ci siamo seduti su una panchina bagnata. Un secolo fa, sembra."},{"id":"autoritratti","name":"Autoritratti","rect":[100,140,380,260],"look":"La collezione di autoritratti degli Uffizi. Centinaia di pittori che si guardano allo specchio. Nessuno sembra soddisfatto."},{"id":"graffito","name":"Elenco graffito","rect":[1500,420,90,70],"art":{"k":"papers","overlay":true},"col":"doc_12"},{"id":"lira_finestra","name":"Lira incisa","rect":[780,300,50,50],"art":{"k":"symbol","c":"#5a4a3a","a":0.5},"col":"sym_4"},{"id":"porta_orfeo","name":"Porta di Orfeo","rect":[880,300,160,340],"art":{"k":"door","c":"#2a1a10","label":"◯"},"at":[960,760],"look":"In fondo al corridoio, una porta che non è nelle piante degli Uffizi. Al posto della serratura, un incavo rotondo con una lira. La misura di un sigillo.","use":[{"if":"item.sigillo","do":["Ho il Sigillo. Lo appoggio nell'incavo?"]},{"do":["Nessuna maniglia. Solo un incavo rotondo, a forma di sigillo."]}],"items":{"sigillo":["@anim:use","@sfx:mechanism","Appoggio il Sigillo. Combacia. Un giro…","narr: Un rumore di ingranaggi antichi. La porta si apre su una scala che scende verso il giardino di Boboli.","@flag:porta_orfeo","@goto:c4_grotta"]}},{"id":"uscita","name":"Torna al Ponte","rect":[860,990,200,70],"art":{"k":"exit"},"exit":{"to":"c4_ponte"},"arrow":"d"}]},"c4_grotta":{"name":"Grotta del Buontalenti","place":"Giardino di Boboli · Firenze","chapter":4,"music":"tension","ambience":"water","fx":["dust","fog"],"art":{"type":"underground","time":"dusk","wall":"#6a6450","floor":"#3a3428","horizon":680,"light":[{"x":960,"y":120,"r":600,"c":"#e8f0c8","a":0.35}],"layers":[{"k":"statue","x":180,"y":260,"w":200,"h":440,"c":"#c8c0b0"},{"k":"statue","x":1560,"y":260,"w":200,"h":440,"c":"#c8c0b0","flip":true},{"k":"fountain","x":760,"y":520,"w":400,"h":220}]},"walk":[[100,1060],[1820,1060],[1700,740],[220,740]],"scale":[740,0.74,1060,1],"spawn":{"default":[300,940,"r"],"from_c4_corridoio":[260,940,"r"]},"switch":false,"switchMsg":"Non adesso.","npcs":[{"id":"varano_g","char":"varano","x":1260,"y":860,"dir":"l","if":"!flag.varano_grotta_via","talk":"varano_c4","look":"Il Notaio. In piedi accanto alla fontana, le mani nei guanti, come se aspettasse un treno in ritardo."},{"id":"kiki_g","char":"kiki","name":"Kiki","x":1500,"y":880,"dir":"l","if":"!flag.kiki_liberata","look":"Kiki. Seduta su una panca di pietra. Sta bene. Mi guarda come se fossi arrivato in ritardo, il che è vero."}],"firstEnter":["beps[surprised]: Kiki!","kiki: Beps! Sto bene. Non ha… non mi ha fatto niente.","varano: Giuseppe. Ha trovato la porta. Ha ricomposto il Sigillo. Sono quasi orgoglioso.","@dialogue:varano_c4"],"hotspots":[{"id":"statue","name":"Statue","rect":[180,260,200,440],"look":{"beps":"Copie dei Prigioni di Michelangelo, mezzi intrappolati nella pietra. Mi sento così da una settimana.","kiki":"I Prigioni. Mezzi fuori, mezzi dentro. Come noi in questa storia."}},{"id":"stalattiti","name":"Stalattiti","rect":[400,40,1100,200],"look":{"beps":"Stalattiti finte del Cinquecento: spugna, conchiglie, tufo. Buontalenti ha costruito una grotta per far sembrare la natura più naturale.","kiki":"Una grotta finta che sembra più vera di quelle vere. Ha senso, in questa storia."}},{"id":"venere","name":"Venere del Giambologna","rect":[880,300,160,240],"art":{"k":"statue","c":"#f0e8d8"},"look":{"beps":"Venere che esce dal bagno. Quattro satiri la spiano dall'alto. Il Cinquecento non aveva il concetto di privacy.","kiki":"Giambologna. Bellissima. I satiri sono inquietanti, però."}},{"id":"dittafono","name":"Dittafono caduto","rect":[1180,940,60,40],"art":{"k":"recorder","overlay":true},"if":"flag.varano_grotta_via","col":"rec_04"},{"id":"uscita","name":"Giardino di Boboli","rect":[1840,640,80,420],"art":{"k":"exit"},"arrow":"r","exit":{"to":"c4_grotta","if":"false","else":[{"if":"flag.kiki_liberata","do":["@dialogue:c4_fine"],"else":{"beps":["Prima parliamo. Io e Kiki."],"kiki":["Aspetta, Beps. Prima parliamo."]}}]}}]},"c5_galata":{"name":"Molo di Karaköy","place":"Istanbul · dicembre 2026, tramonto","chapter":5,"music":"istanbul","ambience":"water","art":{"type":"exterior","time":"dusk","horizon":560,"ground":"#5a5048","skyline":280,"sky":["#3a3a6a","#f0a060"],"sun":[1500,420],"layers":[{"k":"water","x":0,"y":520,"w":1920,"h":200,"c":"#3a4a6a"},{"k":"tower","x":1180,"y":120,"w":130,"h":420,"c":"#8a7a68"},{"k":"dome","x":220,"y":300,"w":320,"h":240,"c":"#6a7480"},{"k":"minaret","x":160,"y":200,"w":50,"h":340},{"k":"minaret","x":560,"y":200,"w":50,"h":340},{"k":"boat","x":700,"y":560,"w":420,"h":140,"c":"#e8e4dc"},{"k":"railing","x":0,"y":680,"w":1920,"h":70,"c":"#3a3a3a"}]},"walk":[[0,1060],[1920,1060],[1920,790],[0,790]],"scale":[770,0.76,1060,1.02],"spawn":{"default":[500,920,"r"],"from_c5_bazar":[1780,920,"l"]},"firstEnter":["kiki: Istanbul. Nonna diceva che è l'unica città dove il tramonto dura un'ora.","beps: Il Traduttore. Dove lo troviamo?","kiki: Nonna diceva sempre «al Bazar, dove vendono il tempo». Credo fosse un antiquario.","@objective:o5_bazar"],"hotspots":[{"id":"traghetto","name":"Traghetto","rect":[700,540,420,160],"look":{"beps":"Il vapur, il traghetto di linea. Bianco, ruggine, gabbiani. Venti minuti tra due continenti, al prezzo di un caffè.","kiki":"Ci siamo arrivati in traghetto da Kadıköy. Ho pianto un po'. Non dirlo a nessuno."}},{"id":"torre","name":"Torre di Galata","rect":[1180,120,130,420],"look":{"beps":"La Torre di Galata, genovese, 1348. Un italiano ha costruito il punto più alto della città più bella del mondo. Lo dico con orgoglio campanilistico.","kiki":"Ci saliva nonna, ogni dicembre. Diceva che da lassù si vede «dove finisce l'Europa»."}},{"id":"moschea","name":"Moschea","rect":[160,200,450,340],"look":{"beps":"Una cupola, quattro semicupole, due minareti. È come un codice scritto bene: niente di troppo, niente che manchi.","kiki":"Il richiamo alla preghiera sta per cominciare. Ascoltalo. Non c'è niente di simile."}},{"id":"pescatori","name":"Pescatori","rect":[1400,600,480,140],"look":{"beps":"Una fila di pescatori sul ponte, canne lunghissime, secchi pieni di sgombri. Stanno lì da secoli, credo.","kiki":"Uno di loro ha preso uno stivale. Lo tiene comunque."}},{"id":"simit","name":"Carretto dei simit","rect":[1600,760,220,180],"art":{"k":"stall","c":"#c03020"},"at":[1700,960],"look":{"beps":"Il carretto rosso dei simit, le ciambelle al sesamo. Odore di forno e di felicità.","kiki":"Simit. Nonna ne portava sempre un sacchetto, al ritorno. Erano duri come sassi, ma li mangiavo lo stesso."},"use":[{"if":"!flag.simit","do":["@flag:simit","Due simit, per favore. … Uno per me, uno per Kiki.",{"if":"present.kiki","do":["kiki[tender]: Sono caldi. Quelli di nonna non erano mai caldi.","@stat:legame+1"]}]},{"do":["Ne ho già mangiati due. Il terzo sarebbe un problema strutturale."]}]},{"id":"chiosco","name":"Cartoline al chiosco","rect":[300,760,120,120],"art":{"k":"stall","c":"#2a4a6a"},"col":"photo_10"},{"id":"gabbiani","name":"Gabbiani","rect":[600,120,400,160],"look":{"beps":"Gabbiani grandi come cani. Uno mi fissa il simit con intenzioni chiare.","kiki":"Non guardarli negli occhi. È un consiglio di nonna, valido per gabbiani e notai."}},{"id":"verso_bazar","name":"Verso il Gran Bazar","rect":[1830,760,90,300],"art":{"k":"exit"},"exit":{"to":"c5_bazar"},"arrow":"r"}]},"c5_bazar":{"name":"Gran Bazar","place":"Istanbul","chapter":5,"music":"istanbul","ambience":"crowd","fx":[{"k":"light","x":820,"y":0,"w":300,"h":900},"dust"],"art":{"type":"interior","time":"evening","wall":"#a87a4a","floor":"#5a4030","horizon":640,"wainscot":false,"vanish":960,"beams":true,"light":[{"x":960,"y":280,"r":700,"c":"#ffc870","a":0.45}],"layers":[{"k":"arch","x":600,"y":40,"w":720,"h":620,"c":"#c8a070","inner":"#3a2418"},{"k":"stall","x":60,"y":420,"w":480,"h":320,"c":"#6a2a3a"},{"k":"stall","x":1380,"y":420,"w":480,"h":320,"c":"#2a4a6a"}]},"walk":[[60,1060],[1860,1060],[1240,720],[680,720]],"scale":[700,0.68,1060,1],"spawn":{"default":[960,960],"from_c5_galata":[160,960,"r"],"from_c5_antiquario":[1600,940,"l"],"from_c5_han":[960,900]},"npcs":[{"id":"emre","x":1300,"y":900,"dir":"l","talk":"emre","look":{"beps":"Un ragazzino con un vassoio di bicchierini di tè appeso a tre catenelle. Corre senza versarne una goccia. Un fenomeno della fisica.","kiki":"Il ragazzo del tè. Sa tutto di tutti, nei bazar è sempre così."}}],"hotspots":[{"id":"lampade","name":"Lampade","rect":[60,120,480,280],"art":{"k":"chandelier"},"look":{"beps":"Centinaia di lampade di vetro colorato. Se ne compro una, Kiki mi lascia.","kiki":"Bellissime. Non comprarne nessuna, Beps. Non abbiamo spazio in valigia. Non abbiamo una valigia."}},{"id":"spezie","name":"Banco delle spezie","rect":[1380,420,480,320],"at":[1500,900],"look":{"beps":"Piramidi di spezie: sumac, pul biber, zafferano finto e zafferano vero. Il venditore mi ha già dato del «dottore» tre volte.","kiki":"Se ti chiama dottore vuol dire che ti vuole vendere lo zafferano finto."}},{"id":"cassa","name":"Cassa da spedizione","rect":[1560,760,140,110],"art":{"k":"crate","c":"#7a5a3a","label":"FIRENZE"},"col":"doc_13"},{"id":"tappeti","name":"Tappeti","rect":[60,420,480,320],"look":{"beps":"Tappeti a pile, fino al soffitto. Il venditore dice che questo è volante. Gli ho chiesto una dimostrazione. Si è offeso.","kiki":"Nonna diceva che veniva qui a comprare tappeti. Non abbiamo mai avuto un tappeto."}},{"id":"donna","name":"Donna in nero","rect":[900,420,90,260],"art":{"k":"figure","hat":true,"c":"#0a0a0c"},"if":"!flag.woman_4","look":{"beps":"In fondo al corridoio. Abito nero, cappello. Ci guarda.","kiki":"È lei. Di nuovo. Beps, stavolta la prendiamo."},"use":["@walk:940,760","@anim:reaction","narr: Tra la folla, un cappello nero. Poi un altro corridoio, un'altra folla, niente.","beps[surprised]: Sparita. Ha lasciato… cinquecento lire. Sul banco delle lampade.",{"if":"present.kiki","do":["kiki[worried]: Il cappello di nonna è a Parigi. Hélène non sopporta Istanbul. Chi è, Beps? Chi è?"]},"@flag:woman_4","@clue:donna_istanbul","@stat:conoscenza+1"]},{"id":"verso_antiquario","name":"Bottega dell'antiquario","rect":[1830,760,90,300],"art":{"k":"exit"},"exit":{"to":"c5_antiquario"},"arrow":"r"},{"id":"verso_han","name":"Büyük Valide Han","rect":[880,700,160,70],"art":{"k":"exit"},"arrow":"u","exit":{"to":"c5_han","if":"flag.selim_camera","else":{"beps":["Un corridoio che sale verso un vecchio caravanserraglio. Prima vorrei sapere cosa cerchiamo."],"kiki":["Prima troviamo il Traduttore."]}}},{"id":"verso_galata","name":"Verso il molo","rect":[0,760,90,300],"art":{"k":"exit"},"exit":{"to":"c5_galata"},"arrow":"l"}]},"c5_antiquario":{"name":"Bottega di Selim Aydın","place":"Gran Bazar · Istanbul","chapter":5,"music":"istanbul","ambience":"room","art":{"type":"interior","time":"evening","wall":"#6a4a3a","floor":"#3a2a20","horizon":650,"wallpaper":true,"light":[{"x":760,"y":320,"r":600,"c":"#ffc080","a":0.45}],"layers":[{"k":"shelves","x":60,"y":100,"w":460,"h":560,"c":"#4a2a1a","seed":"an"},{"k":"rug","x":500,"y":860,"w":900,"h":160,"c":"#7a2a2a"},{"k":"chandelier","x":860,"y":0,"w":180,"h":150}]},"walk":[[80,1060],[1860,1060],[1780,720],[160,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c5_bazar":[200,920,"r"]},"npcs":[{"id":"selim","x":1280,"y":860,"dir":"l","talk":"selim","look":{"beps":"Un signore elegante sui settanta, gilet viola, baffi bianchi perfetti. Lucida un orologio con la cura di un chirurgo.","kiki":"Selim Aydın. Nonna lo chiamava «il mio traduttore»."}}],"firstEnter":["@dialogue:selim"],"hotspots":[{"id":"grammofono","name":"Grammofono","rect":[560,480,200,240],"art":{"k":"phonograph"},"col":"rec_05"},{"id":"orologio","name":"Orologio ottomano","rect":[1500,200,160,200],"art":{"k":"clock"},"look":{"beps":"Un orologio con le ore in numeri ottomani. Ferma alle sei e dodici. «Il tempo qui si vende, non si usa», dice Selim.","kiki":"«Al Bazar, dove vendono il tempo.» Nonna intendeva questo."}},{"id":"mappe","name":"Mappe antiche","rect":[800,160,380,220],"art":{"k":"painting","c":"#d8c49a","seed":"map"},"look":{"beps":"Carte nautiche del Mediterraneo. Una ha una rotta tracciata a matita: Livorno, Pireo, Istanbul. Datata 1944.","kiki":"La rotta di Orfeo. Da Firenze al mare, dal mare a qui. Quante persone ci sono passate?"}},{"id":"foto_1989","name":"Fotografia incorniciata","rect":[1560,440,110,140],"art":{"k":"frame","c":"#d8c8a8"},"col":"photo_09"},{"id":"gatto","name":"Gatto","rect":[400,820,120,80],"art":{"k":"figure","c":"#d8d0c0"},"look":{"beps":"Un altro gatto. Bianco, stavolta. Comincio a sospettare un complotto felino internazionale.","kiki":"Si chiama Yasemin. Gelsomino. Mi sta annusando le scarpe con disapprovazione."},"use":[{"if":"!flag.gatto_selim","do":["@flag:gatto_selim",{"if":"active=='beps'","do":["Lo accarezzo. Starnutisco. Selim ride per un minuto intero."],"else":["kiki: Fusa. Bene. Almeno lui si fida."]}]},{"do":["Yasemin dorme. Non disturbiamo un'autorità."]}]},{"id":"narghile","name":"Narghilè","rect":[1100,640,100,180],"art":{"k":"candle","c":"#4a6a8a"},"look":{"beps":"Un narghilè d'argento. Non fumo. Ma come oggetto di design, ha la mia approvazione.","kiki":"Selim dice che è del Settecento. Selim dice molte cose."}},{"id":"tappeto","name":"Tappeto arrotolato","rect":[180,780,200,120],"art":{"k":"rug","c":"#6a3a5a"},"look":{"beps":"«È volante», dice Selim. Gli ho chiesto se ha l'omologazione ENAC. Non ha capito. Meglio così.","kiki":"Nessun tappeto vola. Ma questo, forse, ci pensa."}},{"id":"uscita","name":"Torna al Bazar","rect":[0,640,80,420],"art":{"k":"exit"},"exit":{"to":"c5_bazar"},"arrow":"l"}]},"c5_han":{"name":"Büyük Valide Han","place":"Istanbul · crepuscolo","chapter":5,"music":"istanbul","ambience":"wind","art":{"type":"exterior","time":"dusk","horizon":600,"ground":"#6a5a48","skyline":80,"sky":["#2a2a5a","#d88a5a"],"cobbles":true,"layers":[{"k":"column_row","x":0,"y":200,"w":1920,"h":480},{"k":"arch","x":760,"y":200,"w":400,"h":480,"c":"#8a7a62","inner":"#2a2018"},{"k":"tree","x":1560,"y":380,"w":280,"h":340,"c":"#3a5a3a"}]},"walk":[[0,1060],[1920,1060],[1920,780],[0,780]],"scale":[760,0.76,1060,1.02],"spawn":{"default":[960,920],"from_c5_bazar":[960,980],"from_c5_tetto":[300,900,"r"],"from_c5_cisterna":[1000,860]},"firstEnter":["kiki: Il Büyük Valide Han. Un caravanserraglio del Seicento. Mercanti, cammelli, laboratori di tessitori. E, secondo Selim, una porta per il sottosuolo."],"hotspots":[{"id":"botola","name":"Botola","rect":[880,820,180,100],"art":{"k":"vent"},"at":[960,960],"look":{"beps":"Una botola di ferro nel pavimento, con un anello arrugginito. Saldata dalla ruggine.","kiki":"La botola di Selim. Arrugginita."},"use":[{"if":"flag.botola_aperta && item.lanterna","do":["@goto:c5_cisterna"]},{"if":"flag.botola_aperta","do":["Di sotto è buio pesto. Senza luce non scendo."]},{"do":["Tiro l'anello… niente. È saldata dalla ruggine. Servirebbe una leva."]}],"items":{"piede_porco":[{"if":"flag.botola_aperta","do":["È già aperta."]},{"if":"active=='beps'","do":["@anim:use","@sfx:door","beps: Leva, fulcro, forza. Archimede sarebbe fiero. La botola si apre con un gemito.","@flag:botola_aperta","@objective:o5_scendi"]},{"do":["kiki: Ci provo… niente. Beps, questo è un lavoro per te.","@objective:o5_botola_beps"]}],"lanterna":[{"if":"flag.botola_aperta","do":["@goto:c5_cisterna"]},{"do":["Prima bisogna aprirla."]}]}},{"id":"pozzo","name":"Vecchio pozzo","rect":[1300,700,180,200],"art":{"k":"fountain"},"look":{"beps":"Un pozzo con la vera in marmo. Getto un sassolino… plic. Dopo tre secondi. Profondo.","kiki":"Sotto tutta Istanbul ci sono cisterne. Una città sotto la città."}},{"id":"nicchia","name":"Nicchia nel muro","rect":[520,480,70,70],"art":{"k":"papers","overlay":true},"col":"doc_14"},{"id":"tessitori","name":"Laboratorio dei tessitori","rect":[80,420,400,280],"look":{"beps":"Telai a mano. Un vecchio tesse un tappeto con un motivo che sembra… una lira.","kiki":"Il vecchio mi ha sorriso e ha fatto il segno della lira con le dita. Qui lo sanno tutti, chi siamo."}},{"id":"piccioni","name":"Piccioni","rect":[1200,200,300,140],"look":{"beps":"Piccioni turchi. Più educati di quelli di Parigi, meno di quelli di Firenze.","kiki":"Ti fai sempre giudicare dai piccioni, l'hai notato?"}},{"id":"scala_tetto","name":"Scala per il tetto","rect":[0,700,90,360],"art":{"k":"exit"},"exit":{"to":"c5_tetto"},"arrow":"l"},{"id":"verso_bazar","name":"Torna al Bazar","rect":[860,1000,200,60],"art":{"k":"exit"},"exit":{"to":"c5_bazar"},"arrow":"d"}]},"c5_tetto":{"name":"Il tetto dell'Han","place":"Istanbul · notte sul Corno d'Oro","chapter":5,"music":"tender","ambience":"wind","art":{"type":"exterior","time":"night","horizon":640,"ground":"#4a4440","skyline":300,"stars":true,"cobbles":false,"light":[{"x":1500,"y":140,"r":300,"c":"#f0e8d0","a":0.25}],"layers":[{"k":"water","x":0,"y":600,"w":1920,"h":80,"c":"#1a2a4a"},{"k":"dome","x":600,"y":360,"w":380,"h":280,"c":"#3a4a5a"},{"k":"minaret","x":540,"y":240,"w":50,"h":400},{"k":"minaret","x":990,"y":240,"w":50,"h":400},{"k":"dome","x":120,"y":440,"w":240,"h":200,"c":"#3a4a5a"},{"k":"railing","x":0,"y":690,"w":1920,"h":60,"c":"#2a2a2a"}]},"walk":[[0,1060],[1920,1060],[1920,800],[0,800]],"scale":[780,0.8,1060,1.02],"spawn":{"default":[800,920,"r"],"from_c5_han":[1700,920,"l"]},"firstEnter":[{"if":"!flag.tetto_scena","do":["@dialogue:tetto"]}],"hotspots":[{"id":"panorama","name":"Il Corno d'Oro","rect":[0,360,1920,320],"look":{"beps":"Istanbul di notte. Le moschee illuminate come lanterne, i traghetti che si incrociano senza scontrarsi mai. È come guardare un orologio enorme.","kiki":"Nonna diceva che da qui si vede dove finisce l'Europa. Io vedo solo dove comincia qualcos'altro."}},{"id":"comignolo","name":"Comignolo","rect":[1300,600,120,200],"art":{"k":"pillar","c":"#6a5a4a"},"look":{"beps":"Un comignolo di mattoni. C'è un foglio arrotolato infilato tra i mattoni. Qualcuno ci teneva a nasconderlo bene.","kiki":"C'è qualcosa infilato tra i mattoni."}},{"id":"lettera_comignolo","name":"Foglio arrotolato","rect":[1340,640,50,40],"art":{"k":"letter","overlay":true},"col":"doc_15"},{"id":"stendino","name":"Stendibiancheria","rect":[200,680,300,200],"art":{"k":"rope"},"look":{"beps":"Qualcuno stende i panni sul tetto di un caravanserraglio del Seicento. Rispetto.","kiki":"Un lenzuolo che sventola come una vela. Stasera tutto sembra un simbolo."}},{"id":"gabbiano","name":"Gabbiano","rect":[1600,640,100,80],"art":{"k":"figure","c":"#e8e8e8"},"look":{"beps":"Un gabbiano sul cornicione. Mi guarda. Lo guardo. Nessuno dei due cede.","kiki":"Ha l'aria di Monsieur Albert."}},{"id":"panchina","name":"Muretto","rect":[700,820,400,100],"art":{"k":"bench","c":"#5a5048"},"at":[900,960],"look":{"beps":"Un muretto caldo di sole anche a quest'ora. Ci si sta seduti in due. Esattamente due.","kiki":"Sediamoci. Due minuti. Ce li siamo guadagnati."},"use":[{"if":"flag.tetto_scena","do":["Ci sediamo di nuovo. Non serve parlare."]},{"do":["@dialogue:tetto"]}]},{"id":"scala","name":"Scendi nel cortile","rect":[1830,760,90,300],"art":{"k":"exit"},"exit":{"to":"c5_han"},"arrow":"r"}]},"c5_cisterna":{"name":"La cisterna","place":"Sotto il Büyük Valide Han","chapter":5,"music":"mystery","ambience":"water","fx":["fog",{"k":"light","x":700,"y":0,"w":500,"h":900}],"art":{"type":"underground","time":"night","wall":"#4a4a46","floor":"#1a2a2a","horizon":660,"light":[{"x":960,"y":560,"r":520,"c":"#ffd890","a":0.4}],"layers":[{"k":"column_row","x":0,"y":80,"w":1920,"h":600},{"k":"water","x":0,"y":680,"w":1920,"h":120,"c":"#1a3a3a"}]},"walk":[[160,1060],[1760,1060],[1640,800],[280,800]],"scale":[790,0.78,1060,1],"spawn":{"default":[400,940,"r"],"from_c5_han":[400,940,"r"],"from_c5_camera_anelli":[1500,900,"l"]},"firstEnter":["beps: Una cisterna bizantina. Colonne di riuso, ognuna da un tempio diverso. Un cantiere di mille e cinquecento anni fa.","kiki: E acqua. Ovunque. Tieni alta la lanterna."],"hotspots":[{"id":"medusa","name":"Testa di Medusa","rect":[860,640,200,160],"art":{"k":"statue","c":"#5a5a50"},"look":{"beps":"Una testa di Medusa usata come base di una colonna. Capovolta. I bizantini erano pratici: le sculture pagane diventavano mattoni.","kiki":"Medusa capovolta. Chi la guarda diventa pietra. Chi la capovolge, diventa un genio del riciclo."}},{"id":"lira_medusa","name":"Incisione sotto la Medusa","rect":[1080,740,50,50],"art":{"k":"symbol","c":"#c8c0a0","a":0.45},"col":"sym_5"},{"id":"colonne","name":"Colonne","rect":[0,80,1920,300],"look":{"beps":"Corinzie, ioniche, una con gli occhi di pavone incisi. Riuso intelligente. Il mio prof di restauro piangerebbe di gioia.","kiki":"Sembra una foresta di pietra. Ascolta: gocciola come nella stanza murata."}},{"id":"pesci","name":"Pesci","rect":[200,700,600,80],"look":{"beps":"Carpe grigie che nuotano lente. Sono qui da prima di noi. Saranno qui dopo.","kiki":"Le chiamano «i custodi». Ovvio."}},{"id":"passerella","name":"Passerella","rect":[1200,700,400,100],"look":{"beps":"Una passerella di legno sull'acqua. Porta a una porta di bronzo in fondo alla cisterna.","kiki":"Lì in fondo. La porta della Camera."}},{"id":"porta_camera","name":"Porta di bronzo","rect":[1600,380,200,340],"art":{"k":"door","c":"#5a4a2a","label":"◉"},"at":[1600,880],"exit":{"to":"c5_camera_anelli"},"arrow":"r"},{"id":"uscita","name":"Risali","rect":[160,300,140,300],"art":{"k":"stairs","c":"#4a4a46"},"at":[320,900],"exit":{"to":"c5_han"}}]},"c5_camera_anelli":{"bg":"assets/backgrounds/bg_camera_segreta_orfeo_01.jpg","name":"Camera degli Anelli","place":"Sotto Istanbul","chapter":5,"music":"mystery","ambience":"underground","fx":["dust"],"art":{"type":"underground","time":"night","wall":"#5a4a36","floor":"#2a2018","horizon":680,"light":[{"x":960,"y":420,"r":560,"c":"#ffd890","a":0.45}]},"walk":[[100,1080],[1850,1080],[1700,830],[1500,795],[420,795],[220,830]],"scale":[790,0.62,1080,1],"spawn":{"default":[420,990,"r"],"from_c5_cisterna":[320,1010,"r"]},"firstEnter":["kiki[surprised]: Anelli. Quattro anelli di bronzo uno dentro l'altro, sul muro. E al centro un incavo rotondo.","beps: Della misura di un medaglione.","@objective:o5_anelli"],"hotspots":[{"id":"anelli","name":"Meccanismo degli anelli","rect":[580,110,760,650],"art":{"k":"rings"},"at":[960,900],"look":{"beps":"Quattro anelli concentrici, ognuno con otto simboli. Una tacca rossa in alto. Il meccanismo è collegato: girando un anello, quello più interno lo segue.","kiki":"Luna, sole, lira, onda, chiave, stella, occhio, mano. Sono gli stessi simboli che… aspetta. Il retro del medaglione."},"use":[{"if":"puzzle.c5_anelli","do":["Gli anelli sono fermi sulla combinazione giusta. Il loro lavoro è finito."]},{"if":"flag.medaglione_inserito","do":["@puzzle:c5_anelli"]},{"do":["Al centro c'è un incavo rotondo. Senza qualcosa da metterci dentro, gli anelli non girano."]}],"items":{"medaglione":[{"if":"flag.medaglione_inserito","do":["@puzzle:c5_anelli"]},{"do":["@anim:use","@sfx:mechanism","Il medaglione entra nell'incavo con un clic. Gli anelli tremano: adesso girano.","@flag:medaglione_inserito",{"if":"!clue.retro_medaglione","do":["kiki[think]: Prima che lo mettessi… sul retro c'erano dei simboli. Luna, lira, onda, chiave. Dal centro verso il bordo.","@clue:retro_medaglione"]},"@puzzle:c5_anelli"]}]}},{"id":"iscrizioni","name":"Iscrizioni","rect":[430,150,140,520],"look":{"beps":"Iscrizioni in italiano, turco, francese, ebraico, greco. Tutte dicono la stessa cosa, credo.","kiki":"«Chi entra in due, esce in due.» In cinque lingue. Il Traduttore ha lasciato la firma."}},{"id":"nicchia","name":"Nicchia","rect":[1500,150,280,620],"art":{"k":"arch","c":"#6a5a40"},"look":{"beps":[{"if":"puzzle.c5_anelli","do":["La nicchia si è aperta. Dentro c'era la pianta incisa: Firenze, la stanza murata, una scala sotto il terzo gradino."]},{"do":["Una nicchia chiusa da una lastra di bronzo. Nessuna maniglia."]}],"kiki":[{"if":"puzzle.c5_anelli","do":["La Camera di Orfeo è a Firenze. Sotto la stanza murata. È sempre stata lì."]},{"do":["Chiusa. Forse si apre con gli anelli."]}]}},{"id":"lanterne","name":"Torce a muro","rect":[1410,320,120,200],"art":{"k":"candle"},"look":{"beps":"Torce di ferro fissate al muro. Qualcuno le ha accese da poco. Selim, probabilmente. O qualcun altro.","kiki":"Pece fresca. Qualcuno viene qui spesso. Più spesso di Selim."}},{"id":"uscita","name":"Torna alla cisterna","rect":[150,250,130,500],"art":{"k":"exit"},"exit":{"to":"c5_cisterna"},"arrow":"l"}]},"c6_pont_neuf":{"name":"Pont Neuf","place":"Parigi · gennaio 2027, notte di neve","chapter":6,"music":"paris","ambience":"wind","fx":["snow"],"art":{"type":"exterior","time":"night","horizon":580,"ground":"#5a5a60","skyline":220,"stars":false,"light":[{"x":500,"y":300,"r":380,"c":"#ffd890","a":0.35},{"x":1500,"y":300,"r":380,"c":"#ffd890","a":0.35}],"layers":[{"k":"river","x":0,"y":540,"w":1920,"h":140,"c":"#1a2a3a"},{"k":"statue","x":860,"y":260,"w":200,"h":420,"c":"#3a4a40"},{"k":"streetlamp","x":440,"y":300,"w":80,"h":480},{"k":"streetlamp","x":1420,"y":300,"w":80,"h":480},{"k":"railing","x":0,"y":680,"w":1920,"h":70,"c":"#4a4a4a"}]},"walk":[[0,1060],[1920,1060],[1920,790],[0,790]],"scale":[770,0.78,1060,1.02],"spawn":{"default":[960,920],"from_c6_atelier":[160,920,"r"],"from_c6_archivio":[1780,920,"l"],"from_c6_ufficio":[960,960],"from_c6_catacombe":[960,960]},"firstEnter":["kiki: Parigi sotto la neve. Sembra una cartolina che qualcuno ha dimenticato di spedire.","beps: Hélène ha detto di passare da lei prima di ogni altra cosa. «Prima di Varano. Prima di tutto.»","@objective:o6_helene"],"hotspots":[{"id":"enrico","name":"Statua di Enrico IV","rect":[860,260,200,420],"look":{"beps":"Enrico IV a cavallo, coperto di neve. Il re che disse «Parigi val bene una messa». Io direi che val bene un treno notturno.","kiki":"Sotto la statua, nel 1818, misero una scatola con dei documenti. Una capsula del tempo. I parigini nascondono le cose da sempre."}},{"id":"senna","name":"Senna","rect":[0,540,1920,120],"look":{"beps":"La Senna nera, con le luci dei lampioni che ci galleggiano sopra come monete.","kiki":"Un bateau-mouche vuoto. Solo le luci e un marinaio che fuma."}},{"id":"panchina","name":"Panchina innevata","rect":[1100,820,300,110],"art":{"k":"bench","c":"#3a3a3a"},"at":[1250,960],"look":{"beps":"Una panchina sotto la neve. Due posti.","kiki":"Ci sediamo? Due minuti. Solo noi."},"use":[{"if":"!flag.panchina_pn","do":["@flag:panchina_pn","@dialogue:panchina_pn"]},{"do":["Ci sediamo un attimo. La neve cade. Non serve dire niente."]}]},{"id":"lampione","name":"Lampione","rect":[440,300,80,480],"look":{"beps":"Un lampione di ghisa con la neve sul cappello. Sembra un vecchio signore che aspetta qualcuno.","kiki":"Come quello del Lungarno. Ma senza un uomo in grigio sotto. Per ora."}},{"id":"verso_atelier","name":"Verso il Marais (Studio Marchetti)","rect":[0,760,90,300],"art":{"k":"exit"},"exit":{"to":"c6_atelier"},"arrow":"l"},{"id":"verso_archivio","name":"Passage des Libraires","rect":[1830,760,90,300],"art":{"k":"exit"},"arrow":"r","exit":{"to":"c6_archivio","if":"flag.helene_euridice","else":{"beps":["Un passaggio coperto pieno di librerie chiuse. Senza sapere quale porta, è inutile."],"kiki":["Prima Hélène."]}}},{"id":"verso_ufficio","name":"Île de la Cité (studio notarile)","rect":[860,990,200,70],"art":{"k":"exit"},"arrow":"d","exit":{"to":"c6_ufficio","if":"puzzle.c6_cronologia && flag.nastro_ascoltato","else":{"beps":["Varano ci aspetta. Ma prima voglio sapere tutto quello che lui sa. Archivio e nastro."],"kiki":["Non andiamo da lui a mani vuote. Prima il nastro e l'archivio."]}}}]},"c6_atelier":{"name":"Studio Marchetti (notte)","place":"Rue des Archives · Parigi","chapter":6,"music":"mystery","ambience":"room","art":{"type":"interior","time":"night","wall":"#9a8a6a","floor":"#4a3624","horizon":650,"light":[{"x":760,"y":520,"r":500,"c":"#ffcf88","a":0.45}],"layers":[{"k":"poster","x":120,"y":160,"w":150,"h":200,"c":"#d8c8a8"},{"k":"easel","x":1640,"y":420,"w":180,"h":340},{"k":"lamp","x":740,"y":420,"w":80,"h":280}]},"walk":[[80,1060],[1860,1060],[1780,710],[160,710]],"scale":[710,0.72,1060,1],"spawn":{"default":[300,900,"r"],"from_c6_pont_neuf":[180,920,"r"],"from_c6_sala":[1000,820]},"npcs":[{"id":"helene6","char":"helene","x":1260,"y":860,"dir":"l","talk":"helene_c6","look":{"beps":"Hélène, in piedi accanto al banco luminoso. Ha in mano un cappello nero.","kiki":"Hélène. Con un cappello nero in mano. Oh."}}],"firstEnter":["@dialogue:helene_c6"],"hotspots":[{"id":"banco","name":"Banco luminoso","rect":[560,600,420,160],"art":{"k":"table","c":"#e8e4d8"},"look":{"beps":"Il banco su cui abbiamo sovrapposto le foto. Sembra passato un anno. Sono passati due mesi.","kiki":"Il banco dove abbiamo visto nonna e la bisnonna nello stesso punto."}},{"id":"foto_2019","name":"Fotografia recente","rect":[460,160,110,150],"art":{"k":"frame","c":"#c8c0a8"},"col":"photo_11"},{"id":"gatto","name":"Daguerre","rect":[1180,640,120,80],"art":{"k":"figure","c":"#e8a050"},"look":{"beps":"Daguerre. Mi riconosce. Mi odia con la stessa costanza dell'altra volta. È rassicurante.","kiki":"Daguerre dorme sul trench di Hélène. È il suo modo di dire che le vuole bene."}},{"id":"tenda","name":"Sala di proiezione","rect":[1660,260,180,470],"art":{"k":"curtain","c":"#2a1a1a"},"at":[1720,860],"exit":{"to":"c6_sala","if":"flag.helene_euridice","else":"Prima ascoltiamo Hélène."}},{"id":"finestra","name":"Finestra","rect":[1240,120,300,280],"art":{"k":"window","time":"night"},"look":{"beps":"Neve sul tiglio del cortile. La bicicletta senza ruota è ancora lì. Parigi è coerente.","kiki":"Nevica. Nonna adorava la neve a Parigi: diceva che rende tutti onesti, perché si vedono le impronte."}},{"id":"uscita","name":"Esci","rect":[0,620,80,440],"art":{"k":"exit"},"exit":{"to":"c6_pont_neuf"},"arrow":"l"}]},"c6_sala":{"name":"Sala di proiezione","place":"Sotto lo Studio Marchetti","chapter":6,"music":"mystery","ambience":"room","fx":[{"k":"light","x":300,"y":300,"w":1300,"h":200}],"art":{"type":"interior","time":"night","wall":"#2a1a1a","floor":"#1a1010","horizon":640,"wainscot":false,"dark":0.5,"light":[{"x":960,"y":300,"r":600,"c":"#e8e8ff","a":0.25}],"layers":[{"k":"frame","x":520,"y":100,"w":880,"h":420,"c":"#e8e8e0"},{"k":"sofa","x":560,"y":760,"w":380,"h":180,"c":"#5a1a1a"},{"k":"sofa","x":1000,"y":760,"w":380,"h":180,"c":"#5a1a1a"}]},"walk":[[80,1060],[1860,1060],[1780,700],[160,700]],"scale":[700,0.72,1060,1],"spawn":{"default":[300,920,"r"],"from_c6_atelier":[200,920,"r"]},"hotspots":[{"id":"revox","name":"Registratore a bobine","rect":[160,560,220,180],"art":{"k":"machine","c":"#8a8a8e"},"at":[300,880],"look":{"beps":"Un Revox A77. Due bobine, VU-meter con le lancette. Bellissimo come un'auto d'epoca.","kiki":"Il Revox di Jacques. Hélène lo ha fatto revisionare la settimana scorsa. Sapeva che saremmo venuti."},"use":[{"if":"flag.nastro_ascoltato","do":["Il nastro l'abbiamo ascoltato. Non ho bisogno di risentire quella votazione."]},{"do":["Mi serve una bobina da metterci sopra."]}],"items":{"nastro":[{"if":"flag.nastro_ascoltato","do":["Già ascoltato."]},{"do":["@dialogue:nastro"]}]}},{"id":"schermo","name":"Schermo","rect":[520,100,880,420],"look":{"beps":"Uno schermo bianco. Un rettangolo di niente pronto a diventare qualcosa.","kiki":"Jacques proiettava qui i suoi film di famiglia. Nonna è in metà di quei film."}},{"id":"bobine","name":"Bobine di film","rect":[1500,600,160,140],"art":{"k":"film","overlay":true},"col":"rec_06"},{"id":"proiettore","name":"Proiettore","rect":[1400,360,240,200],"art":{"k":"projector"},"look":{"beps":"Un proiettore 16 millimetri. Fa un rumore da macchina da cucire quando gira.","kiki":"Hélène dice che una volta ha proiettato «Orfeo» di Cocteau per nonna. Nonna ha pianto tutto il tempo e poi ha detto: «Ha sbagliato tutto»."}},{"id":"poltrone","name":"Poltrone","rect":[560,760,820,180],"look":{"beps":"Poltrone di velluto rosso consumato. Quella di sinistra ha la forma di qualcuno che la usava ogni sera.","kiki":"La poltrona di nonna. Quella di sinistra."}},{"id":"uscita","name":"Torna su","rect":[0,620,80,440],"art":{"k":"exit"},"exit":{"to":"c6_atelier"},"arrow":"l"}]},"c6_archivio":{"name":"Archivio di Orfeo — Parigi","place":"Sotto il Passage des Libraires","chapter":6,"music":"mystery","ambience":"underground","fx":["dust"],"art":{"type":"underground","time":"night","wall":"#5a4a3a","floor":"#2a2018","horizon":650,"light":[{"x":960,"y":460,"r":600,"c":"#ffcf88","a":0.45}],"layers":[{"k":"shelves","x":60,"y":120,"w":520,"h":540,"c":"#3a2a1a","paper":true,"seed":"p1"},{"k":"shelves","x":1340,"y":120,"w":520,"h":540,"c":"#3a2a1a","paper":true,"seed":"p2"},{"k":"candle","x":940,"y":520,"w":40,"h":80}]},"walk":[[100,1060],[1820,1060],[1720,720],[200,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c6_pont_neuf":[260,920,"r"]},"firstEnter":["kiki: L'Archivio di Orfeo. Quello vero. Nonna veniva qui ogni 12 marzo.","beps: Il giorno della votazione del '67.","@objective:o6_cronologia"],"hotspots":[{"id":"tavolo","name":"Tavolo dei documenti","rect":[620,600,680,180],"art":{"k":"desk","c":"#4a3020"},"at":[960,880],"look":{"beps":"Un tavolo lungo, coperto di documenti in ordine sparso. Lettere, verbali, rapporti. Ottant'anni di Orfeo in disordine.","kiki":"Sono stati sparpagliati apposta. Qualcuno voleva che li rimettessimo in ordine. O che non ci riuscissimo."},"use":[{"if":"puzzle.c6_cronologia","do":["Cronologia ricostruita. Due falsi smascherati. Il tavolo ha detto tutto."]},{"do":["@puzzle:c6_cronologia"]}]},{"id":"atto","name":"Atto di cancellazione","rect":[1440,640,80,50],"art":{"k":"papers","overlay":true},"col":"doc_16"},{"id":"scaffali","name":"Scaffali","rect":[60,120,520,300],"look":{"beps":"Faldoni con etichette a mano: «Passaggi 1944», «Alluvione 1966», «Parigi 1967», «Istanbul 1989». E uno vuoto: «XVII».","kiki":"Il faldone del XVII è vuoto. Come il suo cassetto, come la sua riga nella lista."}},{"id":"busto","name":"Busto di Orfeo","rect":[1360,300,160,260],"art":{"k":"statue","c":"#d8d0c0"},"look":{"beps":"Un busto di Orfeo con la lira. Qualcuno gli ha messo una sciarpa. Fa freddo, qui sotto.","kiki":"La sciarpa è di nonna. La riconosco. Gliel'ha lasciata lei."}},{"id":"candele","name":"Candele","rect":[920,500,80,120],"look":{"beps":"Candele accese. Qualcuno è passato poco fa. O le candele qui non si spengono mai.","kiki":"Hélène. Le ha accese per noi."}},{"id":"uscita","name":"Risali","rect":[0,620,80,440],"art":{"k":"exit"},"exit":{"to":"c6_pont_neuf"},"arrow":"l"}]},"c6_ufficio":{"name":"Studio del Notaio","place":"Île de la Cité · Parigi","chapter":6,"music":"tension","ambience":"room","art":{"type":"interior","time":"night","wall":"#3a3a40","floor":"#2a2420","horizon":650,"wallpaper":true,"light":[{"x":1000,"y":520,"r":480,"c":"#ffd8a0","a":0.45}],"layers":[{"k":"shelves","x":60,"y":100,"w":480,"h":560,"c":"#2a2018","seed":"law"},{"k":"rug","x":600,"y":860,"w":800,"h":150,"c":"#2a3a5a"}]},"walk":[[80,1060],[1860,1060],[1780,720],[160,720]],"scale":[720,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c6_pont_neuf":[200,920,"r"]},"npcs":[{"id":"varano6","char":"varano","x":1300,"y":860,"dir":"l","talk":"varano_c6","look":{"beps":"Varano. Capelli brizzolati, barba grigia e l'aria di uno che non dorme da anni.","kiki":"Senza cappello sembra più vecchio. E più stanco."}}],"firstEnter":["varano: Giuseppe. Signorina Morel. Accomodatevi. Vi aspettavo da Firenze.","varano: Prendetevi un momento. Guardatevi intorno. Poi parliamo.","@objective:o6_parla_varano"],"hotspots":[{"id":"scrivania","name":"Scrivania","rect":[900,580,420,200],"art":{"k":"desk","c":"#2a1a10"},"look":{"beps":"Una scrivania impero, sgombra. Solo un tampone, una penna stilografica e una scatola di fiammiferi.","kiki":"Fiammiferi. Su una scrivania senza posacenere."}},{"id":"lettera_lina","name":"Lettera sulla scrivania","rect":[1000,560,70,40],"art":{"k":"letter","overlay":true},"col":"doc_17"},{"id":"ritratto","name":"Ritratto","rect":[1500,160,180,240],"art":{"k":"painting","c":"#3a3a3a","seed":"ettore"},"look":{"beps":"Un uomo con gli stessi occhi di Varano, più duri. «Ettore Varano, notaio, 1919–1999».","kiki":"Il padre. Quello che ha falsificato il verbale. Lo guarda ogni giorno, da qui."}},{"id":"cassaforte","name":"Cassaforte","rect":[1700,500,160,220],"art":{"k":"safe"},"look":{"beps":"Una cassaforte a muro, aperta. Vuota. Quello che c'era, Varano lo porta addosso.","kiki":"Aperta. Vuole che lo sappiamo."}},{"id":"fiammiferi","name":"Fiammiferi","rect":[1240,590,50,30],"art":{"k":"crate","c":"#a82a20","overlay":true},"look":{"beps":"Fiammiferi svedesi. Una scatola nuova. Ne manca uno.","kiki":"Ne manca uno. Ci ha già provato?"}},{"id":"finestra","name":"Finestra su Notre-Dame","rect":[620,100,300,300],"art":{"k":"window","time":"night"},"look":{"beps":"Notre-Dame sotto la neve, a duecento metri. Varano guarda una cattedrale bruciata e ricostruita tutti i giorni.","kiki":"Ha visto bruciare Notre-Dame da questa finestra. Chissà cosa ha pensato."}},{"id":"uscita","name":"Esci (verso le catacombe)","rect":[0,620,80,440],"art":{"k":"exit"},"exit":{"to":"c6_catacombe","if":"flag.varano_c6_fine","else":["Non ce ne andiamo senza aver parlato con lui."]},"arrow":"l"}]},"c6_catacombe":{"name":"Catacombe","place":"Sotto Parigi","chapter":6,"music":"tension","ambience":"underground","fx":["dust","fog"],"art":{"type":"underground","time":"night","wall":"#6a6050","floor":"#2a2620","horizon":660,"dark":0.7,"light":[{"x":760,"y":460,"r":460,"c":"#ffd890","a":0.4}]},"walk":[[100,1060],[1820,1060],[1700,740],[220,740]],"scale":[740,0.74,1060,1],"spawn":{"default":[300,920,"r"],"from_c6_pont_neuf":[260,920,"r"]},"firstEnter":["kiki: Varano ha detto che il treno per Firenze si prende meglio da qui. Le catacombe portano fino a Denfert. E nessuno ci segue, qui sotto.","beps: Non ho mai capito il concetto di «meglio» applicato a un ossario."],"hotspots":[{"id":"ossa","name":"Muro di ossa","rect":[200,200,1500,440],"look":{"beps":"Ossa disposte in disegni geometrici: croci, cuori, cerchi. Sei milioni di parigini. L'ordine più inquietante che abbia mai visto.","kiki":"Li hanno spostati qui nel Settecento, dai cimiteri del centro. Senza nomi. Nessun registro."}},{"id":"iscrizione","name":"Iscrizione","rect":[760,120,400,90],"art":{"k":"sign","label":"ARRÊTE ! C'EST ICI…","c":"#2a2620"},"look":{"beps":"«Arrête! C'est ici l'empire de la Mort.» Fermati, qui è l'impero della Morte. Grazie, molto accogliente.","kiki":"Orfeo era sceso negli inferi. Noi ci passiamo per prendere un treno."}},{"id":"lira_ossa","name":"Una lira tra le ossa","rect":[1500,420,60,60],"art":{"k":"symbol","c":"#e8e0c8","a":0.45},"col":"sym_6"},{"id":"candela","name":"Candela","rect":[720,520,60,100],"art":{"k":"candle"},"look":{"beps":"Qualcuno ha lasciato una candela accesa. Speriamo sia stato qualcuno vivo.","kiki":"Una candela e una moneta da 500 lire. La Testimone è passata di qui."}},{"id":"uscita","name":"Verso Denfert e la stazione","rect":[1830,640,90,420],"art":{"k":"exit"},"arrow":"r","exit":{"to":"c6_catacombe","if":"false","else":["@dialogue:c6_fine"]}}]},"c7_cantiere":{"name":"La stanza murata","place":"Via de' Bardi · Firenze · notte","chapter":7,"music":"finale","ambience":"underground","fx":["dust",{"k":"light","x":980,"y":120,"w":420,"h":900}],"art":{"type":"underground","time":"night","wall":"#4a3a2e","floor":"#2a221c","horizon":690,"dark":0.6,"light":[{"x":1090,"y":260,"r":520,"c":"#ffe0a0","a":0.45}],"layers":[{"k":"brickwall","x":1180,"y":200,"w":420,"h":490,"hole":true},{"k":"safe","x":330,"y":290,"w":230,"h":400,"c":"#4a5058"},{"k":"desk","x":620,"y":580,"w":380,"h":160,"c":"#4a3a2a","items":false}]},"walk":[[60,1060],[1880,1060],[1860,760],[340,740],[60,800]],"scale":[740,0.74,1060,1],"spawn":{"default":[1600,920,"l"]},"firstEnter":["kiki: Eccoci. Dove è cominciato tutto.","beps: Il computer non c'è più. L'armadio è vuoto. Ma l'acqua…","narr: Plic. Plic. Sotto il pavimento.","beps[think]: Sandro aveva ragione. Si sente l'acqua.","@objective:o7_scendi"],"hotspots":[{"id":"gradini","name":"Gradini","rect":[60,700,260,260],"art":{"k":"stairs","down":true,"c":"#5a4a3a"},"at":[300,900],"look":{"beps":"Tre gradini. Il terzo, quello più chiaro. «L'acqua arrivò al terzo gradino». Non si fermò lì: ci entrò.","kiki":"Il terzo gradino è diverso. Più chiaro. E sembra… vuoto, sotto."},"use":[{"if":"flag.lastra_aperta","do":["@goto:c7_galleria"]},{"if":"!flag.gradino_vuoto","do":[{"if":"active=='beps'","do":["@anim:use","Busso sul terzo gradino. Suono vuoto. Sotto c'è una cavità.","beps[think]: È una lastra appoggiata, non murata. Pesa un quintale, a occhio. Da soli non si alza.","@flag:gradino_vuoto","@objective:o7_lastra"],"else":["kiki: Busso… sembra vuoto. Beps, tu che sei curioso di tutto: ascolta qui."]}]},{"do":[{"if":"present.beps && present.kiki","do":["beps: Insieme. Al tre.","kiki: Uno… due… tre!","@anim:use","@sfx:door","narr: La lastra si solleva, scivola, cade di lato. Sotto: una scala di pietra che scende nel buio, verso il rumore dell'acqua.","@flag:lastra_aperta","@inc:coop","@objective:o7_galleria"],"else":["Da solo non la sollevo."]}]}]},{"id":"armadio","name":"Armadio vuoto","rect":[330,290,230,400],"look":{"beps":"L'armadio dove ho trovato i frammenti. Due mesi fa. Due vite fa.","kiki":"Qui dentro c'era il promemoria di nonna. «Murate la stanza.» E noi l'abbiamo smurata."}},{"id":"tavolo","name":"Tavolo","rect":[620,580,380,160],"look":{"beps":"La polvere ha di nuovo coperto il rettangolo del computer. La polvere ha pazienza.","kiki":"Nonna ci ha lavorato, a questo tavolo. Nel 1998. Ho trovato la sua tazza: «I ♥ Firenze». Che vergogna, nonna."}},{"id":"breccia","name":"Breccia","rect":[1260,260,280,360],"look":{"beps":"La breccia che ha aperto Sandro. Dall'altra parte, il cantiere e il ponteggio della ditta. Il mondo normale.","kiki":"Il mondo normale. Sembra così lontano."}},{"id":"uscita","name":"Esci","rect":[1840,700,80,360],"art":{"k":"exit"},"arrow":"r","exit":{"to":"c7_cantiere","if":"false","else":{"beps":["Non adesso. Non dopo tutta questa strada."],"kiki":["Non si torna indietro, Beps. È l'unica regola."]}}}]},"c7_galleria":{"name":"Galleria sotto l'Arno","place":"Fondamenta di Firenze","chapter":7,"music":"finale","ambience":"water","fx":["fog","dust"],"art":{"type":"underground","time":"night","wall":"#4a4438","floor":"#1a2420","horizon":660,"dark":0.55,"light":[{"x":760,"y":360,"r":520,"c":"#ffd890","a":0.4}],"layers":[{"k":"water","x":0,"y":700,"w":1920,"h":110,"c":"#1a3030"},{"k":"arch","x":1280,"y":220,"w":400,"h":480,"c":"#5a5040","inner":"#0a0806"}]},"walk":[[100,1060],[1820,1060],[1700,800],[220,800]],"walkIf":[{"if":"!flag.paratoia_aperta","walk":[[100,1060],[1100,1060],[1060,800],[220,800]]}],"scale":[790,0.78,1060,1],"spawn":{"default":[300,940,"r"],"from_c7_cantiere":[300,940,"r"],"from_c7_camera":[1600,920,"l"]},"firstEnter":["kiki: Una galleria. Mattoni romani, poi medievali, poi rinascimentali. Stratificata come una torta.","beps: Un canale d'acqua ci taglia la strada. È profondo. E c'è una paratoia, con una ruota.","@objective:o7_paratoia"],"hotspots":[{"id":"ruota","name":"Ruota della paratoia","rect":[820,500,180,200],"art":{"k":"rings"},"at":[900,880],"only":"beps","onlyMsg":{"kiki":["La ruota non si muove di un millimetro. Beps, servono le tue braccia da cantiere."]},"look":{"beps":"Una ruota di ferro che alza la paratoia. Ruggine di secoli, ma l'asse è sano. Si può fare.","kiki":"Una ruota pesante. Troppo per me."},"use":[{"if":"flag.paratoia_aperta","do":["L'acqua è scesa. La paratoia resta su: ci ho messo un cuneo."]},{"do":["@anim:use","@sfx:mechanism","beps[determined]: Forza… forza… FORZA.","narr: La ruota cede di colpo. La paratoia si alza, l'acqua del canale defluisce con un rumore di risacca.","beps: Infilo un cuneo. Così resta su.",{"if":"present.kiki","do":["kiki[smile]: Il mio eroe. Coi calli.","@stat:legame+1"]},"@flag:paratoia_aperta","@refresh","@objective:o7_camera"]}]},{"id":"canale","name":"Canale","rect":[0,700,1920,110],"look":{"beps":[{"if":"flag.paratoia_aperta","do":["Il canale si è svuotato. Sul fondo, monete. Centinaia di monete. Lire, franchi, piastre."]},{"do":["Acqua nera, veloce. Un canale di scolo dell'Arno, forse medievale. Non ci si passa."]}],"kiki":[{"if":"flag.paratoia_aperta","do":["Monete sul fondo. Lire, franchi, piastre turche. Ogni custode ne ha lasciata una."]},{"do":["Troppo profondo. E troppo freddo."]}]}},{"id":"nicchia_voce","name":"Nicchia con registratore","rect":[1460,560,70,50],"art":{"k":"recorder","overlay":true},"if":"flag.paratoia_aperta","col":"rec_07"},{"id":"lira_volta","name":"Lira sulla volta","rect":[560,140,70,70],"art":{"k":"symbol","c":"#d8c8a0","a":0.45},"col":"sym_7"},{"id":"iscrizione","name":"Iscrizione","rect":[240,300,320,120],"art":{"k":"sign","label":"NON VOLTARTI","c":"#3a3428"},"look":{"beps":"«Non voltarti.» Incisa nella pietra, con la data: 1944. Qualcuno è passato di qui con paura e ha voluto lasciarlo scritto.","kiki":"«Non voltarti.» La regola di Orfeo. La regola di nonna."}},{"id":"arco","name":"Arco verso la Camera","rect":[1280,220,400,480],"if":"flag.paratoia_aperta","at":[1480,880],"exit":{"to":"c7_camera"}},{"id":"uscita","name":"Risali","rect":[100,600,100,300],"art":{"k":"stairs","c":"#4a4438"},"at":[260,900],"exit":{"to":"c7_cantiere"}}]},"c7_camera":{"name":"La Camera di Orfeo","place":"Sotto Firenze","chapter":7,"music":"finale","ambience":"underground","fx":["dust",{"k":"light","x":760,"y":0,"w":400,"h":1000},{"k":"embers","if":"flag.meccanismo_aperto"}],"art":{"type":"underground","time":"night","wall":"#5a4a34","floor":"#2a2016","horizon":660,"light":[{"x":960,"y":360,"r":640,"c":"#ffd890","a":0.5}],"layers":[{"k":"water","x":860,"y":660,"w":200,"h":420,"c":"#0a1418"},{"k":"machine","x":700,"y":160,"w":520,"h":360,"c":"#6a5030"}]},"walk":[[60,1060],[1860,1060],[1800,720],[120,720]],"walkFor":{"beps":[[60,1060],[840,1060],[840,720],[120,720]],"kiki":[[1080,1060],[1860,1060],[1800,720],[1080,720]]},"walkIf":[{"if":"flag.meccanismo_aperto","walk":[[60,1060],[1860,1060],[1800,720],[120,720]]}],"follow":false,"scale":[720,0.74,1060,1],"spawn":{"default":[500,920,"r"],"from_c7_galleria":[400,920,"r"]},"firstEnter":["narr: Una sala circolare scavata sotto il fiume. Al centro, un abisso d'acqua nera divide il pavimento in due piattaforme. Sopra, un meccanismo enorme di bronzo e legno, con un incavo, una serratura, una ruota di nomi, un grammofono.","kiki[surprised]: C'è una trave, per passare dall'altra parte. Sottile.","beps: Regge una persona sola. Lo vedo da qui.","kiki: Allora vado io. Tu resti di qua.","@together:false","@place:kiki=c7_camera@1400,900,l","narr: Kiki attraversa la trave. Arrivata dall'altra parte, la trave scricchiola e si spezza, cadendo nell'acqua.","kiki[worried]: Bene. Adesso siamo divisi.","beps: Come aveva detto Varano. «Si apre solo in due.»","@objective:o7_meccanismo"],"hotspots":[{"id":"iscrizione","name":"Iscrizione del meccanismo","rect":[740,60,440,90],"art":{"k":"sign","label":"IL SIGILLO APRE…","c":"#3a2a18"},"look":["«Il Sigillo apre. La Voce chiama. I Nomi rispondono. La Chiave chiude — ma solo se nessuno resta solo.»","@clue:iscrizione_camera"]},{"id":"incavo","name":"Incavo del Sigillo","rect":[560,360,120,120],"art":{"k":"symbol","c":"#c9a85a","a":0.6},"at":[600,880],"only":"beps","onlyMsg":{"kiki":["L'incavo del Sigillo è dalla parte di Beps."]},"look":{"beps":"Un incavo rotondo con una lira. Il posto del Sigillo.","kiki":"Dall'altra parte, vicino a Beps: l'incavo del Sigillo."},"use":[{"if":"flag.m_sigillo","do":["Il Sigillo è al suo posto. Brilla appena."]},{"do":["Ci vuole il Sigillo."]}],"items":{"sigillo":[{"if":"flag.m_sigillo","do":["Già inserito."]},{"do":["@anim:use","@sfx:mechanism","beps: Il Sigillo apre.","narr: Il Sigillo entra nell'incavo. Un primo ingranaggio si muove, lento come un respiro.","@flag:m_sigillo","@take:sigillo"]}]}},{"id":"serratura","name":"Serratura","rect":[380,420,90,110],"art":{"k":"safe","c":"#6a5a3a"},"at":[440,880],"only":"beps","onlyMsg":{"kiki":["La serratura è dalla parte di Beps."]},"look":{"beps":"Una serratura con un 17 inciso. La chiave d'ottone.","kiki":"La serratura col 17. Ce l'ha Beps, la chiave."},"use":["Serve la chiave d'ottone."],"items":{"chiave_ottone":[{"if":"flag.meccanismo_aperto","do":["Già girata."]},{"if":"!flag.m_registro","do":["@sfx:fail","@inc:final_errors","La chiave non gira. «La Chiave chiude»: è l'ultimo passo. Prima vengono gli altri."]},{"if":"!flag.kiki_tiene","do":["@sfx:fail","@inc:final_errors","La chiave gira a vuoto. «…ma solo se nessuno resta solo.»","beps[think]: Dall'altra parte c'è una leva. Kiki deve tenerla mentre io giro."]},{"do":["@dialogue:apertura"]}]}},{"id":"grammofono","name":"Grammofono","rect":[1320,420,180,220],"art":{"k":"phonograph"},"at":[1380,880],"only":"kiki","onlyMsg":{"beps":["Il grammofono è dalla parte di Kiki. Il nastro lo può usare lei: passa a Kiki."]},"look":{"beps":"Un grammofono con un adattatore per bobine. Chi l'ha costruito pensava a tutto.","kiki":"Un lettore per bobine dentro un grammofono. Ci va il nastro. «La Voce chiama.»"},"use":["Serve il nastro."],"items":{"nastro":[{"if":"flag.m_voce","do":["La voce ha già chiamato."]},{"if":"!flag.m_sigillo","do":["@sfx:fail","@inc:final_errors","kiki: Il nastro non gira. «Il Sigillo apre»: prima Beps."]},{"do":["@anim:use","@sfx:tape","kiki: La Voce chiama.","narr: Dal grammofono esce la voce di Ada, del 1967: «Contraria. Euridice vota contro.» Il meccanismo risponde con un secondo scatto.","@flag:m_voce"]}]}},{"id":"ruota_nomi","name":"Ruota dei Nomi","rect":[1560,300,220,220],"art":{"k":"rings"},"at":[1620,880],"only":"kiki","onlyMsg":{"beps":["La ruota dei nomi è dall'altra parte. Tocca a Kiki."]},"look":{"beps":"Una ruota con diciassette spazi, dall'altra parte. Kiki ci arriva.","kiki":"La Ruota dei Nomi. Sedici emblemi. Il diciassettesimo, raschiato."},"use":[{"if":"flag.m_registro","do":["I Nomi hanno risposto."]},{"if":"!flag.m_voce","do":["@sfx:fail","@inc:final_errors","kiki: Bloccata. «I Nomi rispondono»… dopo che la Voce ha chiamato."]},{"do":["@puzzle:c7_registro"]}]},{"id":"leva","name":"Leva","rect":[1180,500,100,200],"art":{"k":"lever","down":false},"at":[1220,880],"only":"kiki","onlyMsg":{"beps":["La leva è dalla parte di Kiki."]},"look":{"beps":"Una leva dall'altra parte. Collegata alla serratura con una catena che attraversa l'abisso.","kiki":"Una leva legata alla serratura di Beps. Va tenuta mentre lui gira la chiave."},"use":[{"if":"flag.meccanismo_aperto","do":["Il meccanismo è aperto. Posso lasciarla."]},{"if":"flag.kiki_tiene","do":["kiki: La sto tenendo! Beps, la chiave! (Passa a Beps.)"]},{"if":"!flag.m_registro","do":["@sfx:fail","@inc:final_errors","kiki: La tiro, ma non succede niente. Prima i Nomi."]},{"do":["@anim:use","@sfx:mechanism","kiki[determined]: La tengo. Nessuno resta solo, Beps. Gira quella chiave.","@flag:kiki_tiene","@objective:o7_chiave"]}]},{"id":"abisso","name":"Abisso d'acqua","rect":[860,660,200,400],"look":{"beps":"Acqua nera, profonda. L'Arno sotto l'Arno. Kiki è dall'altra parte, a tre metri. Sembrano tre chilometri.","kiki":"Non guardarlo. Guarda me."}},{"id":"foto_originale","name":"Fotografia incorniciata","rect":[200,200,120,150],"art":{"k":"frame","c":"#c8b898"},"col":"photo_12"},{"id":"registro_scrigno","name":"Scrigno del Registro","rect":[880,420,160,120],"art":{"k":"trunk","c":"#5a3a22"},"if":"flag.meccanismo_aperto && !item.registro","at":[960,900],"look":"Lo scrigno del Registro, aperto. Dentro, un volume rilegato in pelle, spesso come un mattone.","use":["@anim:pickup","@give:registro","@dialogue:varano_arriva"]},{"id":"uscita","name":"Torna alla galleria","rect":[60,640,80,420],"art":{"k":"exit"},"arrow":"l","exit":{"to":"c7_galleria","if":"flag.meccanismo_aperto && item.registro","else":{"beps":["Non me ne vado senza Kiki."],"kiki":["Io da qui non esco, senza Beps."]}}}]},"c7_alba":{"bg":"assets/backgrounds/bg_lungarno_notte_01.jpg","bgFilter":"brightness(1.1) saturate(1.1) sepia(0.2)","bgTint":"linear-gradient(180deg, rgba(255,120,100,.55) 0%, rgba(255,160,110,.4) 35%, rgba(255,190,140,.12) 60%, transparent 80%)","name":"Lungarno all'alba","place":"Firenze","chapter":7,"music":"finale","ambience":"water","art":{"type":"exterior","time":"dawn","horizon":600,"ground":"#5a5048","skyline":200,"sun":[1600,520],"layers":[{"k":"river","x":0,"y":560,"w":620,"h":160,"c":"#6a7a8a"},{"k":"bridge","x":40,"y":470,"w":540,"h":150,"shops":true},{"k":"building","x":620,"y":160,"w":520,"h":660,"c":"#b8946a","seed":"a"},{"k":"building","x":1140,"y":120,"w":780,"h":700,"c":"#c8a478","seed":"b"},{"k":"railing","x":0,"y":690,"w":620,"h":70}]},"walk":[[120,1080],[1920,1080],[1920,900],[1600,780],[1300,665],[1100,645],[1000,655],[790,770]],"scale":[650,0.42,1080,0.95],"spawn":{"default":[640,990,"r"]},"npcs":[{"id":"varano7","char":"varano","x":900,"y":775,"dir":"l","talk":"varano_finale","look":{"beps":"Varano, all'alba, sotto il lampione spento. Una scatola di fiammiferi in mano.","kiki":"Ha l'aria di non aver dormito da quarant'anni. Forse da stanotte potrà."}}],"firstEnter":["narr: Il sole sorge dietro San Miniato. Il Lungarno è vuoto, lavato dalla notte.","kiki: Il Registro. Ce l'abbiamo.","beps: E adesso dobbiamo decidere cosa farne.","@objective:o7_decidi"],"hotspots":[{"id":"panchina","name":"Panchina","rect":[400,880,280,110],"art":{"k":"bench"},"at":[560,1010],"look":{"beps":"La panchina bagnata della prima sera. Adesso è asciutta. Ci starebbero due persone.","kiki":"La panchina. «Tienila a mente: qui si vedono bene i tramonti.» Si vedono bene anche le albe."}},{"id":"ponte","name":"Ponte Vecchio","rect":[500,490,540,80],"look":{"beps":"Il ponte che non cadde. Sopra, sulla spalletta, c'è una figura in nero. Col cappello.","kiki":"Lassù. Sul ponte. La donna col cappello. Hélène è a Parigi."}},{"id":"donna_ponte","name":"Figura sul ponte","rect":[700,455,30,70],"art":{"k":"figure","hat":true,"c":"#0a0a0c","overlay":true},"look":{"beps":"Ci guarda. Alza una mano. Un saluto? Poi si volta e se ne va.","kiki":"Si è voltata. Euridice non dovrebbe voltarsi. O forse è proprio questo il punto."},"use":["È troppo lontana. E forse è giusto così.","@flag:donna_alba","@clue:donna_alba"]},{"id":"targa","name":"Targa dell'alluvione","rect":[1612,420,70,90],"art":{"k":"sign","label":"4·XI·66","c":"#3a3430"},"look":{"beps":"La targa del '66. La chiave di tutto. Il giorno in cui l'acqua arrivò al terzo gradino.","kiki":"La prima cosa che hai letto, in questa storia. Era la chiave. Era sempre stata qui."}},{"id":"caffe","name":"Caffè delle Logge","rect":[1530,320,90,390],"art":{"k":"door","label":"CAFFÈ","c":"#4a1f1a"},"look":{"beps":"Chiuso. Apre alle sette. Tommaso arriverà, aprirà, asciugherà lo stesso bicchiere.","kiki":"Dopo. Prima decidiamo. Poi cappuccino. Con la cannella."}}]}}},"dialogues":{"_doc":"Dialoghi a temi. first/intro = script iniziale; topics = temi (if, once, optional, special, end); items = reazioni agli oggetti mostrati; linear = sequenza senza menu.","dialogues":{"sandro":{"npc":"sandro","intro":[{"if":"flag.sandro_ok","do":["sandro: Beps. Io resto qui sulla porta, eh."]},{"do":["sandro: Allora, Beps? Il caffè?"]}],"topics":[{"id":"caffe_dato","label":"Ecco il caffè","icon":"item","if":"item.caffe && !flag.sandro_caffe","once":true,"do":["@take:caffe","@flag:sandro_caffe","@flag:sandro_ok","sandro[smile]: Ah. Vita. Sei un sant'uomo, Beps.","sandro: Va bene, il telo lo tolgo. Ma io resto qui sulla porta. Se sento l'acqua, scappo.","@objective:o1_stanza"]},{"id":"caffe_dimenticato","label":"Il caffè… me ne sono dimenticato","icon":"question","if":"!item.caffe && !flag.sandro_caffe","once":true,"do":["sandro[skeptical]: Allora niente stanza. Regola del cantiere: senza caffè non si apre niente.","beps: Questa regola dove sta scritta?","sandro: Nel mio cuore, Beps. La macchinetta dell'ufficio funziona, no?","@objective:o1_caffe_sandro"]},{"id":"stanza","label":"Com'era la stanza quando l'hai aperta?","icon":"eye","do":["sandro[worried]: Asciutta. Troppo asciutta per un posto murato da sessant'anni.","sandro: E pulita. Come se qualcuno ci fosse stato poco fa. Un computer sul tavolo, una sedia, un armadio col lucchetto.","beps: Sessant'anni e un computer del '98.","sandro: Appunto. Io non ci dormo, la notte."]},{"id":"chi_murato","label":"Chi ha murato la stanza?","icon":"person","once":true,"do":["sandro: Il vecchio proprietario dice che nel '98 una signora francese pagò una ditta per «risistemare la cantina». In contanti.","sandro: Io dico che ha murato qualcosa. O qualcuno.","beps: Una signora francese.","sandro: Con un cappello così. L'ha detto il proprietario. Chi se lo ricorda un cappello dopo trent'anni? Uno che l'ha guardato bene.","@clue:signora_francese","@stat:conoscenza+1"]},{"id":"acqua","label":"Davvero si sente l'acqua?","icon":"question","optional":true,"do":["sandro[scared]: Di notte. Un gocciolio, sotto il pavimento. Plic. Plic.","beps: Sotto il pavimento c'è la terra, Sandro.","sandro: Appunto, Beps. Appunto.","@flag:sandro_acqua"]}],"items":{"caffe":[{"if":"!flag.sandro_caffe","do":["@take:caffe","@flag:sandro_caffe","@flag:sandro_ok","sandro[smile]: Ah. Vita. Sei un sant'uomo, Beps.","sandro: Va bene, il telo lo tolgo. Ma io resto qui sulla porta.","@objective:o1_stanza"]}],"foto1944":["sandro: Mai visti. Però quella col cappello… mia nonna aveva un cappello così.","sandro: Tutte le nonne avevano un cappello così. È una cosa delle nonne."],"medaglione_b":["sandro[worried]: Era nella crepa? L'avevo vista luccicare e ho fatto finta di niente. Io la roba dei morti non la tocco."],"frammenti":["sandro: Carta bagnata. Mia moglie con la carta bagnata ci fa le palline per il camino. Lei che ci fa?"],"*":["sandro: Beps, io sono un capocantiere, non un antiquario."]}},"archivista":{"npc":"archivista","first":["@flag:met_archivista","@person:archivista","archivista: Buonasera, giovanotto. Chiudiamo tra venti minuti. Mi dica che ha bisogno di una cosa sola."],"intro":["archivista: Ancora lei. Mi dica."],"topics":[{"id":"catalogo","label":"Il catalogo O","icon":"doc","if":"!flag.catalogo_ok","do":["archivista[skeptical]: Non esiste un catalogo O.","archivista: Esiste un cassetto O, che contiene schede di nessuna importanza ed è chiuso perché la chiave l'ho persa nel 1994.","beps: Persa.","archivista: Persa, giovanotto. Le cose si perdono, negli archivi. A meno che qualcuno non mi dia un buon motivo per ritrovarle.",{"if":"item.promemoria || item.foto1944","do":["beps[think]: (Un buon motivo. Forse dovrei mostrarle quello che ho trovato.)"]}]},{"id":"alluvione","label":"L'alluvione del '66","icon":"city","do":["archivista: Avevo otto anni. L'acqua è entrata qui sotto alle sette del mattino e ci è rimasta due giorni.","archivista: Abbiamo asciugato i fascicoli con la carta assorbente, i phon, le stufe a gas. Gli «angeli del fango» venivano da tutto il mondo.","archivista[sad]: Mio padre veniva ogni notte. Non era archivista. Diceva solo che c'erano «carte da salvare prima delle altre».","@stat:conoscenza+1"],"once":true},{"id":"orfeo","label":"Che cos'è Orfeo?","icon":"symbol","if":"flag.catalogo_ok","once":true,"do":["archivista[think]: Una leggenda da archivisti. Una società di custodi nata durante la guerra.","archivista: Nascondevano persone. E carte. Soprattutto i nomi: chi era stato salvato, e chi aveva tradito.","archivista[sad]: Mio padre, Renzo, ne parlava solo quando beveva. Diceva di essere stato «il Barcaiolo». Portava la gente di là dall'Arno, di notte, in barca, quando i ponti non c'erano più.","archivista: Io non ci sono mai entrata. Per scelta. Certe eredità si rifiutano.","@flag:ottavia_padre","@clue:barcaiolo","@stat:conoscenza+1"]},{"id":"donna","label":"La donna col cappello","icon":"photo","if":"flag.catalogo_ok && item.foto1944","once":true,"do":["archivista: La Testimone. Mio padre la chiamava così.","archivista: Diceva che c'era sempre, e non c'era mai. Che nelle fotografie stava sempre un passo in disparte, nello stesso punto.","archivista[worried]: L'ho vista anch'io, una volta. Nel 1998. Qui, in sala. Ha chiesto il cassetto O, poi è sparita.","@clue:testimone","@stat:conoscenza+1"]},{"id":"deposito","label":"Possiamo entrare nel deposito?","icon":"key","if":"flag.met_kiki && !flag.deposito_ok","do":["archivista: La signorina Morel ha la tessera. Lei no, giovanotto. Ma se la accompagna… dieci minuti.","@flag:deposito_ok","@objective:o1_deposito"]}],"items":{"promemoria":[{"if":"!flag.catalogo_ok","do":["archivista[surprised]: Dove l'ha trovato?","beps: In una stanza murata. Con un computer del '98 e un medaglione nel muro.","archivista: «Si parte dalla scheda O-1.» …","archivista: Va bene. Ho appena ritrovato la chiave. Che fortuna.","@sfx:click","@flag:catalogo_ok","@objective:o1_catena"]},{"do":["archivista: L'ho già letto, giovanotto. Il cassetto è aperto."]}],"foto1944":[{"if":"!flag.catalogo_ok","do":["archivista[surprised]: …","archivista[sad]: Il secondo da sinistra. Quello col berretto. È mio padre, Renzo Ricci.","archivista: Non l'avevo mai visto così giovane.","archivista: Va bene, giovanotto. Le apro il cassetto O. Ma non mi chieda niente che non voglio sapere.","@sfx:click","@flag:catalogo_ok","@flag:ottavia_padre","@objective:o1_catena","@stat:conoscenza+1"]},{"do":["archivista[sad]: Mio padre. Il secondo da sinistra. Me la lasci guardare ancora un momento."]}],"scheda_o17":["archivista: O-17. Provenienza Parigi. Il deposito, ripiano 17. Se ci va, non mi dica cosa trova."],"medaglione_b":["archivista[worried]: Mio padre ne aveva uno simile. Lo hanno sepolto con lui. Metta via quella cosa, giovanotto."],"*":["archivista: Interessante. Ma non è materiale d'archivio."]}},"kiki_pre":{"npc":"kiki_npc","intro":["kiki_npc[skeptical]: Shh. Sala di lettura."],"byeLabel":"Lasciala leggere","topics":[{"id":"contrario","label":"Scusi, sta leggendo al contrario.","icon":"question","once":true,"do":["kiki_npc[skeptical]: È un esercizio. Si chiama «farsi gli affari propri». Glielo consiglio."]},{"id":"orfeo","label":"Conosce il fondo Orfeo?","icon":"symbol","once":true,"do":["kiki_npc: …","kiki_npc[think]: No. Mai sentito. Lei?","beps: Neanche.","kiki_npc: Bene. Allora siamo d'accordo."]}]},"tommaso":{"npc":"tommaso","intro":["tommaso: Cappuccino alle dieci di sera. Io non giudico. Io servo."],"topics":[{"id":"cappuccino","label":"Un cappuccino, per favore","icon":"talk","once":true,"do":["tommaso: Arriva. La signorina lo vuole con la cannella, lo so già.","kiki[surprised]: Come fai a saperlo?","tommaso: Le signorine che entrano bagnate alle dieci di sera vogliono sempre la cannella."]},{"id":"donna","label":"Hai mai visto una donna col cappello nero?","icon":"person","if":"flag.woman_1 || item.foto1944","once":true,"do":["tommaso[think]: Il giovedì. Da anni. Tè nero, niente zucchero.","tommaso: Lascia sempre una moneta da 500 lire sul piattino. Lire, capito? Io le tengo in un barattolo. Ne ho quaranta.","beps[surprised]: 500 lire. Come quella sul gradino.","@clue:cinquecento_lire","@stat:conoscenza+1"]},{"id":"grigio","label":"E un uomo col cappotto grigio?","icon":"person","if":"clue.uomo_grigio || clue.voce_buio","once":true,"do":["tommaso: Il notaio Varano? Viene a volte. Lascia mance enormi e non sorride mai.","tommaso: Una volta gli è caduto un mazzo di chiavi. Sul portachiavi c'era una lira. Tipo quella dei musicisti.","@flag:varano_named","@clue:varano_lira","@stat:conoscenza+1"]}],"items":{"moneta":["tommaso[surprised]: 500 lire! Allora siete del giro. Del giro di chi, non lo so. Ma siete del giro."],"*":["tommaso: Bello. Lo prende con lo zucchero o senza?"]}},"varano_c1":{"npc":"varano","linear":true,"first":["varano: Bella serata per un archivio, Giuseppe.","beps[surprised]: Conosce il mio nome.","varano: Conosco il nome di chiunque metta le mani su certe carte. Le do un consiglio gratuito, cosa rara per un notaio:","varano: restituisca quel computer al cantiere e torni a riparare stampanti.",{"choice":[{"label":"«Chi è lei?»","do":["varano: Uno che ha letto quella lista prima di lei. E che avrebbe preferito non leggerla."]},{"label":"«Mi sta minacciando?»","do":["varano: La sto avvisando. È diverso. Legalmente, intendo."]},{"label":"«Era lei, nel deposito.»","do":["varano: Io sono in molti posti, Giuseppe. È il vantaggio di essere noiosi: nessuno ti nota."]}]},{"if":"present.kiki","do":["varano: Buonanotte, signorina Morel. Sua nonna aveva la stessa espressione, quando non era d'accordo.","kiki[angry]: Lei non sa niente di mia nonna.","varano: So molto meno di quanto vorrei. Buonanotte."]},"@flag:varano_lungarno_gone","@refresh"],"intro":[]},"pdf_password":{"linear":true,"intro":["@flag:pdf_tried","kiki: Inserisci la chiavetta. Il PDF chiede una password.",{"choice":[{"label":"Prova «ORFEO»","do":["@sfx:fail","kiki: «Password errata.» Sarebbe stato troppo facile."]},{"label":"Prova «1944»","do":["@sfx:fail","kiki: «Password errata.»"]},{"label":"Prova «EURIDICE»","do":["@sfx:fail","kiki[think]: «Password errata.» Però l'idea non era male."]},{"label":"Il giorno in cui l'acqua arrivò al terzo gradino","if":"item.scheda_o17","do":[{"if":"clue.alluvione","do":["beps: 4 novembre 1966. C'è scritto sulla targa del Lungarno. Prova «04111966».","@stat:conoscenza+1"],"else":["kiki: L'alluvione. Il 4 novembre 1966: lo sa ogni fiorentino. C'è anche una targa sul Lungarno.","@clue:alluvione"]},"@sfx:success","kiki[surprised]: Si apre.","narr: LISTA_17. Diciassette righe. Quattro sono leggibili:","narr: I · Orfeo, la Guida — la lira. II · Euridice, la Testimone — la luna. VI · Il Barcaiolo, colui che traghetta — l'àncora. XIV · Il Libraio, che custodisce le parole — la foglia.","kiki: Il resto è rumore. Il file è stato danneggiato. O tagliato apposta.","beps: Euridice. La Testimone. La donna col cappello.","@flag:pdf_open","@flag:lista_seen","@clue:lista_parziale","@stat:conoscenza+1"]}]}]},"helene":{"npc":"helene","first":["@flag:helene_met","@person:helene","helene[surprised]: Federica! Mon Dieu, comme tu ressembles à Ada.","kiki[tender]: Ciao, Hélène.","helene: E lui?","kiki: Lui è Beps. Ha trovato l'altra metà.","helene[think]: …L'altra metà. Allora è cominciato.","helene: Tenete. Le chiavi di casa di Ada. Le ho tenute io, in questi anni. Ma prima ditemi cosa vi porta qui.","@objective:o2_foto1967"],"intro":[{"if":"active=='kiki'","do":["helene[smile]: Dimmi, chérie."]},{"do":["helene: Sì, monsieur Beps?"]}],"byeLabel":"Merci, Hélène","topics":[{"id":"foto1967","label":"La fotografia del 1967","icon":"photo","if":"!item.foto1967 && !puzzle.c2_sovrapposizione","do":["helene: Avete la busta di mio padre. Allora sapete già dove guardare.","helene: Ecco la stampa del '67. E il negativo originale: sul retro della pellicola mio padre scriveva sempre qualcosa.","helene: Stampatelo voi. La camera oscura è dietro la tenda nera. Non aprite la tenda mentre c'è la carta fuori.","@give:foto1967","@give:negativo","@clue:foto_1967","@objective:o2_sovrapponi"]},{"id":"studio","label":"Lo Studio Marchetti","icon":"city","do":["helene: Mio padre Jacques l'ha aperto nel 1955. Ritratti, matrimoni, qualche reportage.","helene[think]: E riunioni di persone che non volevano essere fotografate. Ma lui le fotografava lo stesso. Era il suo compito."]},{"id":"ada","label":"Ada","icon":"heart","once":true,"do":["helene[sad]: Ada mi ha insegnato a guardare. Diceva che la verità sta sempre un passo fuori dall'inquadratura.","kiki[sad]: Lo diceva anche a me.","helene: Comprava i libri da Monsieur Albert, sul Quai des Grands-Augustins. Ogni settimana, per cinquant'anni. Se c'è qualcuno che conosce i suoi segreti di carta, è lui.","@stat:legame+1","@flag:albert_hint"]},{"id":"orfeo","label":"Che cos'è Orfeo?","icon":"symbol","once":true,"do":["helene[worried]: Non sono io quella a cui chiederlo. Non ancora.","beps: Questa risposta l'ho già sentita. Di solito precede guai.","helene[smile]: Allora siete sulla strada giusta.","@flag:helene_evasiva"]},{"id":"donna","label":"La donna col cappello","icon":"person","if":"item.foto1944","once":true,"do":["helene: Mio padre la metteva sempre nello stesso punto, nelle foto di gruppo. Era la regola.","helene: La Testimone deve esserci. Anche quando non c'è.","@clue:testimone"]}],"items":{"foto1944":["helene[sad]: Firenze, '44. Mio padre aveva sei anni, quel giorno. Era tra la folla, dietro il fotografo. Lo raccontava sempre."],"busta_e":["helene: La busta in cui mio padre spediva le stampe a Firenze. Nel '67 ne ha mandata una sola, e non è mai tornata indietro."],"medaglione":["helene[surprised]: Intero. Ada l'ha cercato per cinquant'anni.","helene: Un medaglione così non si mette al collo. Si appoggia. Su qualcosa di stampato, di solito."],"medaglione_b":["helene: Metà. Dov'è l'altra?"],"foto1967":["helene: Il negativo, prima stampatelo. Poi sovrapponete le due foto sul banco luminoso. Ci sono i crocini apposta."],"*":["helene: Joli. Ma non è una fotografia."]}},"albert":{"npc":"albert","first":["@person:albert","albert: Bonjour. Qui si guarda, si tocca con gli occhi, e si compra con le domande."],"intro":["albert: Alors?"],"byeLabel":"Au revoir","topics":[{"id":"orfeo","label":"Ha qualcosa su Orfeo?","icon":"symbol","if":"!item.libretto && !item.mappa && !puzzle.c2_mappa","do":["albert: Orfeo? Tre Ovidio, due Monteverdi e un libretto molto speciale, che vendo solo a chi risponde a una domanda.","albert: Chi ha portato Orfeo all'Opéra di Parigi, nel 1774?",{"choice":[{"label":"Claudio Monteverdi","do":["albert: Mantova, 1607. Bellissimo. Non Parigi. Riprovate quando volete."]},{"label":"Christoph Willibald Gluck","do":["albert[smile]: Voilà. «Orphée et Eurydice», versione francese. Il libretto è vostro. Pagate con un sorriso.","@give:libretto","@stat:conoscenza+1","@objective:o2_libretto"]},{"label":"Jacques Offenbach","do":["albert[laugh]: Ah! L'Orfeo all'inferno! Il can-can! No, mon ami: quello è del 1858, e lì Orfeo è contentissimo di perdere Euridice."]},{"label":"«Kiki?»","if":"present.kiki && active=='beps'","line":"beps: Kiki?","do":["kiki[smile]: Gluck, Beps. 1774, con il tenore Legros. Nonna aveva il disco.","albert: La signorina ha studiato. Prego, il libretto.","@give:libretto","@inc:coop","@objective:o2_libretto"]}]}],"repeatSafe":true},{"id":"donna","label":"Conosceva la donna col cappello?","icon":"person","if":"item.foto1944 || item.foto1967","once":true,"do":["albert: La Dame au chapeau. Comprava Gluck ogni anno, il 12 marzo. Diceva che era un anniversario.","albert: Di cosa, non l'ho mai chiesto. Ai quais non si chiede.","@clue:dodici_marzo","@stat:conoscenza+1"]},{"id":"quai","label":"Da quanto tempo è qui?","icon":"talk","optional":true,"once":true,"do":["albert: Dal 1971. Il Quai mi ha adottato. Io ho adottato un gabbiano. Si chiama Sartre.","beps: Perché Sartre?","albert: Perché mi guarda come se l'inferno fossi io."]}],"items":{"moneta":["albert[surprised]: 500 lire! La Dame au chapeau ne lasciava una sotto ogni libro che comprava.","albert: Voi chi siete, i suoi nipoti?",{"if":"present.kiki","do":["kiki[sad]: Più o meno.","@clue:cinquecento_lire"]}],"medaglione":["albert: Joli. Un medaglione con dei fori… Per leggere, non per indossare. Avete bisogno di una carta, mon ami."],"*":["albert: Non compro, vendo. E solo libri."]}},"sviluppo":{"linear":true,"intro":[{"if":"present.kiki","do":["kiki: Il negativo va nell'ingranditore. Uno espone, l'altro sviluppa. Chi fa cosa?",{"choice":[{"label":"«Espongo io, tu sviluppi.»","do":["kiki[smile]: Ottima divisione dei compiti, informatico.","@inc:coop"]},{"label":"«Fai tu, io guardo e imparo.»","do":["kiki: Guarda bene, allora. Domani ti interrogo.","@stat:fiducia+1"]},{"label":"«Faccio tutto io, ho visto un tutorial.»","do":["kiki[skeptical]: Un tutorial. Va bene, genio.","narr: Trenta secondi dopo.","kiki[laugh]: Sovraesposto. Nero come il caffè di Sandro. Rifaccio io."]}]}],"else":["Espongo, sviluppo, fisso. Come diceva Kiki."]},"@anim:use","@sfx:tape","narr: Sotto la luce rossa, sulla carta bagnata, l'immagine affiora lentamente: il retro della stampa originale, con una riga a inchiostro.","narr: «La stella guida la tacca.»","@flag:retro_1967","@clue:stella_tacca","@take:negativo",{"if":"present.kiki","do":["kiki[surprised]: È la calligrafia di nonna."]},"beps[think]: La stella… e la tacca. Il medaglione ha una tacca sul bordo."]},"lettera_ada":{"linear":true,"intro":["@flag:lettera_letta",{"if":"stat.fiducia>=2","do":["kiki[sad]: Te la leggo. Ad alta voce. Così non devo farlo da sola.","kiki: «Federica, se leggi questo hai trovato l'altra metà. Non avere paura di chi la porta: io mi sono fidata una volta sola, ed era la persona giusta.»","kiki: «Non voltarti indietro. È l'unica regola. — Nonna»",{"choice":[{"label":"«Tua nonna aveva una bella calligrafia.»","do":["kiki[laugh]: Dio, sei impossibile. … Grazie.","@stat:legame+1"]},{"label":"«Io non ho paura di portarla, l'altra metà.»","tone":"tender","do":["kiki[tender]: Lo so. È questo che mi spaventa.","@stat:legame+1","@stat:fiducia+1"]},{"label":"Resta in silenzio, vicino a lei","line":"beps[tender]: …","do":["kiki[sad]: …","@stat:legame+1"]}]}],"else":["narr: Kiki legge in silenzio. Ripiega la lettera. Ci mette un po' prima di parlare.","kiki[sad]: Dice di non voltarmi indietro. È l'unica regola.","beps: Una buona regola.","kiki: Una regola difficile. Tienila tu, la lettera. Io la perderei apposta."]},"@clue:lettera_ada"]},"c2_fine":{"linear":true,"intro":["@sfx:phone","beps[surprised]: Numero sconosciuto.","@anim:phone","varano: Giuseppe. La Teodosiana è chiusa il lunedì. Domani è martedì. Buon viaggio.","beps[angry]: Come fa a…","narr: Ha riattaccato.","kiki[determined]: Ci segue. Ci precede. Fa quello che vuole.","kiki: Allora noi andiamo più veloci. Il primo treno per Roma parte alle sei.","@cutscene:c2_fine","@chapter:3","@goto:c3_piazza"]},"peppe":{"npc":"agente","first":["agente: Ritratto? Venti euro singolo, trenta in coppia. Per voi trenta, siete una coppia, si vede.","kiki[skeptical]: Non siamo una coppia."],"intro":["agente: Allora, ritratto?"],"byeLabel":"No, grazie","topics":[{"id":"ritratto","label":"«Va bene. In coppia.»","icon":"us","once":true,"do":["narr: Dieci minuti dopo.","agente: Ecco qua.","beps[surprised]: Mi hai fatto il naso enorme.","kiki[laugh]: E io ho gli occhi a cuore. Peppe, sei un truffatore.","agente: Io disegno quello che vedo, signorina.","@stat:legame+1"]},{"id":"donna","label":"Ha visto una donna col cappello nero?","icon":"person","once":true,"do":["agente: Quella del balcone? Vive lì da sempre, dicono. Ma non l'ho mai vista uscire. Mai.","agente: Una volta mi ha lanciato una moneta. Cinquecento lire. Pensa te."]}]},"ilario":{"npc":"ilario","first":["@person:ilario","ilario: Due giovani in una biblioteca a quest'ora. O siete studiosi, o siete innamorati, o siete nei guai.","beps: Una delle tre.","ilario[smile]: Allora siete nei guai. Gli studiosi non arrossiscono."],"intro":["ilario: Dite pure. Ho novantun anni, ma ascolto in fretta."],"topics":[{"id":"teodosiana","label":"La Teodosiana","icon":"city","do":["ilario: Fondata nel 1601 da un cardinale con troppi libri e pochi amici.","ilario: Quarantamila volumi, otto fantasmi, un gatto. Il gatto è l'unico che paga le tasse."]},{"id":"orfeo","label":"Orfeo","icon":"symbol","if":"!flag.cassetti_ok","do":["ilario[think]: Orfeo. Il cantore. Scese agli inferi per amore e risalì per obbedienza. Poi si voltò.","ilario: Perché me lo chiedete?",{"if":"item.medaglione","do":["beps: (Forse dovrei mostrargli il medaglione.)"]}]},{"id":"donna","label":"La donna col cappello","icon":"photo","if":"flag.ilario_libraio","once":true,"do":["ilario: La Testimone viene qui ogni tanto. Nel 1978 si fece fotografare sotto il busto di Teodosio. Sempre nello stesso punto.","ilario[think]: Ma non era la stessa donna del '67. Il cappello sì. La donna no.","@flag:euridice_ruolo","@clue:euridice_ruolo","@stat:conoscenza+1"]},{"id":"xvii","label":"Il ruolo cancellato","icon":"warning","if":"flag.ilario_libraio","once":true,"do":["ilario[sad]: Il diciassettesimo. Il Ponte.","ilario: Nel 1967, a Parigi, sedici custodi votarono per abolirlo. Io votai a favore.","ilario: Me ne pento ogni giorno da cinquantanove anni.","beps: Che cosa faceva il Ponte?","ilario: Doveva decidere quando il Registro sarebbe stato reso pubblico. Era il ponte tra Orfeo e il mondo. Lo abbiamo fatto saltare, come i tedeschi coi ponti di Firenze.","@clue:ruolo_ponte","@flag:erased_role_known","@stat:conoscenza+2"]},{"id":"notaio","label":"Il Notaio","icon":"person","if":"flag.ilario_libraio","once":true,"do":["ilario[worried]: Varano. Il figlio di Ettore. Ha ereditato il ruolo XI, la bilancia.","ilario: Ettore era un uomo pauroso. Aurelio è peggio: è un uomo ferito. I paurosi scappano. I feriti bruciano.","@flag:varano_named","@stat:conoscenza+1"]}],"items":{"medaglione":[{"if":"!flag.cassetti_ok","do":["ilario[surprised]: …","ilario: Intero. Non lo vedevo intero dal 1967.","ilario: Allora sono io che devo parlare. Sono il Libraio. Ruolo XIV. Custodisco le parole.","ilario: E questa è la chiave della Sala dei Cassetti. Ve la do perché la porta questo medaglione, non perché mi fido di voi. Mi fiderò dopo.","@flag:cassetti_ok","@flag:ilario_libraio","@clue:libraio","@objective:o3_sala","@stat:conoscenza+1"]},{"do":["ilario: Lo so, lo so. È bellissimo. Ora andate, prima che cambi idea."]}],"mappa":["ilario[smile]: La mappa di Ada! Gliel'avevo venduta io, nel '68. In cambio di una bottiglia di Chianti e di un segreto."],"foto1967":["ilario: Parigi, '67. Ero lì. Dietro il fotografo, a sinistra. Si vede la mia ombra, guardi."],"*":["ilario: Interessante. Ma alla mia età interessa solo quello che si può leggere."]}},"allarme":{"linear":true,"intro":["@sfx:door","@flag:allarme","@refresh","narr: Dal salone arrivano voci. Passi pesanti. La voce di Don Ilario, altissima: «La biblioteca è chiusa, signori! CHIUSA!»","kiki[scared]: Gli uomini del Notaio.","beps[worried]: La porta del salone è fuori discussione. C'è un cancello di servizio… chiuso dall'altra parte.","kiki: E una grata, laggiù. Avvitata.","@objective:o3_fuga"]},"fuga_riuniti":{"linear":true,"intro":["@join","@unflag:leva_tenuta","kiki: Ci sei? Lascio!","@sfx:door","narr: Il cancello ricade con un colpo sordo. Dall'altra parte, qualcuno lo scuote. Troppo tardi.","beps[surprised]: Questo è stato…","kiki[smile]: Lavoro di squadra. Ora la scala. Da soli non ci arriviamo.","@objective:o3_scala"]},"lista_osteria":{"linear":true,"intro":["@flag:lista_letta","@flag:lista_full","@flag:lista_seen","kiki: Diciassette ruoli. Per ognuno, chi lo ha custodito dal 1944 a oggi.","beps: Orfeo, Euridice, il Cartografo, l'Archivista, il Tipografo, il Barcaiolo… Renzo Ricci, il padre di Ottavia.","kiki: Euridice: Lucia Morel, 1944. Ada Morel, 1967. Poi una riga coperta d'inchiostro. Mia bisnonna e mia nonna, Beps.","beps: XI, il Notaio: Ettore Varano, poi Aurelio Varano.","kiki: E il XVII: raschiato. Ma qui, sul margine, c'è un'annotazione minuscola.","narr: «Il Sigillo è diviso in quattro. Uno resti a Roma. Uno nella cassetta 17 della Banca del Giglio. Uno nel muro dove l'acqua si fermò. Uno sul ponte che non cadde, presso chi custodisce le chiavi.»","beps[think]: Roma l'abbiamo. La Banca del Giglio: la chiave d'ottone, «B.d.G.». Il muro dove l'acqua si fermò: la stanza murata. E il ponte che non cadde…","kiki: Il Ponte Vecchio. Tutto torna a Firenze.",{"choice":[{"label":"«Tutto torna a Firenze. Anche noi.»","do":["kiki[smile]: Anche noi. Mi piace come suona.","@stat:legame+1"]},{"label":"«Dobbiamo stare attenti: Varano sa dove andremo.»","do":["kiki: Allora non ci separiamo. Mai.","beps: Mai.","@stat:fiducia+1","@inc:coop"]},{"label":"«Tua nonna e tua bisnonna erano Euridice. E tu?»","do":["kiki[worried]: Io… non lo so. Non me l'ha mai chiesto nessuno.","kiki: Forse è per questo che nonna ha lasciato tutto a metà. Perché scegliessi io.","@stat:conoscenza+1","@stat:fiducia+1"]}]},"@clue:sigillo_quattro","@cutscene:c3_fine","@chapter:4","@goto:c4_studio"]},"sms_kiki":{"linear":true,"intro":["@sfx:phone","@anim:phone","beps: Un messaggio. Da Kiki.","narr: «Non cercarmi. Sto bene. — Federica.» In allegato, una foto: stalattiti, una statua bianca, una fontana.","beps[worried]: Kiki non firma mai Federica.",{"if":"stat.fiducia>=4","do":["beps[determined]: Lo fa solo con la gente di cui non si fida. Me l'ha detto a Roma. Questo messaggio non l'ha scritto lei. O l'ha scritto lei apposta, perché capissi.","@stat:fiducia+1"],"else":["beps[think]: Mi ha detto di chiamarla Kiki dal primo giorno. «Federica» la usa solo con chi non si fida. Qualcosa non va."]},"beps: E questa foto… stalattiti finte, una Venere che esce dal bagno. È la Grotta del Buontalenti. Boboli.","beps: La lista: «Uno sul ponte che non cadde, presso chi custodisce le chiavi.» Il Ponte Vecchio. Il Corridoio porta dritto a Boboli.","@flag:sms_ricevuto","@clue:sms_federica","@objective:o4_ponte"]},"neri":{"npc":"neri","first":["@person:neri","neri: Buongiorno. Se cerca una fede nuziale, ho un'offerta. Se cerca guai, ho la faccia di chi ne ha visti abbastanza."],"intro":["neri: Mi dica."],"topics":[{"id":"frammento","label":"Lei custodisce qualcosa di Orfeo?","icon":"symbol","if":"!item.sigillo_d && !puzzle.c4_sigillo","do":["neri[skeptical]: Orfeo? Il cantante?","beps: Il Custode delle Chiavi. Ruolo XV.","neri: Non so di cosa parla.",{"if":"item.lista17","do":["beps: (La Lista dei 17. Il suo nome dovrebbe esserci.)"]}]},{"id":"corridoio","label":"La porta del Corridoio","icon":"key","if":"flag.neri_fiducia && !flag.neri_chiave","do":["neri: La porticina? Mio nonno aveva la chiave. Io ce l'ho ancora. Non l'ho mai usata.","neri: Prenda. Se va dove credo, porti il Sigillo intero. Là sotto niente si apre a pezzi.","@flag:neri_chiave","@clue:corridoio"]},{"id":"banco","label":"Posso usare il suo banco?","icon":"item","if":"flag.neri_fiducia && !flag.neri_banco","do":["neri: Il banco? Mio nonno ci ha diviso il Sigillo nel '67. È giusto che ci torni intero.","neri: Faccia lei. Ha mani da informatico, non da orafo, ma il Sigillo si ricompone da solo, se sai leggerlo.","@flag:neri_banco","@objective:o4_sigillo"]},{"id":"nonno","label":"Suo nonno","icon":"person","if":"flag.neri_fiducia","once":true,"do":["neri[sad]: Oreste Neri. Nel '44 teneva le chiavi di mezza Firenze: botteghe, cantine, il Corridoio. Ci passavano di notte, sopra la testa dei tedeschi.","neri: Diceva: «Le chiavi aprono, ma soprattutto chiudono». Non l'ho mai capito.","@stat:conoscenza+1"]},{"id":"kiki","label":"Ha visto una ragazza con la giacca marrone e gli occhiali?","icon":"question","once":true,"do":["neri: Stamattina presto. Con un signore col cappotto grigio. Lei camminava normale, ma si girava. Ogni tre passi, si girava.","beps[worried]: Si girava.","neri: Come se lasciasse dietro qualcosa. O qualcuno."]}],"items":{"lista17":[{"if":"!flag.neri_fiducia","do":["neri[surprised]: …","neri: XV. Il Custode delle Chiavi. Oreste Neri, 1944. Tommaso Neri, 1967. E poi… Stefano Neri. Io.","neri: Mio padre mi ha lasciato un pezzo di bronzo e un ordine: «Darlo solo a chi porta la lista». Non ci avevo mai creduto.","neri: Eccolo. TARTI, c'è scritto sul bordo.","@give:sigillo_d","@flag:neri_fiducia","@stat:conoscenza+1"]},{"do":["neri: Il mio nome è lì. Che strano effetto."]}],"sigillo_a":["neri: Bronzo e ceralacca. Un lavoro di mio nonno. Riconosco il bulino."],"medaglione":["neri: Bel lavoro. Ottone, primi Quaranta. La tacca sul bordo serve a orientarlo, sa?"],"*":["neri: Bello. Ma non lo compro."]}},"bellandi":{"npc":"bellandi","first":["@person:bellandi","bellandi: Buongiorno. Cassette di sicurezza. Mi dica in cosa posso esserle utile secondo il regolamento interno, articolo quattro."],"intro":["bellandi: Prego."],"topics":[{"id":"cassetta","label":"Vorrei aprire la cassetta 17","icon":"key","if":"!flag.cassetta_aperta","do":["bellandi: La 17. Intestata nel 1944, rinnovata ogni dieci anni da un fondo fiduciario parigino.",{"if":"!item.chiave_ottone","do":["bellandi: Ha la chiave del cliente?","beps: … No.","bellandi: Allora no."],"else":["bellandi: Vedo che ha la chiave. Articolo nove: devo chiederle il nome del titolare.",{"choice":[{"label":"«Orfeo»","do":["@sfx:fail","bellandi: No. Mi spiace."]},{"label":"«Euridice»","do":["bellandi[surprised]: …Corretto.","narr: Due chiavi, due giri. Il cassetto scivola fuori.","beps: Dentro: un quarto di sigillo… NON. Una bobina di nastro magnetico. E un foglio.","@give:sigillo_b","@give:nastro","@flag:cassetta_aperta","@clue:nastro_orfeo","@stat:conoscenza+1","bellandi: Firmi qui. E qui. E qui."]},{"label":"«Il Ponte»","do":["@sfx:fail","bellandi: No."]},{"label":"«Varano»","do":["@sfx:fail","bellandi[skeptical]: Decisamente no. Il signor Varano ha la cassetta 11."]}]}]}],"repeatSafe":true},{"id":"varano","label":"Il notaio Varano viene spesso?","icon":"person","once":true,"do":["bellandi: Non posso rispondere. Articolo dodici.","bellandi: …Ieri. Ha chiesto della 17. Gli ho detto che non era sua. Si è tolto il cappello e se n'è andato. Un vero signore. Inquietante, ma un signore."]},{"id":"regolamento","label":"Mi parli del regolamento","icon":"doc","optional":true,"once":true,"do":["bellandi[smile]: Volentieri. Articolo uno…","narr: Venti minuti dopo.","bellandi: …e l'articolo trentatré riguarda i piccioni.","beps: Bellissimo. Grazie. Davvero."]}],"items":{"chiave_ottone":["bellandi: Una chiave del cliente. Per usarla, mi chieda di aprire la cassetta."],"*":["bellandi: Non è un documento d'identità."]}},"varano_c4":{"npc":"varano","first":["@flag:varano_named","@person:varano","varano: Mi chiamo Aurelio Varano. Notaio. Ruolo XI di Orfeo, la Bilancia.","varano: La signorina Morel è libera di andare quando vuole. Lo è sempre stata.","kiki[angry]: Mi ha presa sotto casa e mi ha detto: «Venga, o lo troveranno prima gli altri.» Non era una domanda.","varano: Era un consiglio. Ho la brutta abitudine di dare consigli che sembrano minacce. È il mestiere."],"intro":["varano: Prego, Giuseppe. Parliamo."],"byeLabel":"«Kiki viene con me. Adesso.»","topics":[{"id":"perche","label":"Perché ha preso Kiki?","icon":"question","once":true,"do":["varano: Perché volevo parlarle senza di lei. E con lei senza di lei.","varano: Lei ripara computer, Giuseppe. Sa che certi sistemi vanno spenti prima che si rompano da soli.","varano: Il Registro di Orfeo è uno di quegli edifici."]},{"id":"registro","label":"Che cos'è il Registro?","icon":"doc","once":true,"do":["varano: Ottant'anni di nomi. Chi ha salvato, chi è stato salvato. E chi ha venduto chi.","varano: Se lo rendete pubblico, i nipoti pagheranno per i nonni. Famiglie intere. Persone che non hanno fatto niente.","varano[sad]: Io lo so bene.","@clue:registro","@stat:conoscenza+1"]},{"id":"bruciare","label":"Lei vuole bruciarlo.","icon":"warning","once":true,"do":["varano: Voglio chiudere una ferita. La cenere è l'unica cosa che non accusa nessuno.","kiki[angry]: La cenere non salva nessuno, notaio.","varano: Nemmeno la verità, signorina. Nemmeno la verità."]},{"id":"sigillo","label":"Il Sigillo","icon":"key","once":true,"do":["varano: Lo tenga. Il Sigillo apre la Camera di Orfeo. Prima o poi ci arriverete. E io sarò lì.","beps: Perché non lo prende?","varano: Perché la Camera si apre solo in due. Ve ne accorgerete. Io…","varano[sad]: Io sono sempre stato solo."]},{"id":"nome","label":"«Varano.» Ho già sentito questo nome.","icon":"person","if":"clue.varano_finanzia || clue.varano_lira","once":true,"do":["varano: Il palazzo di via de' Bardi. Lo finanzio io. Volevo arrivare alla stanza murata prima di chiunque.","varano[sad]: Sono arrivato secondo. Dopo un informatico con un coltellino e un capocantiere che vuole il caffè.","@stat:conoscenza+1"]}],"bye":["varano: Vada, Giuseppe. La porti fuori.","varano: Ci rivedremo a Parigi. Sarà lì che capirete chi sono.","narr: Il Notaio si alza il bavero e sparisce dietro la Venere, come un attore che conosce l'uscita di scena.","@flag:varano_grotta_via","@flag:kiki_liberata","@together:true","@show:kiki","@unlockswitch","@refresh","@dialogue:riunione_grotta"]},"riunione_grotta":{"linear":true,"intro":["kiki[sad]: Beps.",{"choice":[{"label":"Abbracciala","tone":"tender","line":"beps[tender]: …","do":["narr: Kiki si irrigidisce un secondo. Poi si lascia andare.","kiki[tender]: Sei venuto.","beps: «Federica.» Non firmi mai Federica.","kiki[smile]: Lo sapevo che l'avresti capito.","@stat:legame+2"]},{"label":"«Ti ha fatto del male?»","do":["kiki: No. Ha parlato. Tanto. Di suo nonno, di sua nonna. Di cenere.","kiki[worried]: Beps, non è un mostro. È peggio: è uno che crede di avere ragione.","@stat:conoscenza+1","@stat:fiducia+1"]},{"label":"«La prossima volta, i dieci minuti li cronometro io.»","do":["kiki[laugh]: Idiota. … Grazie.","@stat:legame+1","@stat:fiducia+1"]}]},"kiki: Il nastro. L'hai preso, vero? Varano ha detto una cosa: che la metà orientale del Registro è a Istanbul. Dal Traduttore.","beps: Istanbul.","kiki: Nonna ci andava ogni anno, a dicembre. Diceva che andava a «comprare tappeti». Non abbiamo mai avuto un tappeto.","@clue:istanbul","@objective:o4_partenza"]},"emre":{"npc":"emre","first":["@person:emre","emre: Çay? Tè? Thé? Tea? Due lire. Euro. Sorrisi. Accetto tutto."],"intro":["emre: Çay?"],"byeLabel":"Teşekkürler","topics":[{"id":"te","label":"Due tè, per favore","icon":"talk","once":true,"do":["emre: Ecco. Bollente. Prendetelo dal bordo, non dalla pancia del bicchiere.","beps[surprised]: Ahi.","emre: Dalla pancia, l'ha preso.",{"if":"present.kiki","do":["kiki[laugh]: Ha detto dal bordo, Beps.","@stat:legame+1"]}]},{"id":"antiquario","label":"Cerchiamo un antiquario. «Dove vendono il tempo.»","icon":"question","once":true,"do":["emre: Selim Bey! Orologi, mappe, cose vecchie. In fondo a destra. Ditegli che vi manda Emre, mi dà un lira di mancia."]},{"id":"leva","label":"Ci serve una leva. Un piede di porco.","icon":"item","if":"flag.selim_camera && !item.piede_porco && !flag.botola_aperta","do":["emre: Per la botola del Valide Han? Tutti la vogliono aprire, nessuno ci riesce.","emre: Prendete questo. Me lo riportate. Se non me lo riportate, lo dico a Selim Bey.","@give:piede_porco"]},{"id":"donna","label":"Hai visto una donna col cappello nero?","icon":"person","if":"flag.woman_4","once":true,"do":["emre: La signora dei cinquecento? Viene ogni dicembre. Paga il tè con monete italiane vecchie. Io le tengo tutte.","emre: Quest'anno era diversa. Più giovane, forse. O è il cappello che invecchia le persone.","@stat:conoscenza+1"]}],"items":{"moneta":["emre[surprised]: Cinquecento lire! Siete parenti della signora col cappello?"],"*":["emre: Non compro. Vendo tè."]}},"selim":{"npc":"selim","first":["@person:selim","selim[surprised]: Federica. Ada aveva ragione: hai i suoi occhi e il carattere di tuo nonno.","kiki[surprised]: Conosceva mio nonno?","selim: Tutti conoscevano tuo nonno. Nessuno lo sopportava. Era il migliore di tutti.","selim: E voi siete il signor Beps. Ho saputo del Sigillo. Ho saputo della grotta. A Istanbul le notizie arrivano prima dei treni."],"intro":["selim: Prego, prego. Sedetevi. Il tè arriva."],"byeLabel":"A dopo, Selim Bey","topics":[{"id":"traduttore","label":"Lei è il Traduttore?","icon":"symbol","once":true,"do":["selim[smile]: Ruolo XVI. Le due frecce. Traduco Orfeo per chi parla un'altra lingua. E viceversa.","selim: Mia madre, Nermin, accoglieva qui chi fuggiva da Firenze nel '44. Arrivavano con i documenti falsi del Tipografo e una parola d'ordine: «Euridice».","@flag:selim_traduttore","@clue:traduttore","@stat:conoscenza+1"]},{"id":"registro","label":"La metà orientale del Registro","icon":"doc","if":"flag.selim_traduttore","once":true,"do":["selim: Non è una metà. È una mappa. Il Registro non è mai stato diviso: è sempre stato in un posto solo.","selim: Le metà sono le chiavi per arrivarci. Sotto questo Han c'è una camera con quattro anelli. Il vostro medaglione la apre. E vi dirà dove andare.","@flag:selim_camera","@objective:o5_camera","@stat:conoscenza+1"]},{"id":"lanterna","label":"Ci serve luce, là sotto","icon":"item","if":"flag.selim_camera && !item.lanterna","do":["selim: Prendete questa lanterna. Vede meglio delle torce elettriche.","beps: È una metafora?","selim[smile]: A Istanbul, tutto è una metafora. Anche le lanterne.","@give:lanterna"]},{"id":"botola","label":"Come si scende?","icon":"key","if":"flag.selim_camera","once":true,"do":["selim: Nel cortile del Valide Han c'è una botola. Arrugginita da quarant'anni. Emre, il ragazzo del tè, ha un piede di porco per ogni occasione."]},{"id":"ada","label":"Ada veniva qui ogni dicembre","icon":"heart","once":true,"do":["selim[sad]: Ogni dicembre per trent'anni. Diceva che veniva a comprare tappeti. Non ne ha mai comprato uno.","selim: Veniva a controllare che la Camera fosse chiusa. E a bere il tè con me. Credo più per il tè.","kiki[sad]: Non me l'ha mai detto.","selim: Ti voleva fuori da tutto questo. Poi ha capito che non poteva sceglierlo lei, per te.","@stat:legame+1"]},{"id":"donna","label":"La donna col cappello, al Bazar","icon":"person","if":"flag.woman_4","once":true,"do":["selim[think]: La Testimone? Qui, a dicembre?","selim: Non era Hélène. Hélène odia Istanbul: dice che ci sono troppi gatti.","beps: Allora chi era?","selim: Euridice è un ruolo, signor Beps. A volte ha più di una persona, come un vestito che passa di mano. A volte nessuno sa chi lo indossa.","@flag:helene_doubt","@flag:euridice_ruolo","@clue:euridice_ruolo","@stat:conoscenza+1"]}],"items":{"medaglione":["selim: Intero. Ada ne sarebbe felice. Guardatene il retro, con questa luce: le cose vere si leggono solo con la luce giusta.","@clue:retro_medaglione"],"lista17":["selim: XVI, Selim Aydın. Mi hanno scritto con la y senza puntino. Cinquant'anni che glielo dico."],"foto1967":["selim: Ada a trentun anni. Bella come una giornata di scirocco."],"*":["selim: Bello. Ve lo valuto? No? Peccato."]}},"tetto":{"linear":true,"intro":["@flag:tetto_scena","narr: Si siedono sul muretto. Sotto di loro, Istanbul accende le sue luci una per volta.","kiki: Nonna diceva che da qui si vede dove finisce l'Europa.","beps: Ed è bello sapere dove finisce?","kiki[tender]: No. È bello sapere che si può attraversare.","narr: Silenzio. Un traghetto suona la sirena, lontano.",{"choice":[{"label":"Baciala","tone":"tender","if":"stat.legame>=6","line":"beps[tender]: …","do":["@cutscene:bacio","@flag:bacio","kiki[tender]: Era ora, informatico.","beps[smile]: Stavo aspettando che finisse il download del coraggio.","kiki[laugh]: Idiota.","@stat:legame+2","@stat:fiducia+1"]},{"label":"«Kiki… sono felice che quella sera tu fossi in archivio.»","tone":"tender","do":[{"if":"stat.legame>=8","do":["kiki[tender]: Anch'io. Molto più di quanto ti dirò mai.","narr: È lei a baciarlo. Senza fretta.","@cutscene:bacio","@flag:bacio","@stat:legame+2"],"else":["kiki[tender]: Anch'io, Beps.","narr: Kiki gli prende la mano. La tiene. Non dice altro.","@flag:mano","@stat:legame+1"]}]},{"label":"«Sai che da qui il Wi-Fi prende benissimo?»","do":["kiki[laugh]: Sei impossibile.",{"if":"stat.legame>=10","do":["kiki[tender]: Ed è per questo che…","narr: Lo bacia, ridendo ancora.","@cutscene:bacio","@flag:bacio","@stat:legame+1"],"else":["kiki[smile]: Ottimo Wi-Fi. Sì.","narr: Appoggia la testa sulla sua spalla.","@flag:mano","@stat:legame+1"]}]}]},"@clue:tetto",{"if":"puzzle.c5_anelli","do":["@dialogue:c5_fine"]}]},"helene_c6":{"npc":"helene","first":["helene: Entrate. Chiudete la porta. Daguerre odia gli spifferi.","helene[sad]: Vi devo una verità. Prima che la sappiate da Varano.","helene: Il cappello. Questo. Era di Ada fino al 2019. Ora è mio.","helene: Sono io, Euridice. La Testimone. Ada mi ha passato il ruolo prima di morire.","kiki[surprised]: Tu? Eri tu sul Lungarno?","helene: Sul Lungarno, sì. A Roma, sì. Dovevo vedere se eravate pronti.","beps: E a Istanbul?","helene[worried]: …Io non sono mai stata a Istanbul a dicembre. Mai.","narr: Silenzio. Daguerre si stiracchia.","@flag:helene_euridice","@flag:helene_doubt","@flag:euridice_ruolo","@clue:euridice_ruolo","@clue:helene_euridice","@objective:o6_nastro"],"intro":["helene: Sì?"],"byeLabel":"Grazie, Hélène","topics":[{"id":"istanbul","label":"Allora chi era, a Istanbul?","icon":"question","once":true,"do":["helene[think]: Non lo so. Davvero. Euridice non è mai stata una persona sola. C'è sempre stata… una riserva. Qualcuno che Ada aveva scelto e non ci ha mai detto.","kiki: Una riserva.","helene: Ada aveva molti segreti. Questo è l'ultimo che non ho capito.","@stat:conoscenza+1"]},{"id":"nastro","label":"Il nastro di Orfeo","icon":"tape","if":"!flag.nastro_ascoltato","do":["helene: Il Revox è giù, nella sala di proiezione. L'ho fatto revisionare la settimana scorsa.","helene: Ascoltatelo. È la seduta del 12 marzo 1967. Io ero una bambina, aspettavo fuori dalla porta con mio padre."]},{"id":"archivio","label":"L'archivio di Orfeo","icon":"doc","once":true,"do":["helene: Passage des Libraires, la porta verde con la lira sul batacchio. Parola d'ordine: «Eurydice». Con la y.","helene: Ci troverete tutto. In disordine: Varano ci è passato prima di voi. Ha mischiato le carte. Letteralmente.","@flag:archivio_ok"]},{"id":"ruolo","label":"Perché Ada ha scelto te?","icon":"heart","once":true,"do":["helene[sad]: Perché ero la figlia del Fotografo. Perché c'ero sempre, dietro l'obiettivo, anche da bambina.","helene: E perché non voleva sceglierti, Federica. Voleva che fossi libera di non esserlo.","kiki[sad]: E se io volessi esserlo?","helene[smile]: Allora dovrai chiedermelo. E ti dirò di sì.","@stat:legame+1","@stat:fiducia+1"]}],"items":{"nastro":["helene: Quel nastro. Mio padre lo ha registrato di nascosto. Ettore Varano non lo ha mai saputo. Ascoltatelo giù."],"foto1967":["helene[sad]: Ada nel '67. Io ero dietro, con la macchina di papà al collo. Dodici anni."],"*":["helene: Joli."]}},"nastro":{"linear":true,"intro":["@flag:nastro_ascoltato","@sfx:tape","narr: Il nastro gira. Un fruscio, voci che parlano in italiano e francese, una sedia che si sposta.","narr: Voce di uomo: «Seduta straordinaria di Orfeo. Parigi, 12 marzo 1967. Ordine del giorno: abolizione del Ruolo XVII, il Ponte.»","narr: «Il Registro non sarà mai reso pubblico. I nomi dei delatori resteranno nel Registro, e il Registro resterà nell'ombra. Votiamo.»","narr: Voci. «Favorevole.» «Favorevole.» «Favorevole.» Quindici volte.","narr: Poi una voce di donna, ferma: «Contraria. Euridice vota contro. E il Ponte, Guido Sarti, vota contro. Siamo due.»","narr: Silenzio. Poi l'uomo: «Il notaio verbalizza: approvato all'unanimità dei presenti. Euridice risulta assente. Il Ponte risulta assente.»","narr: Voce di donna: «Ettore, io sono qui.» L'uomo: «Non nel verbale, Ada.»","narr: Il nastro finisce in un fruscio.","kiki[angry]: Nonna c'era. Ha votato contro. E lui l'ha cancellata dal verbale.","beps[angry]: Ettore Varano. Il padre di Aurelio. Ha falsificato l'unanimità.","beps[think]: E il Ponte aveva un nome: Guido Sarti. Il volto graffiato nella foto del '44.","@clue:verbale_falso","@clue:guido_sarti","@flag:erased_role_known","@stat:conoscenza+2",{"if":"puzzle.c6_cronologia","do":["@objective:o6_varano"],"else":["@objective:o6_archivio"]}]},"panchina_pn":{"linear":true,"intro":["narr: La neve cade sulla Senna. Si siedono vicini, più vicini di quanto serva per scaldarsi.","kiki: Beps. Quando tutto questo sarà finito…",{"choice":[{"label":"«…ti porto a cena. Una cena vera. Senza notai.»","do":["kiki[laugh]: Senza notai. Lo metto per iscritto.","@stat:legame+1"]},{"label":"«…non sarà finito. Io non me ne vado.»","tone":"tender","do":["kiki[tender]: Era la risposta giusta.",{"if":"!flag.bacio","do":["narr: Stavolta nessuno dei due fa una battuta. Si baciano sotto la neve, come in un film che entrambi giurerebbero di detestare.","@flag:bacio","@cutscene:bacio"]},"@stat:legame+2"]},{"label":"«…cosa farai tu?»","do":["kiki[think]: Non lo so. Restaurare carta. Restaurare me. Magari restaurare noi.","@stat:legame+1","@stat:fiducia+1"]}]}]},"varano_c6":{"npc":"varano","first":["varano: Avete ascoltato il nastro. Lo vedo dalle vostre facce.","varano[sad]: Mio padre ha falsificato quel verbale. Io l'ho scoperto nel 1999, il giorno del suo funerale. Ho trovato una copia del nastro nella sua cassaforte. Quella, laggiù.","varano: L'ho distrutta. Non sapevo che Jacques Marchetti ne avesse un'altra."],"intro":[{"if":"flag.varano_c6_fine","do":["varano: Ancora qui? Le catacombe sono a sinistra, uscendo."]},{"do":["varano: Chiedete pure. Stanotte non ho più niente da nascondere. O quasi."]}],"byeLabel":"«Ci vediamo nella Camera, Varano.»","topics":[{"id":"bruno","label":"Suo nonno, Bruno","icon":"person","once":true,"do":["varano: Bruno Varano. Nel 1944 vendeva nomi ai tedeschi. Tre famiglie del Ghetto, un tipografo, due partigiani dell'Oltrarno.","varano: È nel Registro. In una colonna a parte. La colonna dei delatori.","varano[sad]: Mio padre ha cancellato il Ponte perché il Registro non uscisse mai. Per proteggere il nome di suo padre. Il mio nome.","@flag:varano_past","@clue:bruno_varano","@stat:conoscenza+1"]},{"id":"lina","label":"Sua nonna, Lina","icon":"heart","if":"col.doc_17 || clue.lina","once":true,"do":["varano[surprised]: Avete letto la lettera.","varano: Lina Varano. La moglie di Bruno. Nello stesso anno, nella stessa casa, nascondeva in cantina quelli che lui denunciava. Ne ha salvati trenta.","varano: È nel Registro anche lei. Nella colonna dei Barcaioli.","beps: Allora il Registro non accusa solo. Salva anche.","varano[sad]: …Il Registro dice la verità, Giuseppe. E la verità sulla mia famiglia è che siamo stati entrambe le cose.","@flag:varano_doubt","@clue:lina_varano","@stat:conoscenza+1","@stat:fiducia+1"]},{"id":"verbale","label":"Il verbale falsificato","icon":"warning","if":"clue.verbale_falso","once":true,"do":["varano: Quindici favorevoli, due contrari. Mio padre scrisse «unanimità». Euridice e il Ponte, «assenti».","varano: Guido Sarti morì l'anno dopo, in un incidente stradale. Nessuno ha mai indagato.","kiki[angry]: Sta dicendo che…","varano: Sto dicendo che non lo so. E che non voglio saperlo. È questo il problema della mia famiglia: non vogliamo sapere.","@stat:conoscenza+1"]},{"id":"camera","label":"La Camera di Orfeo","icon":"key","once":true,"do":["varano: Sotto la stanza murata, a Firenze. Lo sapete già: ve l'hanno detto gli anelli.","varano: Il meccanismo si apre solo in due. Chi lo costruì lo volle così: nessuno doveva poter decidere da solo del Registro.","varano[sad]: Io non ho mai avuto nessuno con cui aprirla. Per questo vi ho seguito. Per questo vi ho lasciato il Sigillo.","beps: Vuole che la apriamo noi. Per poi bruciare il Registro.","varano: Voglio che decidiate voi. E poi, sì, lo brucerò. Se me lo lascerete fare.","@clue:camera_due","@stat:conoscenza+1"]},{"id":"perche","label":"Perché ci ha aiutato?","icon":"question","if":"flag.varano_doubt","once":true,"do":["varano[sad]: Perché da quarant'anni porto in tasca una scatola di fiammiferi e non ho mai acceso il primo.","varano: Forse aspettavo qualcuno che mi convincesse a non farlo. O a farlo. Qualcuno, comunque.","kiki[worried]: Non siamo qui per convincerla.","varano: Lo so. È per questo che vi ascolto."]}],"items":{"lista17":["varano: XI. Bruno, Ettore, Aurelio. Una riga sola per tre uomini e due bugie."],"foto1944":["varano[sad]: Il volto graffiato è Guido Sarti, il primo Ponte. Mio padre lo graffiò nel '67 con un ago da cucito. Me l'ha raccontato quando avevo sei anni, come una favola."],"sigillo":["varano: Lo tenga. È più al sicuro con lei che con me."],"*":["varano: No."]},"bye":["varano: Ci vediamo nella Camera. Passate dalle catacombe: i miei uomini sorvegliano le stazioni, ma non sanno camminare tra i morti.","@flag:varano_c6_fine","@objective:o6_catacombe"]},"c6_fine":{"linear":true,"intro":["kiki: Il treno della notte parte alle 22:40. Domattina saremo a Firenze.","beps: Nella stanza murata. Dove è cominciato tutto.",{"if":"flag.bacio","do":["kiki[tender]: Dove ci siamo conosciuti, Beps. Dove è cominciato tutto, davvero."],"else":["kiki[smile]: Dove mi hai guardata come se fossi un fantasma."]},"@cutscene:c6_fine","@chapter:7","@goto:c7_cantiere"]},"apertura":{"linear":true,"intro":["@anim:use","@sfx:mechanism","beps: La Chiave chiude.","kiki: E nessuno resta solo.","narr: La chiave gira. Dall'altra parte, la leva scende con Kiki attaccata. Un rumore immenso attraversa la Camera: ingranaggi, contrappesi, acqua. Dal fondo dell'abisso sale un ponte di pietra che unisce le due piattaforme.","narr: Al centro, uno scrigno si apre.","@flag:meccanismo_aperto","@unflag:kiki_tiene","@together:true",{"if":"!flag.final_errors && !flag.hints_c7 && perr.c7_registro==0","do":["@flag:final_perfect"]},"@refresh","kiki[surprised]: Il Registro.","@objective:o7_registro"]},"varano_arriva":{"linear":true,"intro":["narr: Passi sulla scala. Una torcia. Il Notaio entra nella Camera, si ferma sul ponte di pietra appena emerso.","varano: Ce l'avete fatta. In due.","varano[sad]: Io ci ho provato per vent'anni, da solo. Il meccanismo non si è mai mosso.","beps: È per questo che l'hanno costruito così.","varano: Lo so. Lo so, adesso.","varano: Uscite. Vi aspetto sul Lungarno. All'alba. Decideremo lì. All'aperto, davanti al fiume. Mi sembra giusto.","@cutscene:c7_uscita","@goto:c7_alba"]},"varano_finale":{"npc":"varano","first":["varano: Allora. Il Registro. Avete deciso?"],"intro":["varano: Prendetevi il tempo che serve. Io ho aspettato quarant'anni."],"byeLabel":"«Abbiamo deciso.»","topics":[{"id":"luce","label":"Se lo rendessimo pubblico?","icon":"doc","once":true,"do":["varano: La Luce. Il Ponte voleva questo, nel '44. I nomi di chi ha salvato, finalmente ricordati. I nomi di chi ha venduto, finalmente scritti.","varano[sad]: Anche quello di mio nonno. Anche quello di mia nonna, accanto.",{"if":"flag.varano_doubt","do":["varano: …Sapete una cosa? Se lo fate, testimonierò. Racconterò del verbale. Di mio padre. È l'unico modo di essere un Varano diverso."],"else":["varano: Se lo fate, non potrò impedirvelo. Ma non mi chiedete di esserne felice."]}]},{"id":"custodi","label":"Se lo custodissimo noi?","icon":"us","once":true,"do":["varano: I Custodi. Orfeo rinasce. Euridice, il Ponte. Voi due.","varano: Il Registro resta segreto, ma non sepolto. E un giorno, quando sarà il momento, lo aprirete.","varano[think]: È la scelta più lenta. Non è detto che sia la più sbagliata."]},{"id":"cenere","label":"E se lo bruciassimo?","icon":"warning","once":true,"do":["varano: Cenere. Nessuno accusato, nessuno ricordato. La ferita si chiude.","kiki[sad]: Chiusa sopra trenta persone salvate da sua nonna. Sopra mia bisnonna. Sopra Guido Sarti.","varano[sad]: Sì. Anche sopra di loro. È questo il prezzo della cenere."]},{"id":"noi","label":"Noi due","icon":"us","special":true,"if":"flag.knows_18","once":true,"do":["kiki[tender]: Varano. Sul retro della lista c'è un numero. XVIII. Uno spazio largo il doppio.","varano[surprised]: Il diciottesimo. Ada ne parlava come di una favola. «Un giorno, un ruolo per due.»","varano: Se è lì… allora qualcuno ha previsto che il Registro non dovesse più scegliere tra luce e cenere. Ma tra soli e insieme.","@flag:diciottesimo_parlato"]}],"bye":["@ending"]},"partner_kiki":{"npc":"kiki","intro":[{"if":"chapter>=5 && stat.legame>=14","do":["kiki[tender]: Dimmi, informatico."]},{"if":"chapter>=3","do":["kiki[smile]: Sì?"]},{"do":["kiki: Sì?"]}],"byeLabel":"Niente, andiamo","topics":[{"id":"c1_foto","label":"La tua fotografia","icon":"photo","if":"chapter==1","once":true,"do":["kiki: Identica alla tua. Stessa carta, stesso taglio, stesso volto graffiato.","kiki[sad]: Nonna la teneva nel messale. Non andava a messa da quarant'anni, ma il messale lo apriva tutte le sere.","@clue:foto_kiki"]},{"id":"c1_voce","label":"Ascolta NON_APRIRE.wav","icon":"tape","if":"chapter==1 && item.usb","once":true,"do":["narr: Beps le passa un auricolare. Il file parte.","narr: «Se qualcuno sta ascoltando questo messaggio, significa che abbiamo fallito.»","kiki[surprised]: …","kiki[sad]: È nonna. È la voce di mia nonna. Ada.","@flag:kiki_nonna","@clue:voce_ada",{"choice":[{"label":"«Mi dispiace. Vuoi che lo spenga?»","tone":"tender","do":["kiki[tender]: No. Lascialo andare. Non sentivo la sua voce da sette anni.","@stat:legame+1"]},{"label":"«Tua nonna era in Orfeo?»","do":["kiki[think]: A quanto pare. E non me l'ha mai detto. Nemmeno alla fine.","@stat:conoscenza+1"]},{"label":"Restale accanto in silenzio","line":"beps[tender]: …","do":["kiki[sad]: …Grazie.","@stat:legame+1","@stat:fiducia+1"]}]}]},{"id":"c1_medaglione","label":"Il medaglione","icon":"symbol","if":"chapter==1 && item.medaglione_b && !flag.got_medaglione_k","once":true,"do":[{"if":"stat.fiducia>=1","do":["kiki[surprised]: Hai l'altra metà. Lo sapevo.","kiki: Tieni. La mia. Nonna diceva che era «con qualcuno di testardo». Proviamo.","@give:medaglione_k"],"else":["kiki[skeptical]: Prima dimmi dove l'hai trovata.",{"choice":[{"label":"«In una crepa della stanza murata. Te lo giuro.»","do":["kiki: Ti credo. Tieni la mia metà. Proviamo.","@stat:fiducia+1","@give:medaglione_k"]},{"label":"«In un mercatino. Due euro.»","do":["kiki[skeptical]: Bugiardo. Ma te la do lo stesso: da sola non serve a niente.","@stat:fiducia-1","@give:medaglione_k"]}]}]},"@objective:o1_medaglione"]},{"id":"c1_chi","label":"Chi sei, davvero?","icon":"person","if":"chapter==1","once":true,"do":["kiki: Federica Morel. Restauratrice di carta, storica d'archivio, metà fiorentina e metà parigina. Diciamo tre quarti fiorentina, quando piove.","kiki[smile]: Mi chiamano Kiki da quando avevo tre anni e non sapevo dire Federica.","kiki: E tu, informatico? Cosa ci fa uno come te in un archivio di notte?","beps: Dieci minuti di lavoro. È una lunga storia.","@stat:fiducia+1"]},{"id":"c1_buio","label":"L'uomo nel buio","icon":"warning","if":"chapter==1 && clue.voce_buio","once":true,"do":["kiki[worried]: Conosceva il deposito. Sapeva dov'era l'interruttore. E ha detto «Orfeo» come si dice il nome di un parente.","kiki: Non era una minaccia. Era peggio: era un consiglio sincero."]},{"id":"c1_adesso","label":"E adesso?","icon":"map","special":true,"if":"chapter==1 && flag.pdf_open && item.medaglione","do":["beps: Quattro nomi, una busta per Parigi, un medaglione intero e un uomo col cappotto grigio che sa come ci chiamiamo.","kiki: Lo Studio Marchetti esiste ancora. Rue des Archives. La figlia del fotografo era un'amica di nonna.",{"choice":[{"label":"«Andiamo a Parigi. Insieme.»","do":["kiki[smile]: «Insieme.» Detto da uno sconosciuto conosciuto tre ore fa.","@stat:legame+1","@inc:coop"]},{"label":"«Vado io. Tu resta al sicuro.»","do":["kiki[angry]: Al sicuro? La voce è di mia nonna, Beps. Il treno lo prendo io. Tu, se vuoi, vieni.","@stat:fiducia-1"]},{"label":"«Prima dimmi tutto quello che sai.»","do":["kiki[think]: Giusto. Nonna era nata a Parigi, viveva tra qui e là. Non parlava mai del '67. Mai. Ecco tutto quello che so.","@stat:conoscenza+1","@stat:fiducia+1"]}]},"kiki: Domani c'è un treno alle sette e dodici. Non fare tardi.","beps[smile]: Io non faccio mai tardi. Arrivo con un margine creativo.","@cutscene:c1_fine","@chapter:2","@goto:c2_gare"],"end":true,"repeatSafe":true},{"id":"c1_adesso_presto","label":"E adesso?","icon":"map","if":"chapter==1 && !(flag.pdf_open && item.medaglione)","do":[{"if":"!flag.pdf_open","do":["kiki: Adesso apriamo quel PDF. Il mio portatile è sul tavolo: dammi la chiavetta."]},{"if":"!item.medaglione","do":["kiki: E quelle due metà di medaglione aspettano solo di essere riunite."]}]},{"id":"c2_parigi","label":"Parigi","icon":"city","if":"chapter==2","once":true,"do":["kiki: Ci sono cresciuta d'estate. Nonna mi portava ai quais, al Louvre il primo sabato del mese, e al cinema a vedere film in bianco e nero che non capivo.","kiki[smile]: Ora li capisco. Erano tutti su persone che si perdono e si ritrovano.","@stat:legame+1"]},{"id":"c2_helene","label":"Hélène Marchetti","icon":"person","if":"chapter==2 && flag.helene_met","once":true,"do":["kiki: Era la migliore amica di nonna. Più giovane di vent'anni. Litigavano su tutto, tranne che sulle cose importanti.","kiki[think]: Ha detto «allora è cominciato». Sa più di quanto dica."]},{"id":"c2_mappa","label":"Che ne pensi della mappa?","icon":"map","if":"chapter==2 && item.mappa && !puzzle.c2_mappa","once":true,"do":["kiki: Lettere in cerchio, una stella rossa. E un medaglione con dieci fori. Si appoggia il medaglione e si gira finché i fori non dicono qualcosa.","kiki: La tacca del medaglione deve servire a orientarlo. Su cosa, però?"]},{"id":"c3_roma","label":"Roma","icon":"city","if":"chapter==3","once":true,"do":["kiki: Roma mi mette soggezione. Troppa storia per metro quadro.","beps: Per uno curioso come me è il paradiso. Ogni muro ha tre muri sotto.","kiki[smile]: Come le persone."]},{"id":"c3_latino","label":"Dove hai imparato il latino?","icon":"doc","if":"chapter==3 && flag.targa_tradotta","once":true,"do":["kiki: Liceo classico a Firenze, poi paleografia a Parigi. E nonna, che mi leggeva Ovidio al posto delle favole.","kiki[laugh]: «Le Metamorfosi» a sei anni. Ho avuto paura degli alberi per un decennio.","@stat:legame+1"]},{"id":"c3_federica","label":"Perché non ti fai chiamare Federica?","icon":"question","if":"chapter==3 && flag.fuga_ok","once":true,"do":["kiki[think]: Perché Federica è il nome con cui mi chiama chi non mi conosce. Le banche, i dottori, i professori.","kiki: Se un giorno firmo «Federica» con te, Beps, vuol dire che qualcosa non va. Ricordatelo.","@stat:fiducia+2","@flag:segnale_federica"]},{"id":"c4_scusa","label":"Mi hai fatto paura","icon":"heart","if":"chapter==4 && flag.kiki_liberata","once":true,"do":["kiki[tender]: Lo so. Anch'io ho avuto paura. Non di lui. Di non vederti arrivare.","@stat:legame+1"]},{"id":"c5_istanbul","label":"Istanbul","icon":"city","if":"chapter==5","once":true,"do":["kiki: Nonna diceva che Istanbul è una città che ti guarda mentre la guardi.","beps: Lo dice anche il gabbiano lì.","kiki[laugh]: Smettila con i gabbiani."]},{"id":"c6_helene","label":"Hélène è Euridice","icon":"person","if":"chapter==6 && flag.helene_euridice","once":true,"do":["kiki[sad]: Avrei dovuto capirlo. Il cappello, le domande, il «non ancora».","kiki: E adesso c'è una terza donna. Quella di Istanbul. Nonna, quanti segreti avevi?","@stat:conoscenza+1"]},{"id":"c6_varano","label":"Che pensi di Varano?","icon":"warning","if":"chapter==6 && flag.varano_c6_fine","once":true,"do":["kiki: Penso che sia un uomo che ha ereditato una colpa e la porta come un cappotto. Grigio, naturalmente.","kiki[sad]: E penso che, se non lo fermiamo, brucerà anche i nomi di chi ha salvato sua nonna. Per non vedere quelli di suo nonno."]},{"id":"c7_paura","label":"Hai paura?","icon":"heart","if":"chapter==7","once":true,"do":["kiki: Sì. Tu?","beps: Da morire.","kiki[smile]: Bene. Allora siamo pronti."]},{"id":"noi","label":"Noi due","icon":"us","special":true,"if":"chapter>=5 && !topic.partner_kiki.noi","do":["beps: Kiki. Noi due.","kiki[tender]: Noi due.",{"if":"flag.bacio","do":["kiki: Non pensavo che un uomo che parla di Wi-Fi durante un tramonto potesse piacermi.","beps: Cinque tacche. Il segnale aveva cinque tacche.","kiki[laugh]: Appunto."],"else":["kiki: Mi hai preso la mano, sul tetto. Non me l'hai più lasciata. Te ne sei accorto?","beps: Me ne sono accorto."]},{"choice":[{"label":"«Quando sarà finito, voglio che ci sia ancora un noi.»","tone":"tender","do":["kiki[tender]: Ci sarà. Te lo prometto. Io le promesse le restauro, non le rompo.","@stat:legame+2","@inc:coop"]},{"label":"«Tua nonna aveva previsto anche questo?»","do":["kiki[laugh]: «Qualcuno di testardo.» Sì. Credo proprio di sì.","@stat:legame+1","@stat:fiducia+1"]},{"label":"«Ho paura di sbagliare tutto.»","do":["kiki[tender]: Sbaglieremo tutto. Insieme. Mi sembra un buon piano.","@stat:fiducia+2"]}]}]},{"id":"noi_ancora","label":"Noi due","icon":"us","special":true,"if":"chapter>=5 && topic.partner_kiki.noi","do":[{"if":"flag.bacio","do":["kiki[tender]: Ancora tu? Vieni qui.","narr: Un bacio rapido, a metà di un'avventura."]},{"do":["kiki[tender]: Ci sono. Sempre."]}]},{"id":"suggerimento","label":"Tu cosa faresti adesso?","icon":"question","do":[{"if":"true","do":["kiki[think]: Io? Rileggerei il taccuino. L'obiettivo è lì, e i dettagli di solito sono negli indizi."]}]}],"items":{"foto1944":["kiki: La nostra foto. Ce l'abbiamo in due. Credo sia il motivo per cui siamo qui."],"medaglione_b":[{"if":"!flag.got_medaglione_k","do":["kiki[surprised]: L'altra metà. Tienila: te la do io la mia, con calma. Chiedimelo."]},{"do":["kiki: Uniscile, Beps. Cosa aspetti?"]}],"medaglione":["kiki[tender]: Intero. Nonna non l'ha mai visto intero."],"moneta":["kiki: Le tue 500 lire. Le stesse della donna col cappello. Coincidenze, eh?"],"lettera_ada":["kiki[sad]: Tienila tu. Te l'ho detto. Io la perderei apposta."],"registro":["kiki: Ottant'anni di nomi. Tra cui il mio, un giorno, forse."],"*":["kiki[skeptical]: Che dovrei farci, con questo?"]}},"partner_beps":{"npc":"beps","intro":[{"if":"chapter>=5 && stat.legame>=14","do":["beps[smile]: Signorina restauratrice."]},{"do":["beps: Dimmi."]}],"byeLabel":"Niente, andiamo","topics":[{"id":"chi","label":"Perché fai l'informatico?","icon":"person","once":true,"do":["beps: Da bambino smontavo tutto: radio, telefoni, il tostapane di mia nonna. Volevo capire cosa c'era dentro.","beps[smile]: Poi ho scoperto che i computer sono uguali, ma non prendono fuoco. Quasi mai.","@stat:fiducia+1 quiet"]},{"id":"studio","label":"Il tuo ufficio","icon":"city","if":"chapter>=4","once":true,"do":["beps[sad]: L'hanno distrutto per dirmi qualcosa. La mia scrivania, la rimetterò a posto. I cavi, li ricollegherò. Il computer… era loro, in fondo.","beps: Quello che non potevano prendermi l'avevo già portato via. Te, per esempio. Cioè. La chiavetta. Volevo dire la chiavetta."]},{"id":"paura","label":"Hai paura?","icon":"heart","if":"chapter==7","once":true,"do":["beps: Sì. Tu?","kiki: Da morire.","beps[smile]: Bene. Allora siamo pronti."]},{"id":"noi","label":"Noi due","icon":"us","special":true,"if":"chapter>=5","once":true,"do":["kiki: Beps. Noi due.","beps[tender]: Noi due. Mi piace come suona. Mi piace come lo dici.",{"choice":[{"label":"«Non sparire più per dieci minuti.»","do":["beps[tender]: Mai più. Nemmeno per un caffè.","@stat:legame+1","@stat:fiducia+1"]},{"label":"«Sei la persona più testarda che conosco.»","do":["beps[laugh]: Detto da te è un complimento enorme.","@stat:legame+1"]}]}]},{"id":"suggerimento","label":"Tu cosa faresti adesso?","icon":"question","do":["beps[think]: Guarderei bene le cose che ho in tasca. Spesso la soluzione è un oggetto che ci siamo dimenticati di usare."]}],"items":{"foto1944":["beps: La nostra foto. Ce l'abbiamo in due."],"lettera_ada":["beps: La tengo io, come mi hai chiesto. Non la perderò."],"*":["beps: Bello. Lo usiamo per qualcosa o è un regalo?"]}},"incontro_kiki":{"linear":true,"intro":["narr: Beps richiude il cassetto O. Una sedia si sposta, alle sue spalle.","kiki_npc: «Mi scusi… lei ha appena consultato il fascicolo Orfeo?»","beps[surprised]: Mi voltai. Non avevo mai visto quella donna prima di allora.","@show:kiki","@flag:met_kiki","@person:kiki","@refresh","kiki[skeptical]: «Perché quel fascicolo interessa anche a me.»",{"choice":[{"label":"«Chi è lei?»","do":["kiki: «Federica. Ma tutti mi chiamano Kiki.»","@flag:kiki_named"]},{"label":"«Dipende. Chi lo chiede?»","do":["kiki[smile]: «Qualcuno che ha una fotografia identica alla sua.»","kiki: Federica Morel. Kiki, per chi mi risponde a tono.","@flag:kiki_named","@stat:legame+1"]},{"label":"Non dire nulla","line":"beps: …","do":["kiki[think]: «Va bene. Allora comincio io: Parigi, 1967. Le dice qualcosa?»","beps: La scheda che ho in mano dice «Provenienza: Parigi, 1967».","kiki: Lo so. L'ho letta da sopra la sua spalla. Federica. Kiki.","@flag:kiki_named","@stat:conoscenza+1"]}]},"narr: Kiki appoggia sul tavolo una fotografia. Quattro uomini, un palazzo, una donna col cappello, un volto graffiato.","beps[surprised]: È identica alla mia.","kiki: Lo so. Ripiano 17, giusto? Io ho la tessera per il deposito. Lei no. Venga con me, informatico.",{"choice":[{"label":"«Perché dovrei fidarmi di lei?»","do":["kiki[skeptical]: Non deve. Ma io la sto portando nel deposito, non il contrario. Chi rischia di più?","@stat:conoscenza+1"]},{"label":"«Andiamo.»","do":["kiki[smile]: Bene. Mi piacciono le persone che non fanno domande inutili.","@stat:fiducia+1","@inc:coop"]}]},"@flag:deposito_ok","archivista: Dieci minuti, signorina Morel. Dieci. E il giovanotto non tocca niente.","@objective:o1_deposito"]},"c5_fine":{"linear":true,"intro":["@sfx:phone","kiki: È Hélène.","@anim:phone","helene: Federica. Varano è a Parigi. Vuole vedervi. E io… io devo dirvi una cosa che avrei dovuto dirvi a novembre.","kiki[worried]: Hélène?","helene: Venite a Parigi. Portate il nastro.","selim: Andate. Il traghetto per l'aeroporto parte tra un'ora. E ricordatevi: chi entra in due, esce in due.","@cutscene:c5_fine","@chapter:6","@goto:c6_pont_neuf"]},"diciottesimo":{"linear":true,"intro":["@sfx:clue","@flag:knows_18","@clue:diciottesimo","narr: Sette lire, sette parole. Messe in fila, dicono una frase sola:","narr: «Il diciottesimo nome appartiene a chi non si volta da solo.»",{"if":"present.kiki && present.beps","do":["kiki[surprised]: Il diciottesimo? I ruoli sono diciassette.","beps[think]: Sulla Lista, sul retro… guarda. Un XVIII a matita. Uno spazio largo il doppio."],"else":["Il diciottesimo? I ruoli sono diciassette. Eppure, sul retro della Lista, c'è un XVIII a matita."]}]},"c4_fine":{"linear":true,"intro":["kiki: Andiamo. Istanbul ci aspetta.","@cutscene:c4_fine","@chapter:5","@goto:c5_galata"]}}},"items":{"_doc":"Oggetti. icon = icona procedurale di riserva; l'immagine reale va in assets/items/<id>.png. examine: testo (o script) per personaggio. combos: oggetto+oggetto (ordine indifferente). notYet: risposta se la combinazione esiste ma non è ancora possibile.","items":{"usb":{"name":"Chiavetta USB","kind":"Copia della cartella ORFEO","icon":{"k":"usb"},"examine":{"beps":"La mia chiavetta. Dentro, tre file: FIRENZE_1944.jpg, LISTA_17.pdf, NON_APRIRE.wav. Il PDF è cifrato.","kiki":"La chiavetta di Beps. Dentro c'è la voce di mia nonna. Non riesco a smettere di pensarci."},"examineIf":[{"if":"flag.pdf_open","do":{"beps":"Il PDF ora è leggibile. Diciassette righe, quasi tutte corrotte. Quattro si leggono.","kiki":"LISTA_17. Quattro nomi leggibili, tredici mangiati dai bit. Come muffa digitale."}}],"wrong":{"beps":"Non vedo una porta USB. Siamo in un'avventura, non in un ufficio.","kiki":"Non tutto ha una porta USB, Beps."}},"foto1944":{"name":"Foto 1944","kind":"Stampa da FIRENZE_1944.jpg","icon":{"k":"photo","c":"#8a7454"},"examine":{"beps":["Quattro uomini davanti a un palazzo. Una donna col cappello, un po' in disparte. Il terzo volto da sinistra è stato graffiato via, deliberatamente.","E negli angoli quattro piccole croci rosse. Come mirini."],"kiki":["Firenze, estate 1944. La donna col cappello porta un medaglione. Ce l'ho identica, questa foto. Nonna la teneva nel messale.","Le crocette agli angoli sono segni di registro. Si usano in tipografia per sovrapporre due lastre."]}},"caffe":{"name":"Caffè in bicchierino","kind":"Dalla macchinetta dell'ufficio","icon":{"k":"candle","c":"#5a3a20"},"examine":{"beps":"Caffè della macchinetta. Tecnicamente è caffè. Legalmente, non saprei.","kiki":"Ha un colore preoccupante."},"wrong":{"beps":"Non è il momento di sprecare caffè.","kiki":"No, questo caffè ha già sofferto abbastanza."}},"frammenti":{"name":"Frammenti di documento","kind":"Dalla stanza murata","icon":{"k":"fragment"},"examine":["Sei strisce di carta strappata, macchiate d'acqua. Se le ricompongo forse si legge qualcosa.","@puzzle:c1_frammenti"]},"promemoria":{"name":"Promemoria 1966","kind":"Documento ricomposto","icon":{"k":"letter"},"examine":{"beps":"«Murate la stanza e portate le copie a Parigi. Chi cerca il resto segua la catena del catalogo: si parte dalla scheda O-1.» Firmato: E.","kiki":"Carta del '66, inchiostro ferrogallico. Chi l'ha scritto aveva le mani bagnate: si vede dalle sbavature."}},"medaglione_b":{"name":"Mezzo medaglione","kind":"Trovato in una crepa del muro","icon":{"k":"medal_l"},"examine":{"beps":"Metà di un medaglione d'ottone. Il bordo spezzato è netto, come se l'avessero diviso apposta. C'è mezza lira incisa.","kiki":"La metà di Beps. Il taglio combacia con la mia, lo vedo da qui."}},"medaglione_k":{"name":"Mezzo medaglione di Kiki","kind":"Eredità di nonna Ada","icon":{"k":"medal_r"},"examine":{"beps":"La metà di Kiki. Me l'ha data come si dà una cosa che non si vuole perdere.","kiki":"Nonna la portava sempre. Diceva che l'altra metà era «da qualche parte, con qualcuno di testardo»."}},"medaglione":{"name":"Medaglione","kind":"Le due metà riunite","icon":{"k":"medal"},"examine":{"beps":["Le due metà combaciano. Una lira, una piccola tacca sul bordo, e dieci forellini disposti a spirale.","Sembra fatto per stare sopra qualcosa. Una mappa, magari."],"kiki":["Intero. Nonna non l'ha mai visto intero.","Una tacca sul bordo e dieci fori. È uno strumento, non un gioiello."]},"examineIf":[{"if":"chapter>=5","do":{"beps":["Sul retro, ora che lo guardo con questa luce, ci sono quattro simboli in fila, dal centro verso il bordo: luna, lira, onda, chiave.","@clue:retro_medaglione"],"kiki":["Sul retro ci sono quattro simboli incisi, dal centro al bordo: luna, lira, onda, chiave. Come una formula.","@clue:retro_medaglione"]}}]},"scheda_o17":{"name":"Scheda O-17","kind":"Catalogo dell'Archivio Storico","icon":{"k":"card"},"examine":{"beps":["«O-17 · Fondo Orfeo · Provenienza: Parigi, 1967. Collocazione: deposito, ripiano 17.»","Sul retro, a matita: «La chiave è il giorno in cui l'acqua arrivò al terzo gradino.»"],"kiki":["Una scheda del catalogo O, quello che ufficialmente non esiste. Provenienza: Parigi, 1967.","Sul retro: «La chiave è il giorno in cui l'acqua arrivò al terzo gradino.» L'alluvione, ovviamente."]}},"busta_e":{"name":"Busta di Euridice","kind":"Dal ripiano 17","icon":{"k":"envelope"},"examine":{"beps":"Una busta del 1967 con un timbro: «Studio Marchetti — 12, rue des Archives, Paris». Vuota, a parte una lira disegnata a matita.","kiki":"Rue des Archives. Nonna abitava a due strade da lì. Questo non è un caso."}},"moneta":{"name":"500 lire","kind":"Il portafortuna di Beps","icon":{"k":"coin"},"examine":{"beps":"Le 500 lire bimetalliche di mio nonno. Non valgono niente. Valgono tutto.","kiki":"Le porta in tasca da sempre. Gliel'ho visto toccare tre volte oggi."},"wrong":{"beps":"No, le 500 lire non le spendo così.","kiki":"Non credo che le sue 500 lire servano qui."}},"coltellino":{"name":"Coltellino multiuso","kind":"Attrezzatura da cantiere","icon":{"k":"pen","c":"#8a1a1a"},"examine":{"beps":"Lama, cacciavite, metro, apribottiglie. Un informatico serio gira sempre con un cacciavite. E un apribottiglie, per i casi gravi.","kiki":"Ha un metro dentro il coltellino. Certo che ce l'ha."},"wrong":{"beps":"Il coltellino non risolve tutto. Quasi tutto.","kiki":"Metti via quel coltellino, MacGyver."}},"libretto":{"name":"Libretto «Orphée et Eurydice»","kind":"Dal banco di Monsieur Albert","icon":{"k":"book"},"examine":["Il libretto dell'opera di Gluck, Parigi 1774. Edizione del 1960. Tra le pagine c'è una carta ripiegata…","@take:libretto","@give:mappa","@clue:mappa_cifrata"]},"mappa":{"name":"Mappa cifrata","kind":"Carta d'Italia con una stella rossa","icon":{"k":"map"},"examine":{"beps":"Una carta d'Italia del 1960 piena di lettere minuscole stampate in cerchio, come un rosone. Una stella rossa a nord-est del centro. Il cerchio ha la misura esatta del medaglione.","kiki":"Le lettere sono disposte attorno a un punto. Se ci appoggi sopra qualcosa con dei fori… sì. È una griglia di Cardano, più o meno."}},"foto1967":{"name":"Foto 1967","kind":"Stampa dai negativi Marchetti","icon":{"k":"photo","c":"#5d6668"},"examine":{"beps":["Parigi, 1967. Tre uomini, un'auto, una facciata. E lei: la donna col cappello. Nello stesso identico punto della foto del '44.","Anche qui, quattro crocette rosse negli angoli."],"kiki":["Questa è nonna. Ada, a trentun anni. Ha il cappello di quella del '44. E il medaglione.","Crocini di registro agli angoli. Le due foto sono fatte per essere sovrapposte."]},"examineIf":[{"if":"flag.retro_1967","do":{"beps":"Sul retro, sviluppata dal negativo, la scritta: «La stella guida la tacca».","kiki":"«La stella guida la tacca.» Calligrafia di nonna."}}]},"negativo":{"name":"Negativo 1967","kind":"Striscia di pellicola","icon":{"k":"negative"},"examine":{"beps":"Una striscia di negativi. Controluce si vede del testo, ma al contrario. Servirebbe un ingranditore.","kiki":"Negativo in bianco e nero, probabilmente Ilford. Va stampato, non guardato."}},"lettera_ada":{"name":"Lettera di Ada","kind":"«Per Federica, quando sarà il momento»","icon":{"k":"letter"},"examine":{"beps":"Non è mia da leggere. La tengo io solo perché Kiki me l'ha chiesto. Le mani le tremavano.","kiki":["«Federica, se leggi questo hai trovato l'altra metà. Non avere paura di chi la porta: io mi sono fidata una volta sola, ed era la persona giusta.»","«Non voltarti indietro. È l'unica regola. — Nonna»"]}},"chiave_ottone":{"name":"Chiave d'ottone","kind":"Dal cassetto della Teodosiana","icon":{"k":"key"},"examine":{"beps":"Una chiave d'ottone col numero 17 punzonato sull'impugnatura. Pesante, fatta per durare.","kiki":"Ha un'etichetta minuscola: «B.d.G.». Banca del Giglio? A Firenze c'è una sede storica."}},"lista17":{"name":"Lista dei 17","kind":"Il registro dei ruoli di Orfeo","icon":{"k":"list"},"examine":{"beps":["Diciassette ruoli, con i nomi di chi li ha custoditi dal 1944 a oggi. Il diciassettesimo è stato raschiato via col temperino.","@flag:lista_full","@flag:lista_seen"],"kiki":["Diciassette ruoli, diciassette successioni. Il XVII è stato cancellato. Non strappato: raschiato. Qualcuno ci ha messo tempo.","@flag:lista_full","@flag:lista_seen"]},"examineIf":[{"if":"flag.knows_18","do":{"beps":"E sul retro, a matita, un numero che prima non c'era: XVIII. Uno spazio largo il doppio.","kiki":"XVIII. Uno spazio per due nomi, non per uno. Nonna, che cosa avevi in mente?"}}]},"sigillo_a":{"name":"Frammento del Sigillo (Roma)","kind":"Un quarto di sigillo in ceralacca e bronzo","icon":{"k":"seal_piece"},"examine":{"beps":"Un quarto di cerchio di bronzo rosso. Sul bordo, inciso: ORFEO.","kiki":"Un quarto di sigillo. Sul bordo leggo «ORFEO». Mancano tre pezzi."}},"sigillo_b":{"name":"Frammento del Sigillo (Banca)","kind":"Dalla cassetta 17","icon":{"k":"seal_piece"},"examine":{"beps":"Un altro quarto. Sul bordo: NON.","kiki":"«NON». Un quarto che dice di no."}},"sigillo_c":{"name":"Frammento del Sigillo (Cantiere)","kind":"Recuperato da Sandro","icon":{"k":"seal_piece"},"examine":{"beps":"Questo era nel muro della stanza murata. Sul bordo: VOL.","kiki":"«VOL». Volare? Voltare?"}},"sigillo_d":{"name":"Frammento del Sigillo (Ponte Vecchio)","kind":"Custodito da Mastro Neri","icon":{"k":"seal_piece"},"examine":{"beps":"L'ultimo quarto. Sul bordo: TARTI.","kiki":"«TARTI». Non voltarti. Ovvio."}},"sigillo":{"name":"Sigillo di Orfeo","kind":"Ricomposto sul banco di Mastro Neri","icon":{"k":"seal"},"examine":{"beps":"Il Sigillo intero. Sul bordo: ORFEO · NON · VOLTARTI. Al centro la lira. Pesa più di quanto dovrebbe.","kiki":"«Orfeo, non voltarti.» Il patto del mito. Se ti volti a guardare, perdi chi ami."}},"nastro":{"name":"Nastro ORFEO","kind":"Bobina magnetica, 1967","icon":{"k":"tape"},"examine":{"beps":"Una bobina da registratore a nastro. Sull'etichetta: «ORFEO — Parigi, 12.III.1967 — Seduta straordinaria».","kiki":"Nastro da un quarto di pollice. Serve un Revox o un Nagra. A Parigi, nello studio di Hélène, ce n'era uno."}},"lanterna":{"name":"Lanterna","kind":"Prestata da Selim","icon":{"k":"torch"},"examine":{"beps":"Una lanterna a olio vecchia di un secolo. Selim dice che «vede meglio delle torce elettriche». Non ho capito se è una metafora.","kiki":"Fa una luce calda. Mi piace di più dei telefoni."}},"piede_porco":{"name":"Piede di porco","kind":"Prestato da Emre","icon":{"k":"crowbar"},"examine":{"beps":"Un piede di porco. Lo strumento di supporto tecnico più antico del mondo.","kiki":"Emre ce l'ha prestato senza fare domande. Questo dovrebbe preoccuparmi."}},"registro":{"name":"Il Registro di Orfeo","kind":"1944–2026","icon":{"k":"book","c":"#2a1a12"},"examine":{"beps":"Ottant'anni di nomi. Chi ha nascosto, chi è stato nascosto, chi ha tradito. Pesa come un mattone. Pesa più di un mattone.","kiki":"Il Registro. Ci sono mia nonna, mia bisnonna, e accanto a loro centinaia di persone salvate. E i nomi di chi li ha venduti."}}},"combos":[{"a":"medaglione_b","b":"medaglione_k","do":["@take:medaglione_b,medaglione_k","@give:medaglione","@sfx:success","beps[surprised]: Combaciano. Perfettamente.",{"if":"present.kiki","do":["kiki[tender]: Nonna diceva che l'altra metà era con qualcuno di testardo.","beps[smile]: Testardo è una parola grossa. Diciamo perseverante.","@stat:legame+1"]},"@clue:medaglione_intero"]},{"a":"mappa","b":"medaglione","do":["@puzzle:c2_mappa"]},{"a":"foto1944","b":"foto1967","if":"scene=='c2_studio_marchetti'","do":["@puzzle:c2_sovrapposizione"],"notYet":{"beps":"Per sovrapporle mi servirebbe un piano luminoso.","kiki":"Serve un tavolo luminoso. Da Hélène ce n'è uno."}},{"a":"sigillo_a","b":"sigillo_b","if":"false","do":[],"notYet":{"beps":"Per ricomporlo servono tutti e quattro i frammenti e un banco da orafo.","kiki":"Servono tutti i pezzi. E mani da orafo."}},{"a":"sigillo_a","b":"sigillo_c","if":"false","do":[],"notYet":"Servono tutti e quattro i frammenti e un banco da orafo."},{"a":"sigillo_a","b":"sigillo_d","if":"false","do":[],"notYet":"Servono tutti e quattro i frammenti e un banco da orafo."},{"a":"sigillo_b","b":"sigillo_c","if":"false","do":[],"notYet":"Servono tutti e quattro i frammenti e un banco da orafo."},{"a":"sigillo_b","b":"sigillo_d","if":"false","do":[],"notYet":"Servono tutti e quattro i frammenti e un banco da orafo."},{"a":"sigillo_c","b":"sigillo_d","if":"false","do":[],"notYet":"Servono tutti e quattro i frammenti e un banco da orafo."},{"a":"frammenti","b":"scheda_o17","do":["Prima devo ricomporre i frammenti. Uno alla volta."]},{"a":"usb","b":"scheda_o17","do":{"beps":["La scheda dice che la chiave è il giorno in cui l'acqua arrivò al terzo gradino. Mi serve un computer per provarla.",{"if":"!clue.alluvione","do":["Il giorno dell'acqua… l'alluvione del '66. Ma che giorno, esattamente? Sul Lungarno c'è una targa."]}],"kiki":["Ci serve un computer. Il mio portatile, al caffè."]}},{"a":"nastro","b":"lista17","do":["Il nastro è del 1967, la lista arriva al 2026. Il nastro va ascoltato, non confrontato."]},{"a":"foto1944","b":"lista17","do":{"beps":["Il volto graffiato nella foto… e il nome raschiato nella lista. Stessa mano? Stessa paura.","@clue:cancellato"],"kiki":["Il volto graffiato e il ruolo raschiato. Hanno cancellato una persona due volte.","@clue:cancellato"]}}]},"puzzles":{"_doc":"Enigmi. type = modulo in src/puzzles/. hints = 3 livelli (leggero, specifico, quasi-soluzione). onSolve/onLeave = script. Ogni enigma si può lasciare e riprendere; lo stato è salvato.","puzzles":{"c1_frammenti":{"type":"fragments","chapter":1,"title":"Il documento strappato","pieces":[{"id":"f1","text":"ORFEO · PROMEMORIA RISERVATO — Firenze, 9 novembre 1966"},{"id":"f2","text":"L'acqua è arrivata fino al terzo gradino della stanza. I registri"},{"id":"f3","text":"si sono salvati, ma qui non sono più al sicuro. Murate la stanza"},{"id":"f4","text":"e portate le copie a Parigi. Chi cerca il resto segua la catena"},{"id":"f5","text":"del catalogo: si parte dalla scheda O-1 e si obbedisce sempre"},{"id":"f6","text":"al rimando in rosso. Il diciassettesimo sa il resto. — E."}],"solution":["f1","f2","f3","f4","f5","f6"],"initial":["f4","f1","f6","f3","f5","f2"],"successText":"Il promemoria è ricomposto.","hints":["Ogni striscia ha un bordo strappato in alto e in basso: due strisce vicine hanno bordi complementari. Anche le frasi devono continuare.","Il titolo con la data va per primo. Le frasi finiscono a metà: cerca la striscia che comincia con la parola mancante («I registri…» → «si sono salvati»).","L'ordine è: intestazione → «L'acqua è arrivata…» → «si sono salvati…» → «e portate le copie…» → «del catalogo…» → «al rimando in rosso…»."],"onSolve":["@take:frammenti","@give:promemoria","@clue:promemoria_1966","@stat:conoscenza+1","beps[think]: «Si parte dalla scheda O-1.» Un catalogo con la lettera O. All'Archivio Storico, qui accanto.","@objective:o1_archivio"]},"c1_catena":{"type":"chain","chapter":1,"title":"La catena O-17","cards":{"O-1":{"title":"Registro dei passaggi sull'Arno","author":"R. Ricci","year":"1944","red":"O-6"},"O-2":{"title":"Inventario delle chiavi","author":"O. Neri","year":"1944","red":"O-8"},"O-3":{"title":"Corrispondenza con Roma","author":"I. Cesti","year":"1952","red":"O-12"},"O-4":{"title":"Rubrica dei custodi","author":"J. Marchetti","year":"1967","red":"O-15"},"O-5":{"title":"Lasciapassare falsificati","author":"Il Tipografo","year":"1944","red":"O-9"},"O-6":{"title":"Fotografie del Lungarno","author":"J. Marchetti","year":"1944","red":"O-11"},"O-7":{"title":"Note mediche","author":"Il Medico","year":"1944","red":"O-13"},"O-8":{"title":"Chiavi del Corridoio","author":"O. Neri","year":"1945","red":"O-2"},"O-9":{"title":"Timbri e matrici","author":"Il Tipografo","year":"1945","red":"O-5"},"O-10":{"title":"Orari dei treni per Livorno","author":"Il Ferroviere","year":"1944","red":"O-14"},"O-11":{"title":"Carteggio Parigi","author":"J. Marchetti","year":"1967","smudged":true,"redText":"Vedi anche → O-?","note":"Il rimando in rosso è stato lavato via dall'acqua. Sotto, a matita: «vedi la scheda dello stesso autore, anno 1967»."},"O-12":{"title":"Lettere da Roma","author":"I. Cesti","year":"1958","red":"O-3"},"O-13":{"title":"Registro dei ricoveri","author":"Il Medico","year":"1945","red":"O-7"},"O-14":{"title":"Itinerario Livorno–Istanbul","author":"Il Ferroviere","year":"1944","red":"O-10"},"O-15":{"title":"Inventario dei sigilli","author":"Anonimo","year":"1967","smudged":true,"redText":"Vedi anche → O-1?","note":"Il secondo numero è macchiato. Sotto, a matita: «quanti erano i custodi»."},"O-16":{"title":"Verbali delle riunioni","author":"E. Varano","year":"1967","red":"O-4","note":"Firma del notaio Ettore Varano."},"O-17":{"title":"Fondo Orfeo — Provenienza Parigi 1967","author":"E.","year":"1967","note":"Collocazione: deposito, ripiano 17."}},"solution":["O-1","O-6","O-11","O-4","O-15","O-17"],"successText":"La catena porta a O-17.","hints":["Il promemoria dice: si parte da O-1 e si segue sempre il rimando in rosso. Alcune schede però sono state danneggiate dall'alluvione.","Dove il rosso è illeggibile c'è una nota a matita: su O-11 si cerca un'altra scheda dello stesso autore dello stesso anno; su O-15 il numero dei custodi.","O-1 → O-6 → O-11 → O-4 (J. Marchetti, 1967) → O-15 → O-17 (i custodi erano diciassette)."],"onSolve":["@give:scheda_o17","@clue:scheda_o17","@stat:conoscenza+1","@dialogue:incontro_kiki"]},"c2_sovrapposizione":{"type":"overlay","chapter":2,"title":"Le due fotografie","start":{"dx":70,"dy":-45,"rot":14,"sc":0.82},"successText":"I crocini coincidono. La lira è completa. E la donna è nello stesso punto.","hints":["Le crocette rosse agli angoli sono segni di registro: servono proprio a sovrapporre due immagini.","La foto del 1967 è ruotata, più piccola e spostata. Correggi prima la rotazione, poi la scala, infine trascinala.","Ruota di circa 14° verso sinistra (⟲ sette volte), ingrandisci di circa nove passi (+), poi sposta in basso a sinistra finché i crocini combaciano."],"onSolve":["kiki[surprised]: La lira. Metà incisa sulla foto del '44, metà su quella del '67. Insieme fanno il simbolo di Orfeo.","beps: E la donna. Stessa posizione, stesso cappello, stesso medaglione. A ventitré anni di distanza.","kiki: Non è la stessa donna, Beps. Nel '44 è la mia bisnonna Lucia. Nel '67 è nonna Ada. Le ho riconosciute dalle mani.","beps[think]: Allora la donna nelle fotografie non è una persona. È un posto. Un ruolo.","@clue:stessa_donna","@stat:conoscenza+2",{"if":"puzzle.c2_mappa","do":["@dialogue:c2_fine"],"else":[{"if":"item.mappa","do":["@objective:o2_mappa_usa"],"else":["@objective:o2_mappa"]}]}]},"c2_mappa":{"type":"dial","chapter":2,"title":"Il medaglione sulla mappa","positions":8,"start":0,"solution":3,"readings":["AINASODOET","NIDOTEASOA","SANTODIEOA","TEODOSIANA","DEOSATINAO","ETONDISAAO","OADIESTANO","ANOTIDESAO"],"successText":"TEODOSIANA.","hints":["La tacca sul bordo del medaglione serve a orientarlo. Sulla mappa c'è un solo segno evidente.","Sul retro della foto del 1967 c'è scritto: «La stella guida la tacca». Ruota finché la tacca punta la stella rossa.","La stella è a nord-est: tre scatti in senso orario dalla posizione iniziale. Si legge TEODOSIANA."],"onSolve":["beps: TEODOSIANA. Una parola che esiste.","kiki: La Biblioteca Teodosiana. A Roma. Ci ho fatto un tirocinio, due anni fa. Il bibliotecario ha novant'anni e cita i Pink Floyd.","@take:mappa","@clue:teodosiana","@stat:conoscenza+1",{"if":"puzzle.c2_sovrapposizione","do":["@dialogue:c2_fine"],"else":["@objective:o2_sovrapponi"]}]},"c3_cassetti":{"type":"drawers","chapter":3,"title":"I diciassette cassetti","plaque":"PRIMVS DVCIT · SECVNDA MEMINIT · TERTIVS TRAICIT · VLTIMVS VERBA CVSTODIT","plaqueIf":[{"if":"flag.targa_tradotta","text":"«Il primo guida · la seconda ricorda · il terzo traghetta · l'ultimo custodisce le parole» — apri nell'ordine del giuramento."}],"drawers":[{"id":"d1","emblem":"⚙","label":"Ruota"},{"id":"d2","emblem":"☾","label":"Luna"},{"id":"d3","emblem":"✚","label":"Croce"},{"id":"d4","emblem":"⚖","label":"Bilancia"},{"id":"d5","emblem":"❧","label":"Foglia"},{"id":"d6","emblem":"✦","label":"Stella"},{"id":"d7","emblem":"♜","label":"Torre"},{"id":"d8","emblem":"⚓","label":"Àncora"},{"id":"d9","emblem":"✂","label":"Forbici"},{"id":"d10","emblem":"♪","label":"Lira"},{"id":"d11","emblem":"◉","label":"Occhio"},{"id":"d12","emblem":"⚷","label":"Chiave"},{"id":"d13","emblem":"✎","label":"Penna"},{"id":"d14","emblem":"☼","label":"Sole"},{"id":"d15","emblem":"⇄","label":"Frecce"},{"id":"d16","emblem":"▤","label":"Schedario"},{"id":"d17","emblem":"⌒","label":"Raschiato","erased":true}],"solution":["d10","d2","d8","d5"],"successText":"Quattro scatti. Dietro il mobile, qualcosa si apre.","hints":["La targa elenca quattro ruoli nell'ordine del giuramento. Kiki sa leggere il latino. La LISTA_17 nel taccuino abbina ogni ruolo al suo emblema.","Chi guida è Orfeo (la lira), chi ricorda è Euridice (la luna), chi traghetta è il Barcaiolo (l'àncora), chi custodisce le parole è il Libraio (la foglia).","Apri in quest'ordine: lira ♪, luna ☾, àncora ⚓, foglia ❧."],"onSolve":["narr: Il fondo del mobile scorre di lato. Dietro, in una nicchia: una chiave d'ottone, un fascicolo legato e un quarto di cerchio di bronzo rosso.","@give:chiave_ottone","@give:lista17","@give:sigillo_a","@clue:lista_completa","@stat:conoscenza+1","@flag:lista_full","beps[surprised]: La Lista dei 17. Completa. Con tutti i nomi.","@dialogue:allarme"]},"c4_sigillo":{"type":"seal","chapter":4,"title":"Il Sigillo di Orfeo","startRot":{"A":1,"B":2,"C":3,"D":1},"successText":"ORFEO · NON · VOLTARTI. Il Sigillo è intero.","hints":["Ogni frammento ha una parola sul bordo. Ricomposto, il bordo deve leggersi in senso orario partendo dall'alto a sinistra.","Il motto è «ORFEO · NON · VOLTARTI». La curva esterna di ogni frammento deve stare verso l'esterno del cerchio: ruota i pezzi finché l'arco guarda fuori.","In alto a sinistra ORFEO (Roma), in alto a destra NON (Banca), in basso a destra VOL (Cantiere), in basso a sinistra TARTI (Ponte Vecchio). Tocca ogni pezzo posato finché la lira al centro si ricompone."],"onSolve":["@take:sigillo_a,sigillo_b,sigillo_c,sigillo_d","@give:sigillo","@clue:sigillo_intero","@stat:conoscenza+1","neri[surprised]: Mio nonno l'ha diviso nel '67 su questo banco. E lei l'ha ricomposto in dieci minuti.","beps: Undici. Ho sbagliato un pezzo.",{"if":"flag.neri_chiave","do":["@objective:o4_corridoio"],"else":["neri: Adesso le serve la porticina del Corridoio. Me lo chieda.","@objective:o4_chiave_corridoio"]}]},"c5_anelli":{"type":"rings","chapter":5,"title":"Gli anelli di Istanbul","rings":[["sole","luna","stella","mano","occhio","onda","lira","chiave"],["onda","mano","chiave","lira","sole","stella","luna","occhio"],["stella","occhio","lira","sole","chiave","luna","mano","onda"],["luna","lira","onda","occhio","stella","mano","sole","chiave"]],"target":["luna","lira","onda","chiave"],"start":[0,0,0,0],"successText":"Luna, lira, onda, chiave. La nicchia si apre.","hints":["Il retro del medaglione ha quattro simboli incisi, dal centro verso il bordo. Esamina il medaglione.","La sequenza è luna, lira, onda, chiave (dall'anello interno all'esterno). Ogni anello trascina quello più interno: sistema prima l'anello esterno.","Esterno su ⚷ chiave, poi il terzo su ≈ onda, poi il secondo su ♪ lira, infine l'interno su ☾ luna. In quest'ordine, non si scombina più nulla."],"onSolve":["narr: La nicchia si apre. Dentro, una lastra di bronzo incisa: una pianta di Firenze. Un cerchio sulla via de' Bardi. Una scala sotto tre gradini.","kiki[surprised]: La stanza murata. La Camera di Orfeo è sotto la stanza murata. Siamo partiti da lì.","beps[think]: «L'acqua arrivò al terzo gradino.» Non era solo una password.","@clue:camera_firenze","@stat:conoscenza+2",{"if":"flag.tetto_scena","do":["@dialogue:c5_fine"],"else":["kiki[tender]: Prima di ripartire… saliamo sul tetto dell'Han. Solo un momento. Te lo chiedo per favore.","@objective:o5_tetto"]}]},"c6_cronologia":{"type":"timeline","chapter":6,"title":"La cronologia di Orfeo","docs":[{"id":"t1","title":"Giuramento dei Quattro","text":"«Oggi, mentre i tedeschi ordinano di sgomberare i lungarni, quattro di noi giurano: Orfeo, Euridice, il Barcaiolo, il Libraio.» Firenze, 30 luglio 1944."},{"id":"t2","title":"Rapporto del Barcaiolo","text":"«Stanotte hanno fatto saltare tutti i ponti. Solo il Ponte Vecchio è rimasto in piedi. Abbiamo portato undici persone di là in barca.» Notte fra il 3 e il 4 agosto 1944."},{"id":"t3","title":"Lettera di Orfeo","text":"«Il Ponte Vecchio è crollato all'alba: l'archivio passerà dal ponte Santa Trinita, ancora intatto.» Firenze, 5 agosto 1944. Firmata «Orfeo», autenticata dal Notaio."},{"id":"t4","title":"Verbale dell'alluvione","text":"«L'Arno è entrato nella stanza alle 7 del mattino. L'acqua si è fermata al terzo gradino.» Firenze, 4 novembre 1966."},{"id":"t5","title":"Promemoria di E.","text":"«Murate la stanza e portate le copie a Parigi.» Firenze, cinque giorni dopo l'alluvione."},{"id":"t6","title":"Verbale della seduta straordinaria","text":"«Ruolo XVII abolito all'unanimità dei presenti. Euridice e il Ponte assenti.» Parigi, 12 marzo 1967. Redatto dal Notaio E. Varano."},{"id":"t7","title":"Lettera di Ada a Selim","text":"«Ho digitalizzato il Registro e l'ho murato con il resto. Se un giorno lo troveranno, che siano in due.» Istanbul, dicembre 1998."}],"initial":["t5","t3","t7","t1","t6","t2","t4"],"solution":["t1","t2","t3","t4","t5","t6","t7"],"forgeries":["t3","t6"],"successText":"Cronologia ricostruita. Due falsi, una sola mano: quella del Notaio.","hints":["Alcune date sono implicite: «cinque giorni dopo l'alluvione» viene dopo il 4 novembre 1966. Poi cerca ciò che non può essere vero.","Una lettera dice che il Ponte Vecchio crollò nel '44: ma è stato l'unico ponte risparmiato (lo dice anche il Barcaiolo). E il nastro del '67 prova che Euridice era presente alla votazione.","Ordine: Giuramento (30/7/44), Barcaiolo (4/8/44), Lettera di Orfeo (5/8/44), Alluvione (4/11/66), Promemoria (9/11/66), Verbale (12/3/67), Lettera di Ada (1998). Falsi: la Lettera di Orfeo e il Verbale."],"onSolve":["kiki: Due falsi. La lettera del '44 dice che il Ponte Vecchio crollò: ma il Ponte Vecchio è l'unico che non cadde. E il verbale del '67 cancella nonna dalla votazione.","beps: Entrambi autenticati dal Notaio. Bruno Varano nel '44, Ettore Varano nel '67. Padre e figlio.","kiki[angry]: Un'intera famiglia che riscrive la storia.","@clue:falso_1944","@stat:conoscenza+2",{"if":"flag.nastro_ascoltato","do":["@objective:o6_varano"],"else":["@objective:o6_nastro"]}]},"c7_registro":{"type":"register","chapter":7,"title":"La Ruota dei Nomi","options":[{"id":"arco","emblem":"⌒","label":"L'arco (il Ponte)"},{"id":"occhio","emblem":"◉","label":"L'occhio","wrong":"L'occhio è il Fotografo, Ruolo IX. Ha già il suo posto."},{"id":"bilancia","emblem":"⚖","label":"La bilancia","wrong":"La bilancia è il Notaio. Non può stare due volte."},{"id":"lira","emblem":"♪","label":"La lira","wrong":"La lira è Orfeo, il primo. Non l'ultimo."}],"solution":"arco","eighteenth":{"if":"flag.knows_18 && count.symbols>=7"},"successText":"Il XVII ha di nuovo il suo emblema. I Nomi rispondono.","successText18":"Il XVII ha di nuovo il suo emblema. E il XVIII, per la prima volta, ha due nomi.","hints":["Il ruolo raschiato è il diciassettesimo: quello abolito nel 1967. Don Ilario e il nastro dicono come si chiamava.","Il XVII era il Ponte (Guido Sarti): il ponte tra Orfeo e il mondo. Il suo emblema è quello che somiglia a un ponte.","Scegli l'arco ⌒."],"onSolve":["@flag:m_registro","kiki: I Nomi rispondono.","narr: Un terzo scatto, più profondo. Dall'altra parte, la serratura di Beps si illumina.","@objective:o7_leva"]}}},"characters":{"_doc":"Personaggi. look = parametri del fallback procedurale (temporaneo). sprites = strisce orizzontali in assets/sprites/<id>/<anim>.png (frames, fps, w/h di un frame). Il gioco usa automaticamente gli sprite presenti nel manifest.","characters":{"beps":{"name":"Beps","protagonist":true,"role":"Giuseppe, informatico curioso della ditta di restauro","height":1,"look":{"skin":"#d9a882","hair":"#2a1d14","hairStyle":"short","beard":true,"top":"#2a3a52","topStyle":"jacket","shirt":"#e8e2d4","bottom":"#2b2f3a","shoes":"#3a2414","eyes":"#4a3020","portraitBg":"#2a3442"},"sprites":{"idle":{"src":"assets/sprites/beps/idle.png","frames":6,"fps":6,"w":242,"h":512},"walk":{"src":"assets/sprites/beps/walk.png","frames":8,"fps":12,"w":228,"h":512},"run":{"src":"assets/sprites/beps/run.png","frames":8,"fps":16,"w":282,"h":512},"talk":{"src":"assets/sprites/beps/talk.png","frames":6,"fps":8,"w":332,"h":512},"use":{"src":"assets/sprites/beps/use.png","frames":6,"fps":8,"w":234,"h":512},"pickup":{"src":"assets/sprites/beps/pickup.png","frames":6,"fps":10,"w":264,"h":512},"inspect":{"src":"assets/sprites/beps/inspect.png","frames":6,"fps":6,"w":298,"h":512},"read":{"src":"assets/sprites/beps/read.png","frames":6,"fps":5,"w":310,"h":512},"phone":{"src":"assets/sprites/beps/phone.png","frames":6,"fps":5,"w":244,"h":512},"reaction":{"src":"assets/sprites/beps/reaction.png","frames":6,"fps":10,"w":304,"h":512}},"desc":"Beps.","lookLines":[{"if":"chapter>=5 && stat.legame>=14","text":{"kiki":["kiki[tender]: Ha i capelli spettinati dal vento. Non glielo dirò. Mi piace così."]}},{"if":"chapter>=3","text":{"kiki":["kiki[smile]: Beps. Informatico, testardo, incapace di leggere il latino. Il mio socio."]}},{"if":"true","text":{"kiki":["kiki[skeptical]: Un informatico che si infila negli archivi altrui. Non so ancora se fidarmi."]}}],"journal":[{"if":"true","text":"Giuseppe, per tutti Beps. Fa l'informatico per la ditta di restauro che lavora al palazzo di via de' Bardi. Curioso di tutto, smonta qualunque cosa per vedere come funziona. Doveva essere un intervento di dieci minuti."},{"if":"chapter>=4","text":"Ha attraversato Firenze da solo per ritrovare Kiki. Non lo ammetterà mai, ma aveva paura."}]},"kiki":{"name":"Kiki","nameIf":[{"if":"!flag.kiki_named","name":"La sconosciuta"}],"protagonist":true,"role":"Federica, restauratrice di carta e storica d'archivio","height":0.95,"look":{"skin":"#e2b594","hair":"#3a2216","hairStyle":"long","top":"#7a2a2a","topStyle":"coat","shirt":"#e8dccc","scarf":"#c9a85a","bottom":"#2a2228","shoes":"#1a1210","eyes":"#5a3a1a","lipstick":"#a8443a","earring":true,"portraitBg":"#4a2a28"},"sprites":{"idle":{"src":"assets/sprites/kiki/idle.png","frames":6,"fps":6,"w":208,"h":512},"walk":{"src":"assets/sprites/kiki/walk.png","frames":8,"fps":12,"w":238,"h":512},"run":{"src":"assets/sprites/kiki/run.png","frames":8,"fps":16,"w":286,"h":512},"talk":{"src":"assets/sprites/kiki/talk.png","frames":6,"fps":8,"w":380,"h":512},"use":{"src":"assets/sprites/kiki/use.png","frames":6,"fps":8,"w":384,"h":512},"pickup":{"src":"assets/sprites/kiki/pickup.png","frames":6,"fps":10,"w":266,"h":512},"inspect":{"src":"assets/sprites/kiki/inspect.png","frames":6,"fps":6,"w":304,"h":512},"read":{"src":"assets/sprites/kiki/read.png","frames":6,"fps":5,"w":356,"h":512},"reaction":{"src":"assets/sprites/kiki/reaction.png","frames":6,"fps":8,"w":380,"h":512}},"lookLines":[{"if":"chapter>=5 && stat.legame>=14","text":{"beps":["beps[tender]: Kiki. Quando si concentra, morde il tappo della penna. Ho smesso di contare le penne."]}},{"if":"chapter>=3","text":{"beps":["beps[smile]: Kiki. Legge il latino come io leggo le piante catastali. Meglio, a dire il vero."]}},{"if":"flag.kiki_named","text":{"beps":["beps: Federica. Kiki. Ha una fotografia identica alla mia e nessuna intenzione di spiegarmi perché."]}},{"if":"true","text":{"beps":["beps: Non l'ho mai vista prima. Eppure mi guarda come se mi aspettasse."]}}],"journal":[{"if":"flag.met_kiki","text":"Federica, detta Kiki. Restauratrice di carta e storica d'archivio, divisa tra Firenze e Parigi. Possiede una copia della stessa fotografia del 1944."},{"if":"flag.kiki_nonna","text":"La voce registrata in NON_APRIRE.wav è quella di sua nonna, Ada Morel, morta nel 2019."},{"if":"chapter>=5","text":"Ha attraversato mezza Europa con te. Quando ride, si copre la bocca con la mano. Lo fa sempre meno."}]},"kiki_npc":{"name":"La sconosciuta","look":{"skin":"#e2b594","hair":"#3a2216","hairStyle":"long","top":"#7a2a2a","topStyle":"coat","scarf":"#c9a85a","bottom":"#2a2228","lipstick":"#a8443a","earring":true,"portraitBg":"#4a2a28"},"height":0.95,"sprites":{"idle":{"src":"assets/sprites/kiki/idle.png","frames":6,"fps":6,"w":208,"h":512},"walk":{"src":"assets/sprites/kiki/walk.png","frames":8,"fps":12,"w":238,"h":512},"run":{"src":"assets/sprites/kiki/run.png","frames":8,"fps":16,"w":286,"h":512},"talk":{"src":"assets/sprites/kiki/talk.png","frames":6,"fps":8,"w":380,"h":512},"use":{"src":"assets/sprites/kiki/use.png","frames":6,"fps":8,"w":384,"h":512},"pickup":{"src":"assets/sprites/kiki/pickup.png","frames":6,"fps":10,"w":266,"h":512},"inspect":{"src":"assets/sprites/kiki/inspect.png","frames":6,"fps":6,"w":304,"h":512},"read":{"src":"assets/sprites/kiki/read.png","frames":6,"fps":5,"w":356,"h":512},"reaction":{"src":"assets/sprites/kiki/reaction.png","frames":6,"fps":8,"w":380,"h":512}},"portraitOf":"kiki"},"archivista":{"name":"Ottavia Ricci","nameIf":[{"if":"!flag.met_archivista","name":"L'archivista"}],"role":"Capo archivista, Archivio Storico di Firenze","height":0.92,"look":{"skin":"#e0b898","hair":"#b8b0a8","hairStyle":"bun","glasses":true,"top":"#4a5a4a","topStyle":"cardigan","bottom":"#3a3a3a","portraitBg":"#3a4238"},"sprites":{"idle":{"src":"assets/sprites/archivista/idle.png","frames":6,"fps":4,"w":226,"h":512},"talk":{"src":"assets/sprites/archivista/talk.png","frames":6,"fps":6,"w":314,"h":512}},"journal":[{"if":"true","text":"Capo archivista da trentun anni. Conosce ogni scheda del catalogo, comprese quelle che non dovrebbero esistere."},{"if":"flag.ottavia_padre","text":"Suo padre, Renzo Ricci, era il Barcaiolo: nel 1944 traghettava persone sull'Arno di notte. Lei non è mai entrata in Orfeo. Per scelta."}]},"sandro":{"name":"Sandro","role":"Capocantiere","height":1.02,"look":{"skin":"#c98e68","hair":"#4a4038","hairStyle":"bald","moustache":true,"top":"#c97a2a","topStyle":"vest","vest":"#e0a030","bottom":"#3a4a5a","portraitBg":"#4a3a28"},"journal":[{"if":"true","text":"Capocantiere al palazzo di via de' Bardi. Ha aperto lui la stanza murata. Dice che di notte, lì dentro, si sente l'acqua."}]},"tommaso":{"name":"Tommaso","role":"Barista del Caffè delle Logge","look":{"skin":"#d8a880","hair":"#1a1410","hairStyle":"short","top":"#f0ece4","topStyle":"vest","vest":"#1a1a1a","bottom":"#1a1a1a","portraitBg":"#3a2a20"},"journal":[{"if":"true","text":"Fa il miglior cappuccino dell'Oltrarno e ascolta tutto senza darlo a vedere."}]},"varano":{"name":"Aurelio Varano","nameIf":[{"if":"!flag.varano_named","name":"L'uomo col cappotto grigio"}],"role":"Notaio — Ruolo XI di Orfeo","height":1.04,"look":{"skin":"#d6b098","hair":"#c8c4bc","hairStyle":"hat","hatColor":"#2a2a2e","top":"#5a5e64","topStyle":"coat","shirt":"#e8e8e8","scarf":"#2a2a30","bottom":"#2a2a30","shoes":"#111","eyes":"#5a6a7a","portraitBg":"#2a2e34"},"sprites":{"idle":{"src":"assets/sprites/varano/idle.png","frames":6,"fps":5,"w":252,"h":512},"talk":{"src":"assets/sprites/varano/talk.png","frames":6,"fps":7,"w":318,"h":512},"walk":{"src":"assets/sprites/varano/walk.png","frames":8,"fps":11,"w":272,"h":512}},"journal":[{"if":"true","text":"Un uomo alto, cappotto grigio scuro, sciarpa bordeaux, guanti di pelle. Vi segue da Firenze. Non sembra avere fretta."},{"if":"flag.varano_named","text":"Aurelio Varano, notaio fiorentino. Custodisce il Ruolo XI di Orfeo, quello del Notaio, ereditato dal padre Ettore."},{"if":"flag.varano_past","text":"Suo nonno Bruno, nel 1944, fu un delatore. Sua nonna Lina, nello stesso anno, salvò trenta persone. Nel Registro ci sono entrambi. Aurelio non sa quale dei due essere."},{"if":"flag.varano_doubt","text":"Vuole bruciare l'archivio per chiudere una ferita. Ma ha esitato. Due volte."}]},"helene":{"name":"Hélène Marchetti","role":"Fotografa, Studio Marchetti — Parigi","height":0.96,"look":{"skin":"#e8c4a8","hair":"#d8d0c8","hairStyle":"bob","top":"#b8a07a","topStyle":"trench","shirt":"#2a2a2a","bottom":"#2a2a2a","lipstick":"#9a3a3a","earring":true,"portraitBg":"#3a3430"},"journal":[{"if":"true","text":"Figlia del fotografo che scattò la foto del 1967. Gestisce lo Studio Marchetti nel Marais, tra negativi e un gatto di nome Daguerre."},{"if":"flag.helene_euridice","text":"È l'attuale Euridice. Ha raccolto il ruolo da Ada Morel, la nonna di Kiki, nel 2019."},{"if":"flag.helene_doubt","text":"Giura di non essere mai stata a Istanbul a dicembre. Allora chi era la donna nel bazar?"}]},"albert":{"name":"Monsieur Albert","role":"Bouquiniste sul Quai des Grands-Augustins","look":{"skin":"#e0b090","hair":"#e0dcd4","hairStyle":"grey","beard":true,"beardColor":"#e0dcd4","top":"#3a4a3a","topStyle":"coat","scarf":"#8a2a2a","bottom":"#3a3428","portraitBg":"#2a3a30"},"sprites":{"idle":{"src":"assets/sprites/albert/idle.png","frames":6,"fps":4,"w":250,"h":512},"talk":{"src":"assets/sprites/albert/talk.png","frames":6,"fps":6,"w":284,"h":512}},"journal":[{"if":"true","text":"Vende libri sulla Senna da cinquant'anni. Accetta pagamenti solo da chi sa rispondere alle sue domande."}]},"ilario":{"name":"Don Ilario Cesti","role":"Bibliotecario della Teodosiana — Ruolo XIV, il Libraio","height":0.9,"look":{"skin":"#e0c0a0","hair":"#e8e4dc","hairStyle":"grey","glasses":true,"top":"#141414","topStyle":"coat","shirt":"#f4f4f4","bottom":"#141414","portraitBg":"#2a2420"},"sprites":{"idle":{"src":"assets/sprites/ilario/idle.png","frames":6,"fps":4,"w":182,"h":512},"talk":{"src":"assets/sprites/ilario/talk.png","frames":6,"fps":6,"w":318,"h":512}},"journal":[{"if":"true","text":"Novantun anni, bibliotecario della Teodosiana. Cita Seneca e i Pink Floyd con la stessa disinvoltura."},{"if":"flag.ilario_libraio","text":"È il Libraio, Ruolo XIV di Orfeo. Il più anziano dei custodi ancora vivi."}]},"agente":{"name":"Agente di Orfeo","role":"Uomini del Notaio","look":{"skin":"#d0a888","hair":"#d8c070","hairStyle":"short","top":"#1a1a1e","topStyle":"coat","bottom":"#1a1a1e","glasses":true,"portraitBg":"#1a1a20"},"sprites":{"idle":{"src":"assets/sprites/agente/idle.png","frames":6,"fps":4,"w":196,"h":512},"talk":{"src":"assets/sprites/agente/talk.png","frames":6,"fps":6,"w":288,"h":512}},"journal":[{"if":"true","text":"Due uomini in cappotto scuro. Uno biondo, uno che non parla mai. Lavorano per il Notaio, ma non sembrano entusiasti."}]},"neri":{"name":"Mastro Neri","role":"Orafo sul Ponte Vecchio","look":{"skin":"#d8a880","hair":"#8a8478","hairStyle":"grey","moustache":true,"glasses":true,"top":"#5a4a3a","topStyle":"vest","vest":"#2a2018","bottom":"#3a3430","portraitBg":"#3a3020"},"journal":[{"if":"true","text":"Orafo sul Ponte Vecchio da tre generazioni. Suo nonno custodiva un frammento del Sigillo. Lui lo ha custodito senza sapere perché."}]},"bellandi":{"name":"Dott.ssa Bellandi","role":"Responsabile cassette di sicurezza, Banca del Giglio","look":{"skin":"#e8c0a0","hair":"#2a1a14","hairStyle":"bob","top":"#1e2a3a","topStyle":"jacket","shirt":"#f0f0f0","bottom":"#1e2a3a","glasses":true,"portraitBg":"#283038"},"journal":[{"if":"true","text":"Gentile, inflessibile, protocollare. Ha studiato il regolamento della banca come altri studiano Dante."}]},"selim":{"name":"Selim Aydın","role":"Antiquario al Gran Bazar — Ruolo XVI, il Traduttore","height":0.97,"look":{"skin":"#c89870","hair":"#d8d4cc","hairStyle":"grey","moustache":true,"top":"#6a3a2a","topStyle":"vest","vest":"#3a2a5a","shirt":"#e8e0d0","bottom":"#3a3028","portraitBg":"#4a2a20"},"sprites":{"idle":{"src":"assets/sprites/selim/idle.png","frames":6,"fps":4,"w":234,"h":512},"talk":{"src":"assets/sprites/selim/talk.png","frames":6,"fps":6,"w":350,"h":512}},"journal":[{"if":"true","text":"Antiquario nel Gran Bazar. Parla sei lingue e le mescola quando si emoziona."},{"if":"flag.selim_traduttore","text":"È il Traduttore, Ruolo XVI. Sua madre Nermin accoglieva a Istanbul chi fuggiva da Firenze nel 1944."}]},"emre":{"name":"Emre","role":"Ragazzo del tè","height":0.8,"look":{"skin":"#c89068","hair":"#1a1410","hairStyle":"short","top":"#e8e0d0","topStyle":"vest","vest":"#7a2a2a","bottom":"#2a2a2a","portraitBg":"#3a2a20"},"journal":[{"if":"true","text":"Porta il tè in tutto il bazar su un vassoio appeso a tre catenelle. Sa tutto di tutti."}]},"donna":{"name":"La donna in nero","role":"La donna nelle fotografie","look":{"skin":"#e8d0c0","hair":"#111","hairStyle":"hat","hatColor":"#0a0a0a","top":"#0e0e10","topStyle":"dress","bottom":"#0e0e10","shoes":"#000","portraitBg":"#101012"},"journal":[{"if":"true","text":"Cappello a falda larga, abito nero, un medaglione al collo. È nella fotografia del 1944. È in quella del 1967. E l'hai vista sul Lungarno."},{"if":"flag.euridice_ruolo","text":"Non è una persona: è un ruolo. Euridice, la Testimone. Chi lo eredita si veste come lei e si mette nello stesso punto di ogni fotografia."},{"if":"flag.helene_doubt","text":"Eppure qualcuno, a Istanbul, indossava quel cappello. E non era Hélène."}]}}},"collectibles":{"_doc":"Archivio Orfeo: 17 documenti, 12 fotografie, 7 registrazioni, 7 simboli. stat = effetto nascosto alla raccolta. after = script dopo la lettura. Immagini reali facoltative in assets/collectibles/<id>.jpg.","documents":[{"id":"doc_01","chapter":1,"title":"Bolla di consegna","date":"14 marzo 1998","place":"Firenze","text":"«Ditta Restauri Bardi — Consegnato a domicilio: n. 1 personal computer, n. 1 armadio metallico, sacchi di malta (10). Committente: sig.ra A. Morel, per conto di E. Pagamento: contanti.» In fondo, a penna: «Murare entro venerdì.»"},{"id":"doc_02","chapter":1,"title":"Registro di consultazione del deposito","date":"1967–2026","place":"Archivio Storico","text":"Ripiano 17 consultato: 1967 (J. Marchetti), 1978 (I. Cesti), 1989 (A. Morel), 1998 (A. Morel), 2019 (H. Marchetti), 2025 (A. Varano). L'ultima riga è stata cancellata con la gomma, ma la penna ha lasciato il solco: «A. Varano». Era qui un anno prima di noi."},{"id":"doc_03","chapter":2,"title":"Provino a contatto","date":"12 marzo 1967","place":"Parigi","text":"Trentasei fotogrammi della seduta del 12 marzo. Sul margine, a matita grassa, Jacques Marchetti ha cerchiato due figure e scritto: «presenti». Accanto: «E.» e «G.S.». In un fotogramma Ettore Varano guarda in macchina. È l'unico che sembra sapere di essere fotografato.","stat":"conoscenza+1"},{"id":"doc_04","chapter":2,"title":"Lettera mai spedita","date":"1967","place":"Gare de Lyon, consigne n. 67","text":"«Guido, se leggi queste righe hanno fatto quello che temevamo: ti hanno cancellato. Io ho detto di no, ad alta voce. Non risulterà da nessuna parte. Ma io lo so, e un giorno lo saprà qualcun altro. — A.» La busta è affrancata e mai imbucata.","stat":"conoscenza+1"},{"id":"doc_05","chapter":2,"title":"Ricevuta dello Studio Marchetti","date":"15 marzo 1967","place":"Parigi","text":"«Stampa di n. 2 copie, formato 18×24, soggetto: gruppo. Una copia spedita a Firenze. Una copia consegnata a mano alla sig.ra Morel.» Prezzo: «gratuito — per Euridice»."},{"id":"doc_06","chapter":2,"title":"Pagina del diario di Ada","date":"4 novembre 1966","place":"Firenze","text":"«L'acqua è entrata dappertutto. Ho passato la notte nella stanza con Renzo, il Barcaiolo, a portare i registri sopra il terzo gradino. Lui rideva: diceva che era tornato a fare il suo mestiere. Alle cinque abbiamo smesso. Avevamo salvato tutto tranne le scarpe.»","stat":"legame+1"},{"id":"doc_07","chapter":3,"title":"Lettera di Don Ilario","date":"1978","place":"Roma","text":"«Cara Ada, ho votato male nel '67 e voterei peggio oggi, perché sono più vecchio e più vile. Ma conservo la chiave. Quando arriverà qualcuno col medaglione intero, glielo darò senza chiedere niente. È l'unica penitenza che mi riesce. — Ilario»","stat":"conoscenza+1"},{"id":"doc_08","chapter":3,"title":"Verbale romano","date":"1945","place":"Biblioteca Teodosiana","text":"Elenco dei diciassette ruoli con la data del giuramento. Accanto al XVII, il Ponte: «Guido Sarti, tipografo dell'Oltrarno. Giura per ultimo, 2 settembre 1944. Compito: decidere quando il Registro uscirà alla luce.»","stat":"conoscenza+1"},{"id":"doc_09","chapter":3,"title":"Biglietto sul muretto","date":"senza data","place":"Trastevere","text":"Un foglio piegato in quattro, fermato da una moneta da 500 lire: «Bravi. Non voltatevi. — E.» La calligrafia non è quella di Ada. Né quella di Hélène."},{"id":"doc_10","chapter":4,"title":"Biglietto sulla scrivania","date":"dicembre 2026","place":"Ufficio di Beps","text":"Su carta intestata «Studio notarile Varano»: «Non cercate quello che brucia. Il computer era nostro. Ve lo restituisco: avete già preso quello che contava. — A.V.» Sul retro, a matita, cancellato: «mi dispiace per il plastico»."},{"id":"doc_11","chapter":4,"title":"Registro degli accessi","date":"1944–2026","place":"Banca del Giglio","text":"La cassetta 17 è stata aperta solo cinque volte in ottantadue anni: 1944, 1967, 1989, 2019 e oggi. Le prime quattro firme sono tutte di donne. La quinta è la mia."},{"id":"doc_12","chapter":4,"title":"Elenco graffito","date":"agosto 1944","place":"Corridoio Vasariano","text":"Inciso col coltello sotto una finestra: undici nomi e una data, «4 VIII 44». Sono le persone che il Barcaiolo portò di là in barca la notte dei ponti. Sotto, più recente: «Ricordati di noi, Firenze».","stat":"conoscenza+1"},{"id":"doc_13","chapter":5,"title":"Lista di spedizione","date":"1944","place":"Gran Bazar","text":"«Da Livorno a Istanbul: 12 casse di LIBRI.» Accanto a ogni cassa, un nome di persona e un'età. La più piccola, «Libri, cassa 7», ha quattro anni.","stat":"conoscenza+1"},{"id":"doc_14","chapter":5,"title":"Lasciapassare","date":"settembre 1944","place":"Büyük Valide Han","text":"Un lasciapassare falso, perfetto, firmato «il Tipografo». Intestato a Guido Sarti. Non è mai stato usato: Guido decise di restare a Firenze, «perché qualcuno deve fare da ponte».","stat":"conoscenza+1"},{"id":"doc_15","chapter":5,"title":"Lettera di Ada a Selim","date":"dicembre 1989","place":"Istanbul","text":"«Selim, ho scelto una seconda Testimone, nel caso mi succeda qualcosa. Non te ne dico il nome: è più sicura se non la conosce nessuno, nemmeno tu. Si siederà al Caffè delle Logge il giovedì e lascerà 500 lire, come facevo io. Se mai la vedrai, offrile un tè. — Ada»","stat":"legame+1"},{"id":"doc_16","chapter":6,"title":"Atto di cancellazione del Ruolo XVII","date":"12 marzo 1967","place":"Parigi","text":"Atto notarile su carta bollata: «Il Ruolo XVII è abolito. Il suo titolare è rimosso da ogni documento, fotografia e registro di Orfeo.» Firmato: Ettore Varano. In calce, a mano, una seconda firma, tremante: «Euridice — contraria».","stat":"conoscenza+1"},{"id":"doc_17","chapter":6,"title":"Lettera di Lina Varano","date":"1946","place":"Firenze","text":"«Caro Aurelio, non ti conoscerò mai, ma un giorno avrai il cognome di tuo nonno e io voglio che tu abbia anche il mio. Bruno ha venduto sei persone. Io ne ho nascoste trenta nella cantina sotto i suoi piedi. Siamo stati entrambi Varano. Scegli tu quale essere. — Nonna Lina»","stat":"conoscenza+1","after":["@clue:lina"]}],"photos":[{"id":"photo_01","chapter":1,"title":"I ponti di Firenze","date":"agosto 1944","place":"Caffè delle Logge","photo":"generic","text":"Il Lungarno coperto di macerie dopo la notte del 3 agosto. In fondo, intatto, il Ponte Vecchio. Una donna col cappello attraversa la piazza verso la macchina fotografica.","woman":true},{"id":"photo_02","chapter":1,"title":"L'Archivio dopo l'alluvione","date":"novembre 1966","place":"Archivio Storico","photo":"generic","text":"Volontari in fila che si passano faldoni fradici di mano in mano. Gli angeli del fango. Tra loro, una bambina con gli occhiali: Ottavia Ricci, otto anni.","stat":"legame+1"},{"id":"photo_03","chapter":2,"title":"Gare de Lyon","date":"marzo 1967","place":"Parigi","photo":"photo1967","text":"Una cartolina d'epoca: il Train Bleu, i lampioni, una folla sotto l'orologio. Ingrandendo, sotto l'orologio: un cappello nero.","woman":true},{"id":"photo_04","chapter":2,"title":"Jacques e Ada","date":"1966","place":"Studio Marchetti","photo":"generic","text":"Jacques Marchetti e Ada Morel ridono davanti al banco luminoso. È l'unica foto in cui Ada non porta il cappello.","stat":"legame+1"},{"id":"photo_05","chapter":2,"title":"Ada e la piccola","date":"1995","place":"Rue Vieille-du-Temple","photo":"generic","text":"Ada su questo divano, con una bambina di un anno in braccio. Sul retro: «Federica. Ha già il mio carattere. Che Dio aiuti chi le starà vicino.»","stat":"legame+1"},{"id":"photo_06","chapter":3,"title":"Roma 1978","date":"1978","place":"Biblioteca Teodosiana","photo":"generic","text":"La donna col cappello sotto il busto di Teodosio, nello stesso punto delle altre foto. Ma le mani sono diverse: più giovani. Non è Ada.","woman":true,"stat":"conoscenza+1"},{"id":"photo_07","chapter":3,"title":"Trastevere 1944","date":"giugno 1944","place":"Osteria da Fiorella","photo":"generic","text":"La liberazione di Roma: gente in strada, bandiere, un carretto. Una ragazzina con un grembiule sorride: è Fiorella, la proprietaria dell'osteria. Ottant'anni fa."},{"id":"photo_08","chapter":4,"title":"Il ponte che non cadde","date":"4 agosto 1944","place":"Ponte Vecchio","photo":"generic","text":"Il Ponte Vecchio all'alba, con le macerie delle case distrutte agli ingressi. Su una barca sotto le arcate, un uomo rema: Renzo Ricci, il Barcaiolo.","stat":"conoscenza+1"},{"id":"photo_09","chapter":5,"title":"Istanbul 1989","date":"dicembre 1989","place":"Bottega di Selim","photo":"generic","text":"Ada e Selim davanti alla bottega. Dietro di loro, sfocata, una giovane donna col cappello nero. Ada la guarda con orgoglio. Il volto della ragazza è tagliato dalla cornice.","woman":true,"stat":"conoscenza+1"},{"id":"photo_10","chapter":5,"title":"Il porto di Galata","date":"1944","place":"Istanbul","photo":"generic","text":"Una cartolina: un piroscafo italiano attraccato a Karaköy. Sul retro, in italiano: «Siamo arrivati in dodici. Grazie, Firenze.»"},{"id":"photo_11","chapter":6,"title":"Il passaggio del cappello","date":"2019","place":"Studio Marchetti","photo":"generic","text":"Ada, molto anziana, in poltrona. Hélène in piedi accanto a lei, col cappello nero in mano. Nessuna delle due sorride. Entrambe sembrano in pace."},{"id":"photo_12","chapter":7,"title":"Firenze 1944 — l'originale","date":"luglio 1944","place":"Camera di Orfeo","photo":"photo1944","photoOpts":{"half":false},"text":"La stampa originale, intatta. Il volto che nelle copie è graffiato qui si vede bene: un giovane con gli occhiali e la giacca macchiata d'inchiostro. Sotto, a matita: «Guido Sarti, il Ponte».","woman":true,"stat":"conoscenza+1"}],"recordings":[{"id":"rec_01","chapter":1,"title":"Microcassetta: dettatura di E.","date":"1998","place":"Ripiano 17","duration":"01:12","text":"«Prova, prova. … Ho finito di copiare il Registro sul computer. Lo muro con il resto, in via de' Bardi. Se qualcuno lo trova, che sappia una cosa: il Registro non è una condanna. È una lista di persone che hanno avuto coraggio. Gli altri nomi ci sono solo perché i coraggiosi avevano qualcuno da cui difendersi.»","stat":"conoscenza+1"},{"id":"rec_02","chapter":2,"title":"Segreteria telefonica","date":"2019","place":"Casa di Ada","duration":"00:34","text":"«Nonna, sono Federica. Ti chiamo da Firenze, piove. Volevo solo sentirti. Ti richiamo domani.» Bip. «Federica, sono nonna. Domani non ci sono. Ma tu richiama lo stesso, qualcuno risponderà.»","stat":"legame+1"},{"id":"rec_03","chapter":3,"title":"Dittafono di Don Ilario","date":"1999","place":"Passaggio di servizio","duration":"00:58","text":"«Appunti per il mio successore. Se state ascoltando, sono morto o sono a pranzo. In entrambi i casi: il medaglione intero apre la sala. Le cose intere aprono le porte. Quelle a metà aprono solo discussioni.»","stat":"conoscenza+1"},{"id":"rec_04","chapter":4,"title":"Dettatura di Aurelio Varano","date":"2025","place":"Grotta del Buontalenti","duration":"01:40","text":"«Lettera a mia nonna, che non ho conosciuto. … Non riesco a finirla. Ogni volta che scrivo il tuo nome mi viene in mente il suo. Non so se il Registro vi separerà o vi metterà vicini per sempre. Ho paura di tutte e due le cose.»","stat":"fiducia+1"},{"id":"rec_05","chapter":5,"title":"Disco di Nermin","date":"1951","place":"Bottega di Selim","duration":"02:31","text":"Una canzone in ladino e turco, cantata da una donna. Selim traduce: «Siete arrivati di notte con nomi falsi. Ve ne andrete di giorno con i vostri.» È la ninna nanna che Nermin cantava ai bambini delle casse di libri.","stat":"legame+1"},{"id":"rec_06","chapter":6,"title":"Colonna sonora di una bobina","date":"1967","place":"Sala di proiezione","duration":"00:45","text":"L'audio di un film di famiglia: Jacques Marchetti che dirige una foto di gruppo. «Più a destra, Ettore. Ada, tu resta lì, in disparte, come sempre. Guido, togliti gli occhiali. Guido? Dov'è Guido?»","stat":"conoscenza+1"},{"id":"rec_07","chapter":7,"title":"L'ultimo messaggio di Ada","date":"2019","place":"Galleria sotto l'Arno","duration":"01:58","text":"«Se sentite questo, siete arrivati fin qui in due. Bene. Io non ci sono riuscita: avevo Guido, poi non l'ho avuto più. Il Registro non va né salvato né bruciato da soli. Decidetelo insieme. E se c'è uno spazio vuoto dopo il diciassettesimo… scriveteci quello che volete. Vi voglio bene. Anche a te, testardo.»","stat":"legame+1"}],"symbols":[{"id":"sym_1","chapter":1,"title":"La lira della stanza murata","glyph":"♪","place":"Via de' Bardi","text":"Una lira incisa nell'intonaco. Sotto la lira, una parola sola, in maiuscolo: «IL».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]},{"id":"sym_2","chapter":2,"title":"Il lucchetto della Senna","glyph":"☾","place":"Quai des Grands-Augustins","text":"Un vecchio lucchetto d'ottone con una lira e una luna incise. Sul retro: «DICIOTTESIMO».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]},{"id":"sym_3","chapter":3,"title":"La lira nella fontana","glyph":"✦","place":"Piazza dei Librai","text":"Una lira scolpita nel bordo della vasca, levigata dalle mani di chi si siede. Sotto, minuscolo: «NOME».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]},{"id":"sym_4","chapter":4,"title":"La lira del Corridoio","glyph":"⚓","place":"Corridoio Vasariano","text":"Una lira incisa sotto la finestrella, dove il Barcaiolo guardava il fiume. Accanto: «APPARTIENE».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]},{"id":"sym_5","chapter":5,"title":"La lira sotto la Medusa","glyph":"❧","place":"Cisterna","text":"Una lira graffiata sotto la testa capovolta della Medusa. Accanto: «A CHI».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]},{"id":"sym_6","chapter":6,"title":"La lira tra le ossa","glyph":"⚷","place":"Catacombe","text":"Una lira composta con piccole ossa, tra i disegni del muro. Sotto, su una targhetta: «NON SI VOLTA».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]},{"id":"sym_7","chapter":7,"title":"La lira sulla volta","glyph":"⌒","place":"Galleria sotto l'Arno","text":"Una lira dipinta sulla volta, con una parola sola: «DA SOLO».","after":[{"if":"count.symbols>=7 && !flag.knows_18","do":["@dialogue:diciottesimo"]}]}]},"endings":{"_doc":"Finali. req = condizione (vedi DIALOGUE_SYSTEM.md). lockedHint = cosa vede il giocatore se il finale non è disponibile (mai numeri). epilogues = varianti, la prima la cui condizione è vera. postcredit = script dopo i titoli.","prompt":"Il Registro di Orfeo, ottant'anni di nomi, è tra le vostre mani. Il Notaio aspetta, una scatola di fiammiferi in tasca. Cosa farete?","order":["luce","custodi","cenere","segreto"],"endings":{"luce":{"title":"La Luce","subtitle":"Il Registro viene reso pubblico.","choice":"La Luce","choiceSub":"Consegnare il Registro all'Archivio Storico e alla stampa. Tutti i nomi, quelli che salvarono e quelli che tradirono.","lockedHint":"Per difendere la verità davanti al mondo vi servirebbero più prove e una conoscenza più profonda di Orfeo.","req":"stat.conoscenza>=30 && evidence>=9 && item.registro","script":["beps: La Luce. Guido Sarti voleva questo. Il Ponte.","kiki: Tutti i nomi. Anche quelli che fanno male.",{"if":"flag.varano_doubt","do":["varano[sad]: Allora testimonierò. Racconterò di mio padre, del verbale. E di mia nonna Lina. È l'unico modo di essere un Varano diverso.","@flag:varano_testimonia"],"else":["varano: Non posso fermarvi. Non vi chiederò di perdonarmi se non verrò alla conferenza stampa."]},"@cutscene:fine_luce"],"epilogues":[{"id":"luce_amore","if":"stat.legame>=20","text":["Tre mesi dopo, il Registro di Orfeo viene esposto all'Archivio Storico di Firenze. Ottavia Ricci cura la mostra e, per la prima volta in trent'anni, sorride in pubblico davanti alla foto di suo padre.","Trecentoquattordici persone salvate. Diciannove delatori. Il nome di Guido Sarti torna nella foto del 1944: un restauratore di carta lo ricostruisce graffio per graffio. Il restauratore è Kiki.","{varano}","Beps e Kiki non smettono di litigare su dove appendere la foto. Alla fine la appendono in due posti. Nella loro casa nuova, in Oltrarno, c'è un tavolino del Caffè delle Logge che Tommaso ha giurato di non aver mai venduto."]},{"id":"luce","if":"true","text":["Tre mesi dopo, il Registro di Orfeo viene esposto all'Archivio Storico di Firenze. Ottavia Ricci cura la mostra.","Trecentoquattordici persone salvate. Diciannove delatori. Il nome di Guido Sarti torna nella foto del 1944.","{varano}","Beps torna ai suoi computer. Kiki torna a Parigi. Si scrivono ogni settimana. Lettere, non messaggi. Ada ne sarebbe fiera."]}],"postcredit":["@cutscene:post_luce"]},"custodi":{"title":"I Custodi","subtitle":"Orfeo rinasce, con due nuovi custodi.","choice":"I Custodi","choiceSub":"Prendere il posto di Euridice e del Ponte. Custodire il Registro, insieme, finché non sarà il momento giusto.","lockedHint":"Per custodire insieme un segreto così, la fiducia e il legame tra voi dovrebbero essere più forti, e costruiti agendo insieme.","req":"stat.fiducia>=12 && stat.legame>=20 && flag.coop>=5","script":["kiki: Lo custodiamo noi. Io sarò Euridice, come nonna. Hélène sarà felice di restituirmi il cappello.","beps: E io sarò il Ponte. Il ruolo che hanno cancellato. Deciderò io quando il Registro uscirà. Con te.","varano[sad]: Il Ponte e la Testimone. Mio padre si rivolterebbe nella tomba.",{"if":"flag.varano_doubt","do":["varano: …Bene. Lasciatemi restare il Notaio. Vi prometto che stavolta il verbale dirà la verità.","@flag:varano_custode"],"else":["varano: Fate come volete. Io ho finito con Orfeo."]},"@cutscene:fine_custodi"],"epilogues":[{"id":"custodi","if":"true","text":["Orfeo si riunisce di nuovo, il 12 marzo, a Parigi. Diciassette sedie, diciassette custodi. Per la prima volta dal 1967, nessuna è vuota.","Kiki porta il cappello nero di Ada. Le sta un po' largo. Hélène dice che è giusto così: «Il cappello cresce con te».","{varano}","Il Registro torna nella Camera, sotto Firenze. Ma adesso ci sono due chiavi, e nessuno dei due può aprirla da solo. Beps dice che è il sistema di sicurezza di cui va più fiero. Kiki dice che è solo una scusa per vedersi."]}],"postcredit":["@cutscene:post_custodi"]},"cenere":{"title":"Cenere","subtitle":"Il Registro viene bruciato.","choice":"Cenere","choiceSub":"Lasciare che il Notaio accenda il fiammifero. Nessun nome sarà accusato. Nessun nome sarà ricordato.","lockedHint":"","req":"true","script":["beps: …Va bene, Varano.","kiki[sad]: Beps.","beps: Nessuno di noi ha il diritto di decidere per trecento persone. Nemmeno lui. Ma almeno così nessuno pagherà per i nonni.","varano[sad]: Grazie.","narr: Il fiammifero si accende al secondo tentativo. La carta antica brucia in fretta, come se non aspettasse altro.","@cutscene:fine_cenere"],"epilogues":[{"id":"cenere_insieme","if":"stat.legame>=18","text":["La cenere del Registro finisce nell'Arno, all'alba, davanti alla targa del '66.","Varano lascia Firenze una settimana dopo. Nessuno sa dove sia andato. Alla Banca del Giglio, la cassetta 11 viene chiusa.","Beps e Kiki non ne parlano più. Ma ogni 12 marzo comprano un libretto di Gluck da Monsieur Albert e lo leggono ad alta voce, i nomi che ricordano, quelli che non sono bruciati perché li hanno imparati a memoria.","Restano insieme. La cenere, dice Kiki, è anche concime."]},{"id":"cenere_soli","if":"true","text":["La cenere del Registro finisce nell'Arno, all'alba, davanti alla targa del '66.","Kiki torna a Parigi il giorno stesso. Non litigano. Semplicemente, qualcosa si è spezzato insieme alla carta.","Varano lascia Firenze. Beps torna ai suoi computer, che almeno non mentono.","Passano cinque anni. Poi una sera di pioggia, sul Lungarno, una donna col cappotto rosso si siede su una panchina bagnata."]}],"postcredit":["@cutscene:post_cenere"]},"segreto":{"title":"Il Diciottesimo Nome","subtitle":"Il primo ruolo condiviso di Orfeo.","choice":"Il Diciottesimo Nome","choiceSub":"Né luce né cenere né segreto. Scrivere due nomi in una riga sola, e cambiare le regole di Orfeo.","secret":true,"lockedHint":"","req":"stat.fiducia>=14 && stat.legame>=24 && stat.conoscenza>=36 && count.symbols>=7 && count.collectibles>=36 && flag.knows_18 && flag.eighteenth_written && flag.final_perfect","script":["kiki[tender]: Varano. Abbiamo già scelto, nella Camera. Lo spazio dopo il diciassettesimo. Ci abbiamo scritto due nomi.","beps: Il Diciottesimo non è un custode. Sono due. Nessuno deciderà più da solo cosa fare del Registro: né Orfeo, né il Ponte, né un notaio con i fiammiferi.","beps: Lo apriremo. Non tutto, non subito. Prima i nomi dei salvati, uno alla volta, con le loro famiglie. Poi, insieme a loro, gli altri.","varano[surprised]: …E mia nonna?","kiki[tender]: Sua nonna sarà il primo nome che leggeremo, notaio. Accanto a quello di suo nonno. Perché è la verità, e la verità è che erano tutti e due Varano.","narr: Il Notaio guarda la scatola di fiammiferi per un lungo momento. Poi la lancia nell'Arno.","varano[sad]: Quarant'anni. Bastava che qualcuno me lo dicesse in due.","@flag:varano_redento","@cutscene:fine_segreto"],"epilogues":[{"id":"segreto","if":"true","text":["Il 12 marzo, a Parigi, Orfeo si riunisce per la prima volta con diciotto sedie. L'ultima è una panca: c'è posto per due.","Il Registro viene aperto nome per nome, in tre anni, insieme alle famiglie. Il primo nome letto in pubblico è «Lina Varano». Aurelio legge il secondo: «Bruno Varano». Gli trema la voce solo alla fine.","Guido Sarti torna nella fotografia del 1944. Ottavia Ricci mette la foto di suo padre all'ingresso dell'Archivio. Hélène restituisce il cappello nero, che però resta appeso all'attaccapanni di Ada: nessuno, dicono tutti, è più Euridice da solo.","Beps e Kiki si sposano a giugno, al Caffè delle Logge. Tommaso fa i cappuccini con la cannella e lascia sul piattino di ognuno 500 lire, dal suo barattolo."]}],"postcredit":["@cutscene:post_segreto"]}},"credits":[["Un'avventura grafica di","b3pz"],["Storia e personaggi","Giuseppe & Kiki"],["Motore, sistemi, enigmi e scrittura","Claude Code (Anthropic) con b3pz"],["Illustrazioni finali","in produzione — vedi docs/ASSET_REQUIREMENTS.md"],["Grafica provvisoria","generata proceduralmente"],["Musica e suoni","sintesi procedurale provvisoria"],["Beps","Giuseppe"],["Kiki","Federica"],["Aurelio Varano","il Notaio"],["Ringraziamenti","Firenze, Parigi, Roma, Istanbul"],["E a","tutti quelli che non si voltano"]]},"cutscenes":{"_doc":"Cutscene come «illustrazione animata». Ogni inquadratura usa assets/cutscenes/<id>_<n>.(webp|jpg|png) se presente, altrimenti lo sfondo della scena indicata o una fotografia procedurale. cam: [x%, y%, zoom] da/a. fx: rain, dust, snow, embers, fog, light.","cutscenes":{"intro":{"music":"title","ambience":"rain","shots":[{"img":"assets/reference/cutscenes/florence_night.webp","scene":"c1_lungarno","title":"Firenze","sub":"OTTOBRE 2026","cam":{"from":[30,45,1.25],"to":[55,50,1.05]},"fx":["rain"],"dur":4200},{"scene":"c1_cantiere","text":"Durante alcuni lavori in un palazzo dell'Oltrarno è stata aperta una stanza murata.","cam":{"from":[70,40,1.3],"to":[55,55,1.05]},"fx":["dust"]},{"scene":"c1_studio","text":"Tra il materiale recuperato c'era un vecchio computer. Lo hanno portato in ufficio, dall'informatico della ditta: un ragazzo curioso che si chiama Giuseppe.","cam":{"from":[30,50,1.3],"to":[35,55,1.1]},"fx":["dust"],"figures":[{"id":"beps","x":980,"y":900,"s":1.05}]},{"img":"assets/reference/cutscenes/discovery_orfeo.webp","photo":"photo1944","photoOpts":{"half":false},"text":"Una cartella chiamata ORFEO. Una fotografia del 1944. Una lista di diciassette nomi. E una voce.","cam":{"from":[50,50,1.4],"to":[50,55,1]}}]},"c1_fine":{"music":"tender","shots":[{"scene":"c1_lungarno","text":"Quella notte Beps non dormì. Guardò la fotografia fino all'alba, e il volto graffiato guardò lui.","cam":{"from":[50,45,1],"to":[20,50,1.25]},"fx":["rain"]},{"img":"assets/cutscenes/cutscene_01_arrivo_in_citta.jpg","scene":"c2_gare","title":"Il treno delle 7:12","sub":"FIRENZE — PARIGI","cam":{"from":[50,50,1.2],"to":[50,45,1]},"fx":["light"],"figures":[{"id":"kiki","x":820,"y":900},{"id":"beps","x":1060,"y":900,"flip":true}]}]},"c2_fine":{"music":"roma","shots":[{"scene":"c2_quai","text":"Parigi li salutò con un tramonto che sembrava dipinto apposta. Kiki non si voltò a guardarlo.","cam":{"from":[40,50,1],"to":[70,45,1.2]}},{"scene":"c3_piazza","title":"Roma","sub":"IL GIORNO DOPO","cam":{"from":[50,40,1.25],"to":[50,50,1]},"fx":["dust"]}]},"c3_fine":{"music":"firenze","shots":[{"scene":"c3_osteria","text":"Pagarono le carbonare, lasciarono una mancia esagerata e presero il primo treno per Firenze.","cam":{"from":[50,50,1],"to":[60,55,1.2]},"figures":[{"id":"beps","x":1380,"y":920},{"id":"kiki","x":1560,"y":920,"flip":true}]},{"img":"assets/reference/cutscenes/lungarno_reunion.webp","scene":"c4_ponte","title":"Il ritorno","sub":"FIRENZE · DICEMBRE","cam":{"from":[50,45,1.2],"to":[50,50,1]},"fx":["fog"]}]},"c4_fine":{"music":"istanbul","shots":[{"img":"assets/reference/cutscenes/sigillo_together.webp","scene":"c4_grotta","text":"Uscirono da Boboli tenendosi per mano. Nessuno dei due ricordò, dopo, chi l'avesse presa per primo.","cam":{"from":[50,50,1],"to":[50,60,1.25]},"fx":["fog"]},{"scene":"c5_galata","title":"Istanbul","sub":"LA PORTA D'ORIENTE","cam":{"from":[70,40,1.3],"to":[50,50,1]}}]},"bacio":{"music":"tender","letterbox":true,"shots":[{"scene":"c5_tetto","cam":{"from":[50,45,1],"to":[50,50,1.35]},"fx":["light"],"figures":[{"id":"beps","x":900,"y":900},{"id":"kiki","x":1020,"y":900,"flip":true}],"dur":3800},{"color":"#0a0806","text":"Sotto di loro, Istanbul accende le sue luci. Nessuno dei due se ne accorge.","dur":3600}]},"c5_fine":{"music":"paris","shots":[{"scene":"c5_galata","text":"Selim li accompagnò al molo. Disse addio in sei lingue e in nessuna riuscì a finire la frase.","cam":{"from":[50,50,1],"to":[40,45,1.2]}},{"img":"assets/reference/cutscenes/arrival_paris.webp","scene":"c6_pont_neuf","title":"Orfeo","sub":"PARIGI · GENNAIO","cam":{"from":[50,40,1.2],"to":[50,50,1]},"fx":["snow"]}]},"c6_fine":{"music":"finale","shots":[{"scene":"c6_catacombe","text":"Uscirono dalle catacombe a Denfert-Rochereau, sotto la neve, alle dieci di sera. Il treno della notte era in orario. Per una volta.","cam":{"from":[50,50,1],"to":[70,50,1.25]},"fx":["fog"]},{"scene":"c7_cantiere","title":"L'ultima chiave","sub":"FIRENZE · LA NOTTE","cam":{"from":[50,50,1.3],"to":[50,50,1]},"fx":["dust"]}]},"c7_uscita":{"music":"finale","shots":[{"scene":"c7_camera","text":"Risalirono la scala con il Registro tra le braccia, a turno. Pesava come un mattone. Pesava più di un mattone.","cam":{"from":[50,50,1],"to":[20,40,1.3]},"fx":["embers"]},{"scene":"c7_alba","text":"Fuori, Firenze stava diventando rosa.","cam":{"from":[80,50,1.25],"to":[50,50,1]}}]},"fine_luce":{"music":"finale","shots":[{"img":"assets/cutscenes/cutscene_03_rivelazione_orfeo.jpg","scene":"c1_archivio","title":"La Luce","cam":{"from":[50,40,1.2],"to":[50,50,1]},"fx":["light","dust"]},{"photo":"photo1944","photoOpts":{"half":false},"text":"Il volto di Guido Sarti, ricostruito graffio per graffio, torna nella fotografia. Dopo cinquantanove anni, il Ponte è di nuovo al suo posto.","cam":{"from":[65,60,1.6],"to":[50,50,1]}}]},"fine_custodi":{"music":"finale","shots":[{"img":"assets/cutscenes/cutscene_06_ricerca_finale.jpg","scene":"c6_archivio","title":"I Custodi","cam":{"from":[50,45,1.2],"to":[50,50,1]},"fx":["dust"]},{"scene":"c2_appartamento","text":"Il cappello nero torna sull'attaccapanni di Ada. Accanto, da oggi, c'è anche un berretto da cantiere.","cam":{"from":[80,40,1.4],"to":[70,45,1.1]},"fx":["light"]}]},"fine_cenere":{"music":"mystery","shots":[{"scene":"c7_alba","title":"Cenere","cam":{"from":[30,55,1.2],"to":[20,50,1.4]},"fx":["embers"]},{"color":"#120c08","text":"La carta brucia in fretta. I nomi, un po' più piano.","fx":["embers"],"dur":4200}]},"fine_segreto":{"music":"tender","shots":[{"scene":"c7_alba","title":"Il Diciottesimo Nome","cam":{"from":[50,50,1],"to":[30,45,1.3]},"fx":["light"]},{"img":"assets/cutscenes/cutscene_02_scoperta_in_archivio.jpg","scene":"c7_camera","text":"Nella Ruota dei Nomi, dopo il XVII, c'è una riga larga il doppio. Ci sono due nomi, scritti con due penne diverse e una sola mano.","cam":{"from":[50,30,1.5],"to":[50,40,1.1]},"fx":["embers"]}]},"post_luce":{"music":"tender","shots":[{"scene":"c1_caffe","title":"Un anno dopo","cam":{"from":[50,50,1.2],"to":[50,50,1]},"figures":[{"id":"beps","x":860,"y":920},{"id":"kiki","x":1060,"y":920,"flip":true}]},{"scene":"c1_caffe","text":"Il giorno del matrimonio, tra i regali, c'è una busta senza mittente. Dentro, una fotografia: Beps e Kiki che escono dal Comune, sotto il riso.","cam":{"from":[40,50,1.3],"to":[55,45,1.1]}},{"img":"assets/reference/cutscenes/anonymous_envelope.webp","photo":"generic","photoOpts":{"woman":true,"marks":false},"text":"In un angolo della foto, un passo in disparte, c'è una donna col cappello nero. Sul retro, a matita: «Brava, Federica. — E.»","cam":{"from":[50,50,1],"to":[50,55,1.5]}}]},"post_custodi":{"music":"tender","shots":[{"scene":"c1_archivio","title":"Un anno dopo","text":"Il catalogo O, all'Archivio Storico, ha un cassetto nuovo. Ottavia lo chiama «il cassetto dei due».","cam":{"from":[20,45,1.3],"to":[25,50,1.05]}},{"photo":"generic","photoOpts":{"woman":false,"marks":false},"text":"Il Sigillo di Orfeo è di nuovo diviso. Non in quattro, stavolta: in due. Una metà la porta Beps, l'altra Kiki. Combaciano, ogni sera.","cam":{"from":[50,50,1.4],"to":[50,50,1]}}]},"post_cenere":{"music":"tender","shots":[{"scene":"c1_lungarno","title":"Il Lungarno","cam":{"from":[30,55,1.3],"to":[25,60,1.1]},"fx":["rain"],"figures":[{"id":"kiki","x":420,"y":940}]},{"scene":"c1_lungarno","text":"Un uomo con le mani in tasca le si siede accanto, senza ombrello. Le offre metà di una moneta da 500 lire, piegata a forza con le pinze. «L'altra metà», dice. Lei ride. Piove.","cam":{"from":[25,60,1.1],"to":[25,60,1.4]},"fx":["rain"],"figures":[{"id":"kiki","x":420,"y":940},{"id":"beps","x":560,"y":940,"flip":true}]}]},"post_segreto":{"music":"tender","shots":[{"img":"assets/reference/cutscenes/orfeo_reveal.webp","scene":"c6_archivio","title":"Registro di Orfeo","sub":"RUOLO XVIII","cam":{"from":[50,50,1.3],"to":[50,50,1]},"fx":["dust"]},{"color":"#e9dfc6","text":"«XVIII · Il Ponte e la Testimone, insieme. Giuseppe e Federica. Giurano il 12 marzo, per primi e per ultimi, in due.»","dur":6000},{"img":"assets/reference/cutscenes/anonymous_envelope_old.webp","scene":"c1_caffe","text":"Il giovedì dopo, al Caffè delle Logge, Tommaso trova sul piattino di una donna col cappello nero un biglietto: «Ottimo lavoro. Ora tocca a voi.» Nessuno l'ha vista entrare.","cam":{"from":[60,45,1.3],"to":[50,50,1]}}]}}}};
